       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"77bc8385-c1a1-5d63-ae85-5efe6c6ced65","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -استخدام أداة خشبية -إحداث إصابة -إقرار املدعى عليه -تنازل املدعي اخلاص عن حقه -تعزير باجللد - نصح وتوجيه يف مجلس احلكم .","document_number":"34246203","case_number":"34121195","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/19","year":"1434","subject":"اعتداء -ضرب -استخدام أداة خشبية -إحداث إصابة -إقرار املدعى عليه -تنازل املدعي اخلاص عن حقه -تعزير باجللد - نصح وتوجيه يف مجلس احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34246203 :‬تاريخه‪1434/06/19:‬هـ‬\n                    ‫رقم الدعوى‪34121195:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34638846‬تاريخه‪1434/07/18 :‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪ -‬اســتخدام أداة خشــبية ‪ -‬إحــداث إصابــة ‪ -‬إقــرار‬\n‫املدعــى عليــه ‪ -‬تنــازل املدعــي اخلــاص عــن حقــه ‪ -‬تعزيــر باجللــد ‪-‬‬\n                                  ‫نصــح وتوجيــه يف مجلــس احلكــم ‪.‬‬\n\n\n\n\n   ‫‪ -‬قوله صلى اهلل عليه وسلم ( كل املسلم على املسلم حرام دمه‬\n                                ‫وماله و عرضه ) ‪ .‬رواه مسلم ‪.‬‬\n ‫‪ -‬الشريعة اإلسالمية جاءت بحفظ الكليات اخلمس ومنها النفس‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه باالعتــداء عمــد ًا علــى املدعــي‬\n‫اخلــاص بضربــه علــى رأســه بــأداة خشــبية و التســبب يف إصابتــه ‪ ،‬حيــث‬\n‫انتهــى التحقيــق إلــى توجيــه االتهــام إلــى املدعــى عليــه باالعتــداء عمــد ًا‬\n‫علــى املدعــي اخلــاص بضربــه علــى رأســه ‪ ،‬بــأداة خشــبية ‪ ،‬والتســبب‬\n‫بإحــداث اإلصابــة ‪ ،‬املوصوفــة يف التقريــر الطبــي ‪ ،‬و طلــب املدعــي‬\n‫العــام تعزيــر املدعــى عليــه لقــاء مــا نســب إليــه ‪ ،‬أقــر املدعــى عليــه مبــا‬\n‫جــاء بدعــوى املدعــي العــام ‪ ،‬حضــر املدعــي اخلــاص و تنــازل عــن حقــه‬\n‫اخلــاص يف هــذه الدعــوى ‪ ،‬احلكــم بتعزيــر املدعــى عليــه باجللــد مبــا‬\n‫نســب إليــه يف دعــوى املدعــي العــام ‪ ،‬احلكــم بتنــازل املدعــي اخلــاص‬\n\n                                                                                         ‫‪252‬‬\n\f      ‫عــن حقــه اخلــاص يف هــذه الدعــوى ‪ ،‬جــرى نصــح و توجيــه املدعــى عليــه‬\n      ‫مبــا يناســب احلــال ‪ ،‬قــرر املدعــي عليــه القناعــة ‪ ،‬و املدعــي العــام قــرر‬\n      ‫اعتراضــه علــى احلكــم بــدون الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                          ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬مســاعد رئيــس احملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة يف يــوم األحــد ‪ .....‬الســاعة الثالثــة والربــع بعــد الظهــر‬\n      ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                             ‫أفتتحــت اجللســة األولــى بنـ ً‬\n      ‫احملكمــة اجلزائيــة برقــم (‪ ).....‬وتاريــخ ‪ ....‬واملقيــدة برقــم (‪ )....‬وتاريــخ‬\n      ‫‪ ....‬وفيهــا حضــر املدعــي العــام ‪ ...‬وقــدم الئحــة دعــواه ضــد ‪ .....‬البالــغ‬\n      ‫مــن العمــر ‪ 27‬عام ـ ًا باكســتناني اجلنســية برخصــة اإلقامــة رقــم (‪)....‬‬\n      ‫ا يف دعــواه‬   ‫املقبــوض عليــه بتاريــخ ‪ .......‬واملفــرج عنــه بتاريــخ ‪ ....‬قائ ـ ً‬\n      ‫إنتهــى التحقيــق إلــى توجيــه اإلتهــام للمدعــى عليــه ‪ ....‬باإلعتــداء عمــد ًا‬\n      ‫علــى املدعــي بضربــه علــى رأســه بــأداة خشــبية والتســبب يف إحــداث‬\n      ‫اإلصابــة املوصوفــة بالتقريــر الطبــي املرفــق ‪ ،‬وذلــك لألدلــة والقرائــن‬\n      ‫التاليــة‪ /1 -:‬مــا جــاء يف أقــوال املدعــى عليــه واملدونــة علــى صفحــة رقــم‬\n      ‫(‪ )10‬لفــة رقــم (‪ /2 .)1‬التقريــر الطبــي املنــوه عنــه املرفــق باملعاملــة لفــة‬\n      ‫رقــم (‪/3 .)4‬محضــر دوريــات األمــن املنــوه عنــه املرفــق باملعاملــة لفــة رقم‬\n      ‫(‪ .)5‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة وحيــث أن‬\n      ‫مــا أقــدم عليــه املدعــى عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعة له‬\n      ‫وزاجــرة لغيــره علمـ ًا بــأن احلــق اخلــاص الزال قائمـ ًا هكــذا إدعــى ولعــدم‬\n\n‫‪253‬‬\n\f‫حضــور املدعــى عليــه رغــم تبلغــه مبوعــد هــذه اجللســة كمــا يف محضــر‬\n‫اإلتصــال املــؤرخ يف ‪ ......‬املرفــق باملعاملــة لــذا أجلــت اجللســة إلــى يــوم‬\n‫اإلثنــن ‪ .......‬الســاعة الثانيــة وخمــس وأربعــن دقيقــة بعــد الظهــر ويف يوم‬\n‫االثنــن ‪ .....‬أفتتحــت اجللســة الثانيــة يف موعدهــا احملــدد الســاعة الثانيــة‬\n‫وخمــس وأربعــن دقيقــة بعــد الظهــر وفيهــا حضــر املتداعيــان وبتــاوة‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه احلاضــر بعــد التأكــد مــن هويته‬\n‫أجــاب بواســطة مترجــم احملكمــة ‪ .....‬أفغانــي اجلنســية مبوجــب رخصــة‬\n‫ا مــا ذكــره املدعــي العــام مــن إتهامــي باإلعتــداء‬  ‫االقامــة رقــم (‪ ).....‬قائـ ً‬\n‫عمــد ًا علــى املدعــى عليــه بضربــه علــى رأســه بــأداة خشــبية والتســبب‬\n‫يف إحــداث إصابــة بــه موصوفــة بالتقريــر الطبــي فهــذا صحيــح وأنــا‬\n‫ال إن شــاء‬ ‫نــادم علــى فعلــي وتائــب ولــن أعــود ملثــل مــا بــدر منــي مســتقب ً‬\n‫اهلل هــذه إجابتــي وأثنــاء اجللســة حضــر املدعــي اخلــاص ‪ .....‬باكســتاني‬\n‫عمــا لديــه قــال‬\n                 ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬وبســؤاله ّ‬\n‫بواســطة املترجــم املشــار إلــى إســمه وهويتــه أعــاه إن املدعــى عليــه ‪.....‬‬\n‫قــام باإلعتــداء علـ ّـي بالضــرب عمــد ًا علــى رأســي بــأداة خشــبية وأحــدث‬\n‫بــي إصابــة برأســي وقــد صــدر فيهــا تقريــر طبــي وإننــي أقــرر تنازلــي عنــه‬\n‫عمــا حلــق بــي مــن إصابــة وال أطالبــه بشــيء بخصوصهــا ال حاضــر ًا وال‬         ‫ّ‬\n‫ال هكــذا قــرر بحضــور وشــهادة املترجــم املشــار إليــه وكاتبــه‬          ‫مســتقب ً‬\n‫‪ .....‬والعســكري لدينــا ‪ ...‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬هــذا‬\n‫وقــد جــرى اإلطــاع علــى أقــوال املدعــى عليــه املدونــة بالصفحــة رقــم‬\n‫(‪ )10‬لفــة رقــم (‪ )1‬ومحضــر دوريــات األمــن املرفــق باملعاملــة لفــة رقــم‬\n‫(‪ )5‬فوجــدا كمــا ذكــر املدعــي العــام واإلطــاع علــى التقريــر الطبــي‬\n‫املرفــق باملعاملــة لفــة رقــم (‪ )4‬الصــادر مــن مستشــفى ‪ ......‬برقــم (‪)46‬‬\n\n\n                                                                                           ‫‪254‬‬\n\f      ‫وتاريــخ ‪ .....‬ومفــاده إصابــة املدعــي ‪ ......‬بجــرح قطعــي ‪3‬ســم يف فــروة‬\n      ‫ـاء علــى مــا تقــدم مــن ســماع الدعوى‬ ‫الــرأس ومــدة الشــفاء ســبعة أيــام فبنـ ً‬\n      ‫واإلجابــة ومــا قــرره الطرفــان ونظــر ًا إلــى أن املدعــى عليــه صــادق علــى‬\n      ‫مــا جــاء يف دعــوى املدعــي العــام والشــريعة اإلســامية جــأت بحفــظ‬\n      ‫الكليــات اخلمــس ومنهــا النفــس ويف احلديــث (كل املســلم علــى املســلم‬\n      ‫حــرام دمــه ومالــه وعرضــه) رواه مســلم ونظــر ًا إلــى أن املدعــى عليــه‬\n      ‫أعلــن توبتــه وأظهــر ندامتــه وخللـ ّـو صحيفتــه مــن الســوابق اجلنائيــة وطمعـ ًا‬\n      ‫يف اســتصالحه ونظــر ًا إلــى أن املدعــي اخلــاص تنــازل عــن حقــه اخلــاص‬\n      ‫جتــاه املدعــى عليــه وألن اإلصابــة التــي حلقــت باملدعــي اخلــاص ليســت‬\n      ‫بليغــة حســبما جــاء بالتقريــر الطبــي املشــار إليــه وجلميــع مــا تقــدم قــررت‬\n                                                                                  ‫اآلتــي ‪-:‬‬\n                                                                          ‫أو ًال ‪ /‬ثبــت لـ ّ‬\n      ‫ـدي إدانــة املدعــى عليــه ‪ .....‬باإلعتــداء عمــد ًا علــى املدعــي‬\n      ‫بضربــه علــى رأســه بــأداة خشــبية والتســبب يف إحــداث اإلصابــة‬\n      ‫ـدي تنــازل املدعــي اخلــاص ‪ ....‬عــن‬ ‫املوصوفــة بالتقريــر الطبــي وثبــت لـ ّ‬\n      ‫حقــه اخلــاص عــن املدعــى عليــه بخصــوص هــذه الدعــوى وال يطالبــه فيها‬\n      ‫ال ثاني ـاً‪ /‬جلــد املدعــى عليــه ‪ .....‬ثالثــن‬‫بشــيء ال حاضــر ًا وال مســتقب ً‬\n      ‫جلــدة دفعــة واحــدة وأخــذ التعهــد املشــدد عليــه وإنــذاره مــن العــود ملثــل‬\n      ‫ال تعزيــر ًا لــه علــى مــا أديــن بــه املنصــوص عليــه يف‬\n                                                                  ‫مــا بــدره منــه مســتقب ً‬\n      ‫أو ًال مــن اإلعتــداء عمــد ًا علــى املدعــي بضربــه علــى رأســه بــأداة خشــبية‬\n      ‫والتســبب يف إحــداث اإلصابــة بــه املوصوفــة بالتقريــر الطبــي هــذا مــا‬\n      ‫ظهــر لــي وبــه حكمــت ألجــل احلــق العــام وجــرى نصــح وتوجيــه املدعــى‬\n      ‫عليــه مبــا يناســب املقــام وبإعــان احلكــم قــرر املدعــى عليــه القناعــة‬\n      ‫بــه وأبــدى املدعــي العــام اإلعتــراض علــى احلكــم وطلــب رفعــه الــى‬\n\n\n‫‪255‬‬\n\f‫محكمــة اإلســتئناف بــدون الئحــة إعتراضيــة وأقفلــت اجللســة يف متــام‬\n‫الســاعة الثالثــة بعــد الظهــر وعلــى مــا تقــدم حصــل التوقيــع وصلــى اهلل‬\n         ‫وســلم علــى نبينــا محمــد وعلــى الــه وصحبــه أجمعــن حــرر يف ‪.....‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ -:‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ ...‬وتاريــخ ‪ ...‬املرفــق بهــا‬\n‫القرار الصادر مـن فضيلة الشيخ ‪ ....‬مساعد رئيس باحملكمة اجلزائية‬\n‫باملدينــة املنــورة برقــم ‪ ......‬وتـ ـ ـ ـ ــاريخ ‪ .....‬الـمتضم ــن دعــوى املدعــي العام‬\n‫ضــد ‪..... /‬باكســتاني اجلنســية املتهــم يف اعتــداء‪ ،‬احملكــوم فيــه مبــا‬\n‫دون بباطــن القــرار ‪ ،‬وبدراســة القــرار وصــورة ضبطــه قررنــا املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آل ـ ـ ــه‬\n                                                                        ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                              ‫‪256‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":252,"source_page_end":256,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b4140f0001caa24a7181dca0317b17727c8bf48f7a34973618b4ae0a43ccdaa8","normalized_text_hash":"ae5ec8568deb476c34ccfe820455d6b345bda40a8efa88c5626770a43ea17a81","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p252-34246203"},{"id":"5aa7c300-fe71-5924-9aef-6f7ff35edc2d","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -التسبب بإصابة املدعية -رد دعوى املدعي العام لعدم وجود بينة -كبر سن املدعى عليها -إخاء سبيل املدعى","document_number":"34187653","case_number":"34121728","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/14","year":"1434","subject":"اعتداء -ضرب -التسبب بإصابة املدعية -رد دعوى املدعي العام لعدم وجود بينة -كبر سن املدعى عليها -إخاء سبيل املدعى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34187653:‬تاريخه‪1434/04/14:‬هـ‬\n                          ‫رقم الدعوى‪34121728:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34246700‬تاريخه‪1434/06/20 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬التســبب بإصابــة املدعيــة ‪ -‬رد دعــوى املدعــي العــام‬\n      ‫لعــدم وجــود بينــة ‪ -‬كبــر ســن املدعــى عليهــا ‪ -‬إخــاء ســبيل املدعــى‬\n                                                                         ‫عليهــا ‪.‬‬\n\n\n\n\n                                ‫‪ -‬قاعدة ( األصل البراءة حتى يثبت خالفها ) ‪.‬‬\n                                     ‫‪ -‬وما أشار إليه القاضي يف تسبيب احلكم ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليهــا بضرب امرأة بحــذاء على عينها‬\n      ‫اليمنــى ممــا أدى إلــى إصابتهــا ‪ُ ،‬أبلغــت الشــرطة مــن أحــد األشــخاص‬\n      ‫عــن وجــود مضاربــة يف أحــد احلدائــق ‪ ،‬وباالنتقــال إلــى املوقــع وجــد‬\n      ‫املبلــغ‪ ،‬وأفــاد أن املدعــى عليهــا قامــت بضــرب زوجتــه بحــذاء علــى‬\n      ‫عينهــا اليمنــى ‪ ،‬والتســبب بإصابتهــا ‪ ،‬و طلــب املدعــي العــام تعزيــر‬\n      ‫املدعــى عليهــا لقــاء مــا نســب إليهــا ‪ ،‬أنكــرت املدعــى عليهــا مــا جــاء‬\n      ‫بدعــوى املدعــي العــام‪ ،‬ثــم جــرى اإلطــاع علــى أوراق املعاملــة التــي‬\n      ‫قدمهــا املدعــي ‪ ،‬وباالطــاع عليهــا لــم يوجــد للمدعــي العــام بينــة علــى‬\n      ‫دعــواه كمــا قــرر انــه ليــس لديــه مــا يقدمــه مــن بينــات ســوى محضــر‬\n      ‫التعــرف مــن املدعــى عليهــا ‪ ،‬احلكــم بــرد دعــوى املدعــي العــام ضــد‬\n\n‫‪257‬‬\n\f‫املدعــى عليهــا و إخــاء ســبيلها لعــدم ثبــوت الدعــوى ‪ ،‬ارتضــت املدعــى‬\n‫عليهــا احلكــم واملدعــي العــام قــرر اعتراضــه علــى احلكــم بــدون الئحــة‬\n                ‫اعتراضيــه ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ ...‬وتاريــخ‪ ...‬املقيــدة باحملكمــة برقــم ‪....‬وتاريخ‬\n‫‪ ...‬ففــي يــوم الثالثــاء املوافــق ‪ ....‬افتتحــت اجللســة الســاعة الســاعة‬\n‫الواحــدة والنصــف ظهــر ًا وفيهــا قــدم املدعــي العــام ‪ ... /‬دعــواه علــى ‪/‬‬\n‫‪ 61 ، .....‬عام ـ ًا ‪ ،‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم (‪)....‬‬\n‫أميــة ‪ ،‬متســببة ‪ ،‬تقيــم مبدينــة الريــاض ‪ ،‬أوقفــت بتاريــخ ‪ ..‬بســجن‬\n‫النســاء ومــدد إيقافهــا مبوجــب أمــر متديــد التوقيــف رقــم (‪ )....‬وتاريــخ ‪...‬‬\n‫اســتناد ًا للمــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬حيــث إنــه بتاريخ‬\n‫‪ ...‬تســلم مركــز شــرطة ‪ ....‬تقريــر إحــدى فــرق الدوريــات األمنيــة رقــم‬\n‫(‪ )...‬واملتضمــن تلقيهــا بالغ ـ ًا مــن ‪ .... /‬عــن وجــود مضاربــة يف حديقــة‬\n‫‪ ..........‬علــى شــارع ‪ ............‬وباالنتقــال للموقــع وجــد املبلــغ وأفــاد بقيــام‬\n‫امــرأة تدعــى أم ‪( ...‬املتهمــة) بضــرب زوجتــه املجنــي عليهــا ‪ ... /‬بحــذاء‬\n‫علــى عينهــا اليمنــى والتســبب يف إصابتهــا ومت إســعافها مــن قبــل املدعــو‬\n‫‪ .... /‬وذلــك بنقلهــا للمستشــفى ‪ .‬وبســماع أقــوال املجنــي عليهــا ‪/ ....‬‬\n‫أفــادت بأنهــا أثنــاء تواجدهــا يف حديقــة ‪ ............‬بحــي ‪............‬وبرفقتهــا‬\n‫ابنيهــا ‪ ...‬و‪...‬أبنــاء ‪ ...‬شــاهدت املدعــى عليهــا تقــوم بضــرب ابنهــا الصغيــر‬\n‫‪ ...‬بحذائهــا علــى ظهــره وصــدره فحضــرت إليهــا وســألتها عــن ســبب‬\n\n                                                                                            ‫‪258‬‬\n\f      ‫قيامهــا بذلــك ثــم حصلــت مشــادة كالميــة بينهــا وبــن املدعــى عليهــا‬\n      ‫وقيامهــا برميهــا بحــذاء أصــاب عينهــا اليمنــى وصــدر بحقهــا تقرير طبي‬\n      ‫برقــم (بــدون) وتاريــخ ‪2012/10/24‬م مــن مستشــفى ‪........................‬‬\n      ‫واملتضمــن بتشــخيص حالتهــا تبــن خلــع يف عدســة العــن اليمنــى ومتــزق‬\n      ‫طبقــة العــن مصحــوب بــدم حتــت الشــبكية وحفــرة بقعيــة مغلقــة يف‬\n      ‫العــن اليمنــى ولــم حتــدد مــدة الشــفاء ‪ .‬وبتاريــخ ‪ ...‬قبــض علــى املتهمــة‬\n      ‫مــن قبــل شــرطة ‪ ............‬وإحالتهــا إلــى ســجن النســاء‪ .‬وباســتجواب‬\n      ‫املدعــى عليهــا ‪..... /‬أنكــرت ضــرب املجنــي عليهــا ‪ ....‬وأنكــرت‬\n      ‫معرفتهــا بهــا وأنــه لــم يســبق أن رأتهــا وأقــرت بحضورهــا وابنهــا حلديقــة‬\n      ‫‪ ............‬بــن الفينــة واألخــرى ‪ .‬وبســماع أقــوال ابــن املدعــى عليهــا ‪....‬‬\n      ‫‪ /‬أفــاد بأنــه يحضــر حلديقــة ‪ ............‬مــع أمــه املدعــى عليهــا وأخواتــه‬\n      ‫الصغــار شــبه يومــي وأنــه شــاهد يف إحــدى األيــام مضاربــة باأليــدي بــن‬\n      ‫امرأتــن متغطيتــن أمــام بســطة أمــه ثــم اتصلــت عليــه أمــه وطلبــت منــه‬\n      ‫احلضــور لهــا وغــادروا احل ــديقة ذاهبــن إل ــى منزلهــم ‪ .‬وبســماع أقــوال‬\n      ‫ابنــة املجنــي عليهــا ‪ / ....‬أفــادت بأنهــا أثنــاء تواجدهــا بحديقــة ‪............‬‬\n      ‫مــع أمهــا املجنــي عليهــا وأخيهــا ‪ ....‬حصلــت مشــادة كالميــة بــن أمهــا‬\n      ‫واملدعــى عليهــا بســبب قيــام املدعــى عليهــا بضــرب أخيهــا ‪ ....‬وأنهــا رأت‬\n      ‫املدعــى عليهــا تقــوم برمــي حــذاء علــى أمهــا وأصابــت عينهــا اليمنــى‬\n      ‫وســقطت مغشــي ًا عليهــا ثــم طلبــت مــن أحــد األشــخاص إســعافها فقــام‬\n      ‫بإركابهــا وأمهــا املجنــي عليهــا والذهــاب بهمــا إلى املستشــفى ‪ .‬وبســماع‬\n      ‫أقــوال الشــاهد ‪ / ....‬أفــاد بأنــه أثنــاء تواجــده بحديقــة ‪ ............‬شــاهد‬\n      ‫مشــادة كالميــة بــن مجموعــة مــن النســاء كبيــرات يف الســن فذهــب‬\n      ‫إلبــاغ الهيئــة بذلــك وأثنــاء رجوعــه شــاهد املجنــي عليهــا تصــرخ ومعهــا‬\n\n\n‫‪259‬‬\n\f‫ابنتهــا وطلبــا منــه أن يقــوم بإيصالهمــا إلــى مستشــفى ‪........................‬‬\n‫للعيــون ‪ .‬وبعــرض املدعــى عليهــا علــى املجنــي عليهــا ‪..... /‬ومعهــا امــرأة‬\n‫مشــابهة لهــا يف الشــكل اســتطاعت التعــرف عليهــا ‪ .‬ومبواجهــة املدعــى‬\n‫ال منهمــا علــى أقوالهــا وكانــت‬     ‫عليهــا باملجنــي عليهــا ‪ .../‬أصــرت ك ً‬\n‫املجنــي عليهــا تســرد وقائــع املضاربــة وأن املدعــى عليهــا هــي مــن قــام‬\n‫بضربهــا وتطلــب حقهــا الشــرعي منهــا بينمــا املدعــى عليهــا تطلــب ميــن‬\n‫املجنــي عليهــا ‪ .‬وأســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليهــا‬\n‫‪ ..... /‬بضــرب املجنــي عليهــا ‪ ....‬بحــذاء علــى عينهــا اليمنــى ممــا أدى‬\n‫إلــى إصابتهــا باإلصابــات املوصوفــة بالتقريــر الطبــي املشــار إليــه ‪ .‬وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪1 :‬ـ تقريــر الدوريــات األمنيــة املنــوه عنــه املرفــق‬\n                                                               ‫علــى اللفــة رقــم (‪. )..‬‬\n‫‪2‬ـ مــا جــاء يف أقــوال املدعــى عليهــا املنــوه عنهــا املدونــة علــى الصفحــة‬\n‫رقــم (‪ )...‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪3 . )...‬ـ مــا جــاء يف ســماع‬\n‫أقــوال ‪ ...‬ابــن املدعــى عليهــا املنــوه عنهــا املدونــة علــى الصفحــة رقــم (‪)...‬‬\n‫مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪4 . )..‬ـ مــا جــاء يف ســماع أقــوال ‪.....‬‬\n‫ابنــه املجنــي عليهــا املنــوه عنهــا املدونــة علــى الصفحــة رقــم (‪ )..‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــة رقــم (‪5 . )..‬ـ ماجــاء يف ســماع أقــوال ‪ .....‬املنــوه عنهــا‬\n‫املدونــة علــى الصفحــة رقــم (‪ )..‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪. )..‬‬\n‫‪6‬ـ محضــر العــرض والتعــرف علــى املدعــى عليهــا مــن قبــل املجنــي عليهــا‬\n‫املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )..‬مــن دفتــر التحقيــق املرفــق‬\n‫لفــة رقــم (‪ . )..‬وبالبحــث عــن ســوابقها تبــن عــدم وجــود ســوابق جنائيــة‬\n‫مســجلة عليهــا حتــى تاريخــه ‪ .‬وحيــث إن مــا أقدمــت عليهــا املذكــورة‬\n‫فعــل معاقــب عليــه شــرع ًا لــذا أطلــب احلكــم عليهــا بعقوبــة تعزيريــة لقــاء‬\n\n\n                                                                                            ‫‪260‬‬\n\f      ‫مــا أســند إليهــا علم ـ ًا بــأن احلــق اخلــاص مــازال قائم ـ ًا ‪ .‬وبعــرض دعــوى‬\n      ‫املدعــي العــام علــى املدعــى عليهــا احلاضــرة يف هــذه اجللســة واملعــرف‬\n      ‫بهــا مــن قبــل ولدهــا احلاضــر معهــا ‪ ، ... /‬حامــل بطاقــة الهويــة الوطنيــة‬\n      ‫رقــم ‪ ....‬أجابــت قائلــة ‪ :‬مــا جــاء بدعــوى املدعــي العــام غيــر صحيــح وأنــا‬\n      ‫ال أعــرف هــذه املــرأة املجنــي عليهــا ولــم أضربهــا وليــس بينــي وبينهــا‬\n      ‫أي عــداوة وجميــع مــا جــاء يف الدعــوى جتاهــي غيــر صحيــح ‪ ،‬هكــذا‬\n      ‫أجابــت‪ .‬بعــد ذلــك قــررت رفــع اجللســة لدراســة أوراق املعاملــة إلــى يــوم‬\n      ‫األحــد املوافــق ‪ ...‬الســاعة العاشــرة صباحـ ًا ‪ ،‬واختتمــت اجللســة يف متــام‬\n      ‫الســاعة الثانيــة ظهــر ًا ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ ...‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم‬\n      ‫األحــد املوافــق ‪ ...‬فتحــت اجللســة يف متــام الســاعة الواحــدة ظهــر ًا وفيهــا‬\n      ‫حضــرت املدعــى عليهــا وقــد جــرى منــا الرجــوع ألوراق املعاملــة لإلطــاع‬\n      ‫علــى البينــات التــي قدمهــا املدعــي العــام وباالطــاع عليهــا ودراســتها لــم‬\n      ‫أجــد فيهــا مــا يــدل علــى صحــة دعــوى املدعــي العــام ولــم أجــد أي قرينــة‬\n      ‫ســوى محضــر تعــرف املجنــي عليهــا علــى املدعــى عليهــا فقــط ‪ .‬بعــد‬\n      ‫ذلــك ســألت املدعــي العــام ‪ :‬هــل لديــه زيــادة بينــة ؟ فقــال ‪ :‬ليــس لــدي‬\n      ‫ســوى مــا قدمــت ‪ .‬فبنــاء علــى مــا تقــدم ومبــا أنــه ال بينــة لــدى املدعــي‬\n      ‫العــام علــى دعــواه ومبــا أن األصــل عــدم صحــة هــذه الدعــوى واألصــل‬\n      ‫البــراءة حتــى يثبــت خالفهــا ومبــا أن مجــرد محضــر التعــرف مــن قبــل‬\n      ‫املجنــي عليهــا ال يكفــي التهامهــا الســيما مــع كبــر ســن املدعــى عليهــا‬\n      ‫إذ أن عمرهــا قــد جتــاوز الســتني كمــا يتضــح ذلــك مــن أوراق املعاملــة‬\n      ‫وكــرت العائلــة العائــد لزوجهــا إضافــة إلــى عــدم وجــود ســوابق لــدى‬\n      ‫املدعــى عليهــا ‪ .‬لذلــك كلــه فقــد حكمــت بــرد دعــوى املدعــي العــام‬\n\n\n‫‪261‬‬\n\f‫جتــاه املدعــى عليهــا وأخليــت ســبيل املدعــى عليهــا وقــررت إطالقهــا‬\n‫بالكفالــة احلضوريــة بنــاء علــى املــادة (‪ )216‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة ‪ .‬وبعــرض ذلــك علــى املدعــى عليهــا واملدعــي العــام قــررت‬\n‫املدعــى عليهــا القناعــة باحلكــم وقــرر املدعــي العــام االعتــراض بــدون‬\n‫الئحــة اعتراضيــة ‪ .‬واختتمــت اجللســة يف متــام الســاعة الواحــدة والنصــف‬\n‫ظهــر ًا ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                                       ‫حــرر يف ‪...‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعــة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ ...‬وتاريــخ ‪ ...‬املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ....‬املســجل‬\n‫برقــم ‪ ...‬وتاريــخ ‪ ...‬اخلــاص بدعــوى املدعــي العــام ضــد‪ ...... /‬يف قضيــة‬\n‫مضاربــة علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫نقــرر باألكثريــة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى إثبــات‬\n‫ال حســب النظــام واهلل املوفــق‬    ‫اإلدانــة مــن عدمهــا قبــل احلكــم مســتقب ً‬\n                       ‫صلــى اهلل علــى نبينــا محمــد و آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪262‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":257,"source_page_end":262,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"315b24d15c35c5f04e0a52a4be8c82956ede12eac827d50045610d9e01340de8","normalized_text_hash":"676ff8e0911c23e19d8032f748ca1f9cec2bfbc0626d730ea88b9cee64159e09","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p257-34187653"},{"id":"9cbef568-8c67-5c44-be24-13f2294f18f6","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -تهديد رجل أمن -التعدي بالقول على رجل أمن -اعتداء بالضرب على أحد املوقوفن -التعدي بألفاظ غير الئقة إحداث فوضى بداخل التوقيف -إقرار املدعى عليه مبا جاء بدعوى املدعي العام -التعزير باجللد .","document_number":"34295817","case_number":"34137366","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/14","year":"1434","subject":"اعتداء -ضرب -تهديد رجل أمن -التعدي بالقول على رجل أمن -اعتداء بالضرب على أحد املوقوفن -التعدي بألفاظ غير الئقة إحداث فوضى بداخل التوقيف -إقرار املدعى عليه مبا جاء بدعوى املدعي العام -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34295817 :‬تاريخه‪1434/08/14:‬هـ‬\n                         ‫رقم الدعوى‪34137366:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34332145‬تاريخه‪1434/10/18 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬تهديــد رجــل أمــن ‪ -‬التعــدي بالقــول علــى رجــل‬\n      ‫أمــن ‪ -‬اعتــداء بالضــرب علــى أحــد املوقوفــن ‪ -‬التعــدي بألفــاظ غيــر‬\n      ‫الئقــة ـ إحــداث فوضــى بداخــل التوقيــف ‪ -‬إقــرار املدعــى عليــه مبــا جــاء‬\n                                        ‫بدعــوى املدعــي العــام ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n\n      ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                 ‫مالــه و عرضــه ) راوه مســلم ‪.‬‬\n      ‫‪ -‬الشــريعة اإلســامية جــاءت بحفــظ الكليــات اخلمــس منهــا النفــس‬\n                                                                       ‫والعــرض ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بتهديــد رجــل أمــن والتعــدي‬\n      ‫عليــه بألفــاظ غيــر الئقــة و االعتــداء بالضــرب علــى أحــد املوقوفــن‬\n      ‫أثنــاء ايقافــه ‪ ،‬انتهــى التحقيــق إلــى اتهــام املدعــى عليــه بذلــك وبإحــداث‬\n      ‫فوضــى بداخــل التوقيــف ‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى عليــه‬\n      ‫لقــاء مــا نســب إليــه‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــي‬\n      ‫العــام‪ ،‬صــدر احلكــم بتعزيــر املدعــى عليــه باجللــد لقــاء مــا نســب إليــه‬\n      ‫يف دعــوى املدعــي العــام‪ ،‬قــرر املدعــى عليــه و املدعــي العــام اعتراضهمــا‬\n\n‫‪263‬‬\n\f‫علــى احلكــم بــدون الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬مســاعد رئيــس احملكمــة اجلزائيــة‬\n‫باملدينة املنورة يف يوم اإلثنني ‪ .....‬أفتتحت اجللســة األولى يف متام الســاعة‬\n‫ـاء علــى املعاملــة احملالة إلينــا من فضيلة رئيس‬      ‫الثانيــة والنصــف ظهــر ًا بنـ ً‬\n‫احملكمــة اجلزائيــة باملدينــة املنــورة برقــم (‪ )....‬وتاريــخ ‪ .....‬واملقيــدة برقــم‬\n‫(‪ )....‬وتاريــخ ‪ .....‬وفيهــا حضــر املدعــي العــام ‪ .....‬وقــدم الئحــة دعــواه‬\n‫ضــد ‪ .....‬البالــغ مــن العمــر (‪ )26‬عامـ ًا ســعودي اجلنســية بالســجل املدنــي‬\n‫ا‬\n‫رقــم (‪ )......‬املقبــوض عليــه بتاريــخ ‪ ....‬واملوقــوف بالســجن العــام‪ .‬قائ ـ ً‬\n‫يف دعــواه إنتهــى التحقيــق إلــى إتهــام املدعــى عليــه بتهديــد رجــل أمــن‬\n‫والتلفــظ عليــه بألفــاظ غيــر الئقــة واإلعتــداء بضــرب املوقــوف ‪... /‬‬\n‫باحلــذاء والتلفــظ علــى املواقيــف بألفــاظ غيــر الئقــة وإحــداث فوضــى‬\n‫بداخــل التوقيــف‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪ /1 -:‬مــا ورد بأقــوال‬\n‫املدعــى عليــه املدونــة علــى الصفحــة رقــم (‪ )2،1‬مــن ملــف التحقيــق لفــة‬\n‫رقــم (‪ /2 .)6‬محضــر خفيــر التوقيــف املرفــق باملعاملــة لفــة رقــم (‪)2‬‬\n‫وأقوالــه املدونــة علــى الصفحــة رقــم (‪ )15‬مــن ملــف اإلســتدالل لفــة رقــم‬\n‫(‪ /3 .)1‬أقــوال املواقيــف املدونــة علــى الصفحــة رقــم (‪)12،11،10،9‬‬\n‫مــن ملــف اإلســتدالل لفــة رقــم (‪ .)1‬وبالبحــث عــن ســوابقه لــم يعثــر لــه‬\n‫علــى ســوابق مســجلة باســمه‪ ،‬وحيــث أن مــا اقــدم عليــه املدعــى عليــه‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب ‪ /1 -:‬إثبــات مــا أســند إليه‪.‬‬\n‫‪ /2‬احلكــم عليــه بعقوبــة تعزيريــة‪ .‬علمـ ًا أن احلــق اخلــاص مــا زال قائمــا‪،‬‬\n‫هكــذا إدعــى ولــم يحضــر املدعــى عليــه رغــم طلبــه بخطابنــا رقــم ‪.....‬‬\n\n                                                                                            ‫‪264‬‬\n\f      ‫وتاريــخ ‪ .....‬املوجــه إلــى مديــر شــعبة امــن احملاكــم الشــرعية وقــد وردنــا‬\n      ‫خطــاب مديــر شــعبة أمــن احملاكــم الشــرعية برقــم (‪)5/358/22‬‬\n      ‫وتاريــخ ‪ ......‬املتضمــن بــأن املدعــى عليــه غيــر موقــوف يف الســجن العــام‬\n      ‫لــذا جــرى رفــع اجللســة إلــى يــوم األربعــاء ‪ ......‬وأمــرت بالكتابــة إلــى‬\n      ‫اجلهــة املختصــة إلحضــار املدعــى عليــه يف موعــد اجللســة املشــار إليــه‬\n      ‫أعــاه وأفهمــت بــه املدعــي العــام ويف يــوم األربعــاء ‪ .....‬أفتتحــت اجللســة‬\n      ‫الثانيــة يف موعدهــا احملــدد الســاعة الثانيــة وخمــس وأربعــن دقيقــة‬\n      ‫بعــد الظهــر وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه وقــد‬\n      ‫ســبق الكتابــة إلــى مركــز شــرطة ‪ .....‬بخطابنــا رقــم (‪ )....‬وتاريــخ ‪.....‬‬\n      ‫املتضمــن إحضــار املدعــى عليــه يف موعــد هــذه اجللســة ولــم يتــم إحضــاره‬\n      ‫ولــم تردنــا اإلفــادة علــى خطابنــا املشــار إليــه حتــى تاريخــه لــذا أجلــت‬\n      ‫اجللســة إلــى يــوم اإلثنــن ‪ .....‬الســاعة الثالثــة بعــد الظهــر وأفهمــت بــه‬\n      ‫املدعــي العــام وأمــرت بالكتابــة إلــى اجلهــة املختصــة إلحضــار املدعــى‬\n      ‫عليــه يف املوعــد احملــدد أعــاه واإلفــادة عــن خطابنــا الســابق ويف يــوم‬\n      ‫االثنــن ‪ ......‬افتتحــت اجللســة الثالثــة يف موعدهــا احملــدد الســاعة الثالثــة‬\n      ‫بعــد الظهــر وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه وقــد‬\n      ‫ســبق الكتابــة إلــى مركــز شــرطة ‪ .....‬بخطابنــا رقــم (‪ ).....‬وتاريــخ ‪......‬‬\n      ‫وباخلطــاب التعقيبــي رقــم (‪ )....‬وتاريــخ ‪....‬إلحضــار املدعــى عليــه ولــم يتــم‬\n      ‫إحضــاره ولــم تردنــا اإلفــادة علــى اخلطابــات املشــار إليهــا حتــى تاريخــه‬\n      ‫لــذا أجلــت اجللســة إلــى يــوم اإلثنــن ‪ ...‬الســاعة الثالثــة والربــع بعــد الظهــر‬\n      ‫وأفهمــت بــه املدعــي العــام وأمرت بالكتابة إلــى اجلهة املختصة إلحضار‬\n      ‫املدعــى عليــه يف املوعــد احملــدد أعــاه واإلفــادة عــن املخاطبــات الســابقة‬\n      ‫ويف يوم اإلثنني ‪ ......‬افتتحت اجللســة الرابعة يف موعدها احملدد الســاعة‬\n\n\n‫‪265‬‬\n\f‫الثالثــة والربــع بعــد الظهــر وفيهــا حضر املدعي العــام ولم يحضر املدعى‬\n‫عليــه وقــد ســبق الكتابــة إلــى مركــز شــرطة ‪ .....‬بخطابنــا رقــم (‪).....‬‬\n‫وتاريــخ ‪ .....‬وباخلطابــن التعقيبيــن رقــم (‪ ).....‬وتاريــخ ‪ .....‬ورقــم (‪)......‬‬\n‫وتاريــخ ‪ .....‬إلحضــار املدعــى عليــه ولــم يتــم إحضــاره ولــم تردنــا اإلفــادة‬\n‫علــى املخطابــات املشــار إليهــا حتــى تاريخــه لــذا أجلــت اجللســة إلــى يــوم‬\n‫اإلثنــن ‪ ....‬الســاعة الثالثــة بعــد الظهــر وأفهمــت بــه املدعــي العــام وأمــرت‬\n‫بالكتابــة إلــى اجلهــة املختصــة إلحضــار املدعــى عليــه يف املوعــد احملــدد‬\n                                     ‫أعــاه واإلفــادة عــن املخاطبــات الســابقة ‪.‬‬\n‫ويف يوم االثنني ‪ ......‬افتتحت اجللسة اخلامسة يف موعدها احملدد الساعة‬\n‫الثالثــة بعــد الظهــر وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه‬\n‫وقــد ســبق الكتابــة إلــى مركــز شــرطة ‪ .....‬بخطابنــا رقــم (‪ )....‬وتاريــخ‬\n‫‪ .....‬وباملخاطبــات التعقيــب رقــم (‪ ).......‬وتاريــخ ‪ .....‬ورقــم (‪ ).....‬وتاريــخ‬\n‫‪ ......‬و رقــم (‪ )......‬وتاريــخ ‪ .....‬إلحضــار املدعــى عليــه ولــم يتــم إحضــاره‬\n‫ولــم تردنــا اإلفــادة علــى املخطابــات املشــار إليهــا حتــى تاريخــه لــذا أجلــت‬\n‫اجللســة إلــى يــوم الســبت ‪......‬الســاعة الثانيــة عشــر ظهــر ًا وأفهمــت بــه‬\n‫املدعــي العــام وأمــرت بالكتابــة إلــى اجلهــة املختصــة إلحضــار املدعــى‬\n‫عليــه يف املوعــد احملــدد أعــاه واإلفــادة عــن املخاطبــات الســابقة ويف‬\n‫يــوم الســبت ‪ .....‬أفتتحــت اجللســة السادســة يف موعدهــا احملــدد الســاعة‬\n‫الثانيــة عشــر ظهــر ًا وفيهــا حضــر املدعــي العــام واملدعــى عليــه ‪ ....‬وبعــد‬\n‫التأكــد مــن هويتــه املشــار إليهــا أعــاه جــرى تــاوة دعــوى املدعــي العــام‬\n‫ا مــا ذكــره املدعــي العــام مــن إتهامــي بتهديــد رجــل‬   ‫عليــه فأجــاب قائـ ً‬\n‫أمــن والتلفــظ عليــه بألفــاظ غيــر الئقــة واإلعتــداء بضــرب املوقــوف ‪/‬‬\n‫‪ .....‬باحلــذاء والتلفــظ علــى املواقيــف بألفــاظ غيــر الئقــة وإحــداث فوضى‬\n\n\n                                                                                         ‫‪266‬‬\n\f      ‫بداخــل التوقيــف فهــذا كلــه صحيــح وإننــي نــادم علــى فعلــي وتائــب منــه‬\n      ‫ال إن شــاء اهلل هــذه إجابتــي هــذا‬    ‫ولــن أعــود ملثــل مــا بــدر منــي مســتقب ً‬\n      ‫وقــد جــرى اإلطــاع علــى مــا جــاء يف أقــوال املدعــى عليــه املدونــة علــى‬\n      ‫الصفحــة رقــم (‪ )2-1‬مــن ملــف التحقيــق املرفــق باملعاملــة وعلــى محضــر‬\n      ‫خفيــر التوقيــف املرفــق باملعاملــة لفــة رقــم (‪ )2‬وأقــوال املدعــى عليــه‬\n      ‫املدونــة علــى الصفحــة رقــم (‪ )15‬مــن ملــف اإلســتدالل وأقــوال املواقيــف‬\n      ‫ـاء علــى مــا تقــدم‬‫املدونــة علــى الصحيفــة رقــم (‪ )13-12-11-10-9‬فبنـ ً‬\n      ‫مــن ســماع الدعــوى واإلجابــة ومــا قــرره الطرفــان ونظــر ًا إلــى أن املدعــى‬\n      ‫عليــه صــادق علــى مــا جــاء يف دعــوى املدعــي العــام ونظــر ًا إلــى أن املدعى‬\n      ‫عليــه تعــدى بقولــه وفعلــه والشــريعة اإلســامية جــاءت بحفــظ الكليــات‬\n      ‫اخلمــس ومنهــا النفــس والعــرض ويف احلديــث (كل املســلم علــى املســلم‬\n      ‫حــرام دمــه ومالــه وعرضــه) رواه مســلم ونظــر ًا إلــى خلـ ّـو صحيفــة املدعــى‬\n      ‫عليــه مــن الســوابق اجلنائيــة وإعالنــه التوبــة والنــدم‪ ،‬وقصــد ًا الســتصالح‬\n               ‫املدعــى عليــه وجلميــع مــا تقــدم قــررت اآلتــي ‪ -:‬أو ًال ‪ /‬ثبــت لـ ّ‬\n      ‫ـدي إدانــة‬\n      ‫املدعــى عليــه ‪ ......‬بتهديــد رجــل أمــن والتلفــظ عليــه بألفــاظ غيــر الئقــة‬\n      ‫واإلعتــداء بضــرب املوقــوف ‪ .... /‬باحلــذاء والتلفــظ علــى املواقيــف‬\n      ‫بألفــاظ غيــر الئقــة وإحــداث فوضــى بداخــل التوقيــف‪ .‬ثاني ـاً‪ /‬جلــد‬\n      ‫املدعــى عليــه ســبعني جلــدة دفعــة واحــدة وأخــذ التعهــد املشــدد عليــه‬\n      ‫ال تعزيــر ًا لــه علــى مــا‬\n                                  ‫وإنــذاره مــن العــود إلــى مثــل مــا بــدر منــه مســتقب ً‬\n      ‫أديــن بــه املنصــوص عليــه يف أو ًال مــن تهديــد رجــل أمــن والتلفــظ عليــه‬\n      ‫بألفــاظ غيــر الئقــة واإلعتــداء بضــرب املوقــوف ‪ .... /‬باحلــذاء والتلفــظ‬\n      ‫علــى املواقيــف بألفــاظ غيــر الئقــة وإحــداث فوضــى بداخــل التوقيــف‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت ألجــل احلــق العــام وجــرى نصــح وتوجيــه‬\n\n\n‫‪267‬‬\n\f‫املدعــى عليــه مبــا يناســب املقــام وبإعــان احلكــم قــرر املدعــى عليــه‬\n‫عــدم القناعــة بــه وطلــب رفعــه إلــى محكمــة اإلســتئناف بــدون الئحــة‬\n‫إعتراضيــة وأبــدى املدعــي العــام اإلعتــراض علــى احلكــم وطلــب رفعــه‬\n‫إلــى محكمــة اإلســتئناف بــدون الئحــة إعتراضيــة وأمــرت برفــع احلكــم‬\n‫مــع كامــل متعلقاتــه إلــى محكمــة اإلســتئناف لتدقيقــه حســب املتبــع‬\n‫وأقفلــت اجللســة يف متــام الســاعة الثانيــة عشــر والنصــف بعــد الظهــر‬\n‫وعلــى مــا تقــدم حصــل التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                         ‫وعلــى الــه وصحبــه أجمعــن حــرر يف ‪....‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســول اهلل ‪ ...‬وبعــد‪ -:‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائية الســابعة يف محكمة اإلســتئناف‬\n‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملديــة املنــورة برقــم ‪ ....‬وتاريــخ ‪ ....‬املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة الشــيخ‪ .... /‬القاضــي باحملكمــة اجلزائيــة‬\n‫باملدينــة املنــورة برقــم ‪ .....‬وتاريــخ ‪ .....‬احملكــوم فيــه مبــا دون بباطــن‬\n‫القــرار املتضمــن دعــوى املدعــي العــام ضــد‪ ..... /‬املتهــم يف تهديــد رجــل‬\n‫األمــن وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                           ‫‪268‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":263,"source_page_end":268,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c4d1f6b4dc2b8c4deefe49943008f30fd3006636b0725b0e03be8b59ca304309","normalized_text_hash":"9a0030d1b766ad041f701ac2e31f1c2c20cedf3348fd148ca26c389f65cfc34a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p263-34295817"},{"id":"5937168e-52b6-571f-aeff-4dc70b6896db","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -إحداث إصابات -الشروع يف القتل -دعوى عامة ( حق عام ) -دعوى خاصة ( حق خاص) -تنازل املجني عليه «الزوجة» أحد موجبات تخفيف العقوبة التعزيرية -الشروع يف اجلرمية بالقيام ببعض أسبابها أو مقدماتها موجب للتعزير - التعزير للشبهة (تهمة ) لقيام قرائن على صحة التهمة -تقرير طبي -تعزير بالسجن وأخذ التعهد.","document_number":"34283926","case_number":"34283109","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/30","year":"1434","subject":"اعتداء -ضرب -إحداث إصابات -الشروع يف القتل -دعوى عامة ( حق عام ) -دعوى خاصة ( حق خاص) -تنازل املجني عليه «الزوجة» أحد موجبات تخفيف العقوبة التعزيرية -الشروع يف اجلرمية بالقيام ببعض أسبابها أو مقدماتها موجب للتعزير - التعزير للشبهة (تهمة ) لقيام قرائن على صحة التهمة -تقرير طبي -تعزير بالسجن وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34283926 :‬تاريخه‪1434/7/30 :‬هـ‬\n                          ‫رقم الدعوى‪34283109:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34351947‬تاريخه‪1434/11/5 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬إحــداث إصابــات ‪ -‬الشــروع يف القتــل ‪ -‬دعــوى عامــة‬\n      ‫( حــق عــام ) ‪ -‬دعــوى خاصــة ( حــق خــاص) ‪ -‬تنــازل املجنــي عليــه‬\n      ‫«الزوجــة» أحــد موجبــات تخفيــف العقوبــة التعزيريــة ‪ -‬الشــروع يف‬\n      ‫اجلرميــة بالقيــام ببعــض أســبابها أو مقدماتهــا موجــب للتعزيــر ‪-‬‬\n      ‫التعزيــر للشــبهة (تهمــة ) لقيــام قرائــن علــى صحــة التهمــة ‪ -‬تقريــر‬\n                                      ‫طبــي ‪ -‬تعزيــر بالســجن وأخــذ التعهــد‪.‬‬\n\n\n\n\n                                          ‫ما أشار له القاضي يف تسبيب احلكم ‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بالشــروع يف قتــل‬\n      ‫زوجتــه واالعتــداء بضربهــا ممــا أدى إلصابتهــا باإلصابــات املوصوفــة‬\n      ‫بالتقريــر الطبــي وطلــب إيقــاع العقوبــة التعزيريــة عليــه حيــث تقدمــت‬\n      ‫املدعيــة اخلاصــة ببــاغ بــأن املدعــى عليــه (زوجهــا) ضربهــا وأشــهر عليهــا‬\n      ‫الســكني مهــددا لهــا بقتلهــا ‪ ،‬وبعــد هــذه احلادثــة بأيــام دخــل عليهــا يف‬\n      ‫غرفتهــا ببيــت أهلهــا وهددهــا بالقتــل ورأت بحوزتــه ســكينا‪ ،‬وصــدر‬\n      ‫تقريــر طبــي يوضــح اإلصابــات التــي نالــت املدعيــة ‪ ،‬أنكــر املدعى عليه‬\n      ‫التهمــة وقــرر بــأن يحصــل بينــه وبــن زوجتــه مشــاكل عائليــة ‪ ،‬حضــر‬\n\n‫‪269‬‬\n\f‫وكيــل املدعيــة اخلاصــة وقــرر بــأن موكلتــه متنازلــة عــن املدعــى عليــه‬\n‫وال تطلــب منــه أرشــا وال تأديبــا وال بينــة لديهــا علــى مــا اتهــم بــه املدعــي‪،‬‬\n‫وأنهــا تطلــب منــه أن يقــوم بحقوقهــا ويعاشــرها باملعــروف ويكــف أذاه‬\n‫عنهــا وعــن أســرتها ‪ ،‬وبالعــرض علــى املدعــى عليــه قــرر التزامــه بالقيــام‬\n‫باحلقــوق الزوجيــة والعشــرة احلســنة وأن هــذه طريقتــه منــذ تزوجهــا ‪،‬‬\n‫تبــن مــن صحيفــة ســوابق املدعــي عــدم تســجيل ســابقة عليــه ‪ ،‬قــدم‬\n‫املدعــى عليــه تقريــرا طبيــا صــادرا مــن أحــد املراكــز الطبيــة مضمونــه‬\n‫بــأن املدعــى عليــه يعانــي مــن اضطــراب ذهانــي ضاللــي ومصــاب بوهــم‬\n‫االعتقــادات والشــكوك ‪ ،‬عليــه ونظــرا لتنــازل املدعيــة اخلاصــة ‪،‬‬\n‫ولتطلــع الشــرع لبنــاء احليــاة الزوجيــة علــى الوفــاق والوئــام ‪ ،‬ولعــدم‬\n‫وجــود دليــل يســتند عليــه يف إدانــة املدعــى عليــه ‪ ،‬لكــن تتوجــه التهمــة‬\n‫علــى املدعــى عليــه لــذا فقــد قــررت احملكمــة احلكــم باالكتفــاء مبــا‬\n‫أمضــاه املدعــى عليــه يف التوقيــف ألجــل هــذه القضيــة أي مــدة شــهرين‬\n‫إعتبــارا مــن تاريــخ توقيفــه وأخــذ التعهــد عليــه بإلتــزام األدب والنظــام‬\n‫واحلــذر مــن الوقــوع يف املخالفــات وكــف أذاه عــن زوجتــه وأســرتها‬\n‫والقيــام باحلقــوق الزوجيــة والعشــرة احلســنة ‪ ،‬ورأت معاجلــة املدعــى عليــه‬\n‫يف مستشــفى متخصــص حتــى تتحســن حالتــه ‪ ،‬عــرض احلكــم علــى‬\n‫املدعيــة اخلــاص واملدعــى عليــه وقــررا القناعــة ‪ ،‬وأمــا املدعــي العــام‬\n‫فقــرر عــدم القناعــة وطلــب اســتئنافه بــدون الئحــة ‪ ،‬صــدق احلكــم مــن‬\n                                                              ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                           ‫‪270‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪1434/06/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم وتاريــخ ‪1434/06/19‬ه ـ ففــي يــوم األحــد املوافــق‬\n      ‫‪1434/07/30‬ه ـ افتتحــت اجللســة الســاعة ‪ 01:00‬وفيهــا قــدم املدعــي‬\n      ‫العــام ‪...........‬املــدرع دعــواه ضــد ‪ 39 ،........... /‬عام ـ ًا ‪ ،‬ســعودي‬\n      ‫اجلنســية‪ ،‬مبوجــب الســجل املدنــي رقــم (‪ )...........‬يقيــم مبدينــة الريــاض‬\n      ‫‪ ،‬أوقــف بتاريــخ ‪ 1434/6/1‬ه ـ وأحيــل للســجن العــام مبوجــب أمــر‬\n      ‫اإلحالــة ومتديــد التوقيــف رقــم ‪...........‬وتاريــخ ‪1434/6/13‬ه ـ اســتناد ًا‬\n      ‫للمــادة (‪ )113‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬فبتاريــخ ‪1434/5/28‬ه ـ‬\n      ‫تقدمــت ملركــز شــرطة ‪...........‬املجنــي عليهــا‪........... /‬مبلغــة عــن‬\n      ‫تعرضهــا للضــرب مــن قبــل زوجهــا املدعــى عليــه أعــاه وصــدر بحقهــا‬\n      ‫تقريــر طبــي مــن املديريــة العامــة للشــئون الصحيــة مبنطقــة الريــاض‬\n      ‫برقــم (‪ )...........‬وتاريــخ ‪1434/5/28‬ه ـ املتضمــن وجــود كدمــات‬\n      ‫بالســاعد األميــن وبالعضــد األيســر وكدمــة بالشــفة العليــا وكدمــات‬\n      ‫بالســاقني واملذكــورة حامــل يف الشــهر الرابــع ولــم حتــدد مــدة الشــفاء‬\n      ‫‪.‬وبضبــط بــاغ املجنــي عليهــا وســماع أقوالهــا‪ /‬أفــادت أن املدعــى عليــه‬\n      ‫قــام وقــت احلادثــة األولــى يــوم االثنــن املوافــق ‪1434/5/27‬ه ـ حوالــي‬\n      ‫الســاعة العاشــرة صباحـ ًا باالســتئذان لهــا وألطفالهــا مــن الروضــة ‪........‬‬\n      ‫ب‪ ...........‬وقــام بإنــزال األطفــال عنــد منــزل والدتــه الــذي نقيــم فيــه ثــم‬\n      ‫توجــه بهــا إلــى اســتراحة والدتــه ‪ ...........‬وعنــد وصولهــم االســتراحة‬\n\n‫‪271‬‬\n\f‫قــام املدعــى عليــه بســحبها علــى األرض وإدخالهــا بالقــوة واالعتــداء‬\n‫عليهــا بالضــرب بحذائــه وضغطهــا علــى احلائــط واألرض وأشــهر عليهــا‬\n‫ا (ســوف أقتلــك وأذبحــك) وتكلــم عليهــا‬     ‫ســكني متوســطة احلجــم قائـ ً‬\n‫بــكالم بذيــئ وأخــذ يتكلــم عــن صــورة شــاهدها يف االنترنــت يقــول‬\n‫بأنهــا لهــا وتفيــد أيضـ ًا أنهــا قامــت بتهدئتــه وبعدهــا أخذهــا ملنزلهــم عنــد‬\n‫والدتــه ب‪...........‬وأنهــا قامــت باالتصــال علــى أخوهــا‪........... /‬فحضــر‬\n‫إلــى ‪...........‬وأخذهــا ملنــزل أهلهــا بحــي ‪...........‬بالريــاض ‪.‬ويف يــوم‬\n‫الثالثــاء املوافــق ‪1434/5/28‬ه ـ فجــر ًا حوالــي الســاعة اخلامســة صباح ًا‬\n‫تفاجــأت بدخولــه عليهــا يف غرفتهــا يف بيــت أهلهــا بحــي ‪...........‬بالرياض‬\n‫وكان البــس بيجامــة ومغطــى وجهــه والبــس قفــازات وقــام بوضــع قطعــة‬\n‫قمــاش مبلولــة مبــاء يف فمهــا مــردد ًا (ســوف أقتلــك وأذبحــك) وكالم‬\n‫بــذئ ويقــول (ســوف أصــل إليــك يف أي مــكان تذهبــن إليــه) وتفيــد بعــد‬\n‫تهدئتهــا لــه رأتــه يضــع ســكني يف شــنطة أحضرهــا معــه لــم تشــاهدها‬\n‫حــن دخولــه وبســؤالها عــن كيفيــة دخولــه منــزل أهلهــا أفــادت باحتمال‬\n‫أنــه أخــذ مفتاحهــا اخلــاص بهــا ألنها حني خروجها مــن بيتهم ب‪ ...........‬لم‬\n‫تأخــذ معهــا ســوى مالبســها التــي عليهــا وبســؤالها عــن عــدم اســتنجادها‬\n‫بأهلهــا أفــادت بأنهــا لــم تســتطيع ألنــه كان واضع ـ ًا علــى فمهــا قطعــة‬\n‫قمــاش مبلولــة باملــاء ‪.‬وباســتجواب املدعــى عليــه‪ /‬أنكــر مــا تدعــي بــه‬\n‫املجنــي عليهــا املدعيــة بتات ـ ًا وذكــر أنــه يوجــد بينــه وبينهــا مشــاكل‬\n‫قبــل حوالــي ســتة أشــهر حــول صــورة مشــابهة لهــا وجدهــا باإلنترنــت‬\n‫‪.‬وبإجــراء محضــر مواجهــة بينهمــا وبعــرض ادعــاء املجنــي عليهــا علــى‬\n‫املدعــى عليــه وإنــكار املدعــى عليــه علــى املدعيــة تبــن لنــا قــوة حجــة‬\n                                                ‫املدعيــة يف ادعاءهــا ملــا يلــي ‪:‬‬\n\n\n                                                                                         ‫‪272‬‬\n\f                                                  ‫‪ -1‬استشهادها بوالدة املدعى عليه ‪.‬‬\n      ‫‪ -2‬وجــود ســبب دافــع لقيــام املدعــى عليــه باالعتــداء علــى املجنــي عليهــا‬\n      ‫وهــو الشــك فيهــا ويــدل علــى ذلــك طلبــه أثنــاء املواجهــة حتليــل (‪)DNA‬‬\n                                                               ‫ألبناءه‪...............................‬‬\n                             ‫‪ -3‬التقرير الطبي يثبت وجود حالة االعتداء بالضرب ‪.‬‬\n      ‫‪ -4‬يؤكــد وقــوع االعتــداء يف وقتــه املذكــور واعتــراف املدعــى‬\n      ‫عليــه أثنــاء املواجهــة بحضــوره إلــى الروضــة التــي تعمــل فيهــا املدعيــة‬\n                                                         ‫واالســتئذان لهــا وألطفالهــا ‪.‬‬\n      ‫وأســفر التحقيــق بتوجيــه االتهــام للمدعــى عليــه‪...................... /‬‬\n      ‫بالشــروع يف قتــل زوجتــه‪........... /‬واالعتــداء بضربهــا ممــا أدى إلصابتهــا‬\n      ‫باإلصابــات املوصوفــة بالتقريــر الطبــي املشــار إليــه‪ .‬وذلــك لألدلــة‬\n                                                                           ‫والقرائــن األتيــة ‪:‬‬\n                                      ‫‪ -1‬ما جاء بالتقرير الطبي املشار إليه املرفق ‪.‬‬\n                              ‫‪ -2‬ما جاء مبحضر املواجهة املدون من ملف التحقيق ‪.‬‬\n          ‫وببحث سوابقه اتضح عدم وجود سوابق مسجله عليه حتى تاريخه ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل معاقــب عليــه شــرع ًا لــذا‬\n      ‫أطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا أســند إليــه ‪ ،‬علم ـ ًا بــأن‬\n      ‫احلــق اخلــاص مــازال قائم ـ ًا ‪ .‬هــذه دعــواي ‪ ،‬وبســؤال املدعــى عليــه‬\n      ‫أجــاب بقولــه إن مــا ذكــره املدعــي العــام غيــر صحيــح ودعــوى زوجتــي‬\n      ‫وبالغهــا غيــر صحيــح ولكــن يحصــل بينــي وبــن زوجتــي مشــاكل‬\n      ‫عائليــة هكــذا أجــاب فطلبــت مــن املدعــي العــام البينــة فقــال بينتــي‬\n      ‫مــا يف أوراق املعاملــة وبــاغ املدعيــة بذلــك هــذا وقــد حضــر ‪...........‬‬\n      ‫ســعودي بالهويــة رقــم (‪ )...........‬الوكيــل الشــرعي عــن ‪......................‬‬\n\n\n‫‪273‬‬\n\f‫ســعودية بالهويــة رقــم (‪ )...........‬مبوجــب صــك الوكالــة الصــادرة مــن‬\n‫كاتــب العــدل بــوزارة العــدل برقــم ‪...........‬يف ‪1434/07/25‬ه ـ املخــول‬\n‫لــه فيهــا باملرافعــة واملدافعــة واملخاصمــة واملخالصــة واملطالبــة ضــد‬\n‫زوجهــا ‪......................‬والصلــح والتنــازل واإلقــرار ‪ ...‬الــخ وقــال إن هــذا‬\n‫احلاضــر املدعــى عليــه زوج ملوكلتــي وبينهمــا أوالد وليــس لدينــا بينــة‬\n‫علــى الضــرب والشــروع يف القتــل وموكلتــي متنازلــه عــن حقهــا اخلــاص‬\n‫وال تطالــب بــأرش وال تأديــب ولكــن تطلــب منــه أن يقــوم بحقوقهــا‬\n‫ويعاشــرها باملعــروف ويكــف أذاه عنهــا وعــن أســرتها وأنــي بحضــوري‬\n‫ال هكــذا قــرر بطوعــه‬    ‫أقــرر تنــازل موكلتــي عنــه ال حاضــر ًا وال مســتقب ً‬\n‫واختيــاره وبعــرض ذلــك علــى املدعــى عليــه ‪...........‬قــال إننــي التــزم علــى‬\n‫نفســي بالقيــام باحلقــوق الزوجيــة والعشــرة احلســنة وهــذه طريقتــي منــذ‬\n‫أن تزوجتهــا هــذا وقــد أبــرز أحــد املراجعــن للمدعــى عليــه تقريــر ًا‬\n‫طبي ـ ًا صــادر ًا مــن مركــز مطمئنــة مفــاده أن املدعــى عليــه يعانــي مــن‬\n‫اضطــراب ذهانــي ضاللــي ومصــاب بوهــم االعتقــادات والشــكوك‬\n‫فبنــاء علــى مــا تقــدم وإلــى مــا تضمنتــه أوراق املعاملــة ونظــر ًا النتهــاء‬\n‫احلــق اخلــاص بالتنــازل وحيــث أن الشــرع ينظــر إلــى بنــاء احليــاة الزوجيــة‬\n‫وإلــى الوفــاق والوئــام بــن الزوجــن وحيــث لــم يثبــت علــى املدعــى عليــه‬\n‫مــا أســفر إليــه التحقيــق لعــدم وجــود دليــل يســتند إليــه ولكــن تتوجــه‬\n‫التهمــة عليــه يف ذلــك لــذا قــررت االكتفــاء مبــا أمضــاه املدعــى عليــه‬\n‫يف التوقيــف وهــو مــدة شــهرين اعتبــار ًا مــن تاريــخ توقيفــه ويؤخــذ عليــه‬\n‫التعهــد بالتــزام األدب والنظــام واحلــذر مــن الوقــوع يف املخالفــات وكــف‬\n‫أذاه عــن زوجتــه وأســرتها والقيــام باحلقــوق الزوجيــة والعشــرة احلســنة وبه‬\n‫حكمــت وأرى معاجلــة املدعــى عليــه يف مستشــفى حتــى تتحســن حالتــه‬\n\n\n                                                                                         ‫‪274‬‬\n\f      ‫وبعــرض احلكــم علــى احملكــوم عليــه واملدعــي اخلــاص وكالــة قــرروا‬\n      ‫القناعــة أمــا املدعــي العــام فطلــب اســتئنافه بــدون الئحــة اعتراضيــة‪.‬‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬حــرر يف ‪1434/07/30‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد فقــد اطلعنــا‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة األولــى مبحكمــة االســتئناف بالريــاض‬\n      ‫علــى املعاملــة الــواردة مــن مســاعد رئيــس احملكمــة اجلزائيــة بالريــاض‬\n      ‫برقــم وتاريــخ ‪1434/10/7‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة ‪...........‬برقــم وتاريــخ ‪1434/7/30‬ه ـ واخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ ،........... /‬وموضوعهــا ضــرب وانتهــاء‬\n      ‫الدراســة والتدقيــق املصادقــة علــى احلكــم لعــدم موجــب املالحظــة مــع‬\n      ‫تنبيــه فضيلتــه إلــى الشــرح علــى وكالــة صــورة املدعــي املرفقــة الصــادرة‬\n      ‫مــن املدعــي عليــه أصالــة بأنهــا مطابقــة ألصلهــا‪ .‬واهلل املوفــق وصلــى اهلل‬\n                           ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــة وســلم ‪.‬‬\n\n\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":269,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bacbf2fb586b5b5e27e8c8a299d1445316235d8becc950b7f90c1739d23287be","normalized_text_hash":"1b43bfe02d4887291354abd0c52ebf0b8b344ed940e53a811e0552da8d40b472","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p269-34283926"},{"id":"06840413-ada4-50c3-92e3-4a329693f08f","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى إيذاء ووضع حجارة وبهائم ميتة على الطريق العام -عدم البينة -إمهال املدعى العام إحضار بينة -عجز املدعى العام على إحضار بينته -حلف املدعى عليهما على نفي الدعوى -صرف النظر عن احلقن العام واخلاص.","document_number":"34203552","case_number":"34786739","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية األولى برفقها القرار رقم 34259198وتاريخ","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/01","year":"1434","subject":"دعوى إيذاء ووضع حجارة وبهائم ميتة على الطريق العام -عدم البينة -إمهال املدعى العام إحضار بينة -عجز املدعى العام على إحضار بينته -حلف املدعى عليهما على نفي الدعوى -صرف النظر عن احلقن العام واخلاص.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34203552:‬تاريخه‪1434/04/01:‬هـ‬\n                   ‫رقم الدعوى‪34786739 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n       ‫تاريخه‪1434/8/15 :‬هـ‬   ‫‪34297067‬‬\n\n\n\n‫دعــوى إيــذاء ووضــع حجــارة وبهائــم ميتــة علــى الطريــق العــام ‪ -‬عــدم‬\n‫البينــة ‪ -‬إمهــال املدعــى العــام إحضــار بينــة ‪ -‬عجــز املدعــى العــام علــى‬\n‫إحضــار بينتــه ‪ -‬حلــف املدعــى عليهمــا علــى نفــي الدعــوى ‪ -‬صــرف‬\n                                      ‫النظــر عــن احلقــن العــام واخلــاص‪.‬‬\n\n\n\n\n‫‪ -‬قولــه صلــى اهلل عليــه وســلم‪ ( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                           ‫املدعــى عليــه )‬\n‫‪ -‬مــا جــاء يف كشــاف القنــاع‪ ( :)337/4( :‬وال يجــوز للقاضــي احلكــم‬\n                              ‫برؤيــة خــط الشــاهد احتياط ـ ًا للحكــم )‪.‬‬\n                            ‫‪ -‬املادة (‪ )120‬من نظام املرافعات الشرعية‪.‬‬\n                             ‫‪ -‬املادة (‪ )169‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليهمــا بوضــع احلجــارة والبهائــم علــى الطريــق‬\n‫عمــد ًا ممــا تســبب يف حــدوث تلفيــات لســيارتني وكذلــك حــدوث‬\n‫اإلصابــة المــرأة باإلصابــة املوصوفــة بالتقريــر الطبــي املرفــق ‪ ،‬بعــرض‬\n‫ذلــك علــى املدعــى عليهمــا أنكراهــا جملــة وتفصيــا وبعــرض ذلــك‬\n‫علــى املدعــي العــام طلــب مهلــة إلحضــار البينــة‪ ،‬حضــر املدعــي باحلــق‬\n\n                                                                                    ‫‪280‬‬\n\f      ‫اخلــاص وادعــى علــى املدعــى عليهمــا أنهمــا قامــا بوضــع أحجــار وبهائــم‬\n      ‫ميتــة يف وســط الطريــق ‪ ،‬وأثنــاء مــروره وطــئ هــذه األشــياء فخــرج‬\n      ‫عــن الطريــق وتلفــت الســيارة‪ ،‬وبعــرض دعــوى املدعــي باحلــق اخلــاص‬\n      ‫علــى املدعــى عليهمــا أنكراهــا‪ ،‬وبطلــب البينــة مــن املدعــي باحلــق‬\n      ‫اخلــاص طلــب ميــن املدعــى عليهمــا علــى نفــي دعــواه فقــط‪ ،‬وبعــرض‬\n      ‫ذلــك علــى املدعــى عليهمــا حلــف كل واحــد منهمــا اليمــن علــى نفــي‬\n      ‫دعــوى املدعــي باحلــق اخلــاص‪ ،‬نظــر ًا ألن املدعــى عليهمــا أنكــرا دعــوى‬\n      ‫املدعــي جملــة وتفصيــا‪ ،‬ونظــر ًا ألن املدعــي لــم يقــم بينــة علــى دعــواه‬\n      ‫وطلــب ميــن املدعــى عليهمــا علــى نفــي ذلــك‪ ،‬وألن املدعــى عليهمــا أديــا‬\n      ‫اليمــن املطلوبــة منهمــا علــى نفــي دعوى املدعي‪ ،‬لــذا مت احلكم بصرف‬\n      ‫النظــر عــن دعــوى املدعــي اخلــاص والعــام وإخــاء ســبيل املدعــى عليهمــا‬\n      ‫مــن هــذه الدعــوى‪ ،‬بعــرض احلكــم علــى املدعــي واملدعــى عليهمــا قرروا‬\n      ‫القناعــة وقــرر املدعــي العــام االعتــراض وجــرى تصديــق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪281‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم الســبت ‪1434/4/20‬هـ ـ الســاعة احلاديــة عشــرة والنصــف‬\n‫صباح ـ ًا لــدي أنــا ‪......‬القاضــي يف احملكمــة اجلزائيــة بتبــوك فتحــت‬\n‫ـاء علــى املعاملــة الــواردة لــي مــن هيئــة التحقيــق واالدعــاء العــام‬\n                                                                         ‫اجللســة بنـ ً‬\n‫برقــم ‪ 6032‬وتاريــخ ‪1433/9/10‬ه ـ واحملالــة لــي بشــرح فضيلــة الرئيس‬\n‫رقــم ‪ 34786739‬وتاريــخ ‪1434/4/1‬هـ ـ وفيهــا حضــر املدعــي العــام ‪......‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ ،......‬واملعمــد مــن مرجعــه مبوجب‬\n‫ا يف تقريــر دعــواه بصفتــي‬   ‫اخلطــاب رقــم ‪ 13058‬يف ‪1433/9/5‬ه ـ قائـ ً‬\n‫مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء لفــرع الهيئــة مبنطقــة تبــوك أدعــي علــى‪/‬‬\n‫‪...... -1‬ســعودي اجلنســية مبوجب ســجل مدني يرقم ‪...... -2......‬ســعودي‬\n‫اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ،......‬باالطــاع علــى احملضــر املعــد‬\n‫مــن قبــل نقطــة أمــن الظلفــة بتاريــخ ‪1433/5/22‬ه ـ أنــه يف متــام الســاعة‬\n‫العاشــرة مســاء وقــع حادثــن بســبب قيــام أشــخاص غيــر معروفــن‬\n‫بوضــع أحجــار وبهائــم ميتــة علــى الطريــق عمــد ًا مت القبــض علــى احلدثني‬\n‫‪ ......‬و ‪ ......‬مــن قبــل نقطــة أمــن مركــز ‪......‬وبســماع أقــوال املقيــم ‪......‬‬\n‫أفــاد بأنــه وقــع لــه حــادث بســبب وضــع أحجــار وبهائــم ميتــة علــى الطريق‬\n‫ممــا تســبب يف إحــداث تلفيــات يف ســيارته مــن نــوع ‪ ......‬وبســماع أقــوال‬\n‫املواطــن ‪......‬أفــاد بأنــه كان معــه يف الســيارة ‪......‬كمــا أفــاد بأنــه‬\n‫تعــرض للحــادث بســبب وجــود أحجــار وبهائــم ميتــة علــى الطريــق ممــا‬\n‫تســبب يف إحــداث تلفيــات يف ســيارته مــن نــوع ‪ .....‬وقــد قــدرت قيمــة‬\n‫التلفيــات للســيارة مــن نــوع ‪ .....‬بأربعــة وثالثــن ألــف وتســعمائة واثنــن‬\n\n                                                                                          ‫‪282‬‬\n\f      ‫وثمانــن ريــا ًال وقــد قــدرت قيمــة التلفيــات للســيارة مــن نــوع ‪ .....‬بتســع‬\n      ‫وخمســن ألــف ريــال وخمســمائة وســتة عشــر ريــاال وبســماع شــهادة‬\n      ‫احلــدث ‪......‬أفــاد بــأن املدعــى عليهمــا طلبــا منــه الذهــاب معهــم لوضــع‬\n      ‫احلجــارة والبهائــم امليتــة علــى الطريــق فرفــض ذلــك وقامــوا بتهديــده إن‬\n      ‫أخبــر أحــد بذلــك وقــد صــدر التقريــر الطبــي بحــق ‪......‬رقــم (‪)......‬‬\n      ‫وتاريــخ ‪1433/6/22‬ه ـ مــن مستشــفى ‪......‬العــام املتضمــن وجــود رض‬\n      ‫بســيط علــى األنــف أدى إلــى رعــاف بســيط ومــدة الشــفاء يومــان مالــم‬\n      ‫حتــدث مضاعفــات ‪ ،‬وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى‬\n      ‫عليهمــا ‪......‬بوضــع احلجــارة والبهائــم علــى الطريــق عمــد ًا ممــا تســبب يف‬\n      ‫حــدوث تلفيــات لســيارتني وكذلــك حــدوث اإلصابــة المــرأة باإلصابــة‬\n      ‫املوصوفــة بالتقريــر الطبــي املرفــق وذلــك لألدلــة والقرائــن التاليــة ‪-1‬‬\n      ‫شــهادة احلــدث املدونــة علــى اللفــة رقــم (‪ -2 )34‬مــا جــاء بالتقارير الطبية‬\n      ‫املرفــق لفــة رقــم (‪ -3 )15-13‬مــا جــاء يف تقاريــر قيمــة التلفيــات املرفــق‬\n      ‫لفــة رقــم (‪ )43‬ورقــم (‪ )39-38‬وحيــث أن مــا أقــدم عليــه املذكــوران‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا لــذا أطلــب ‪ -1‬إثبــات مــا أســند إليهمــا‬\n      ‫‪ -2‬احلكــم عليهمــا بعقوبــة بديلــة اســتنادا لقــرار مجلــس الــوزراء رقــم‬\n      ‫(‪ )169‬وتاريــخ ‪1429/6/19‬ه ـ علم ـ ًا بــأن احلــق اخلــاص ال زال قائم ـ ًا )‬\n      ‫هــذه دعــواي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليهمــا أجــاب كل واحــد‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي بوضــع احلجــارة‬      ‫منهمــا قائ ـ ً‬\n      ‫والبهائــم علــى الطريــق عمــد ًا ممــا تســبب يف حــدوث تلفيــات لســيارتني‬\n      ‫وكذلــك حــدوث اإلصابــة المــرأة باإلصابــة املوصوفــة بالتقريــر الطبــي‬\n      ‫املرفــق ‪ ،‬فهــذا غيــر صحيــح ‪ ،‬هكــذا أجــاب كل واحــد مــن املدعــى‬\n      ‫ا ‪ :‬مــا ذكرتــه‬  ‫عليهمــا ‪ ،‬وبعــرض ذلــك علــى املدعــي العــام أجــاب قائ ـ ً‬\n\n\n‫‪283‬‬\n\f‫هــو الصحيــح ولــدي بينــة علــى ذلــك أطلــب إمهالــي ألجــل إحضارهــا ‪،‬‬\n‫هكــذا أجــاب املدعــي العــام ‪ ،‬ثــم حضــر يف هــذه اجللســة املدعــي اخلاص‬\n‫‪ ،......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪......‬فادعــى ضــد‬\n‫ا يف حتريــر دعــواه‬     ‫احلاضريــن معــه يف مجلــس احلكــم الشــرعي قائ ـ ً‬\n‫عليهمــا ‪ :‬لقــد قــام هــذان احلاضــران املدعــى عليهمــا بوضــع أحجــار‬\n‫وبهائــم ميتــة يف وســط طريــق ‪......‬يف تبــوك ‪ ،‬وأثنــاء مــروري قمــت بــوطء‬\n‫هــذه األشــياء فخرجــت عــن الطريــق وتلفــت ســيارتي مــن نــوع ‪ ، ......‬وقــد‬\n‫قــدرت تلفيــات الســيارة املذكــورة مببلــغ قــدره تســعة وخمســون ألف ـ ًا‬\n‫وخمســمائة وســتة عشــر ريــا ًال ‪ ،‬أطلــب إلزامهمــا بدفعهــا لــي حــا ًال هــذه‬\n‫دعــواي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليهمــا أجــاب كل واحــد منهمــا‬\n‫ا ‪ :‬مــا ذكــره املدعــي اخلــاص غيــر صحيــح ‪ ،‬هذه إجابتــي ‪ ،‬وبطلب‬           ‫قائـ ً‬\n‫البينــة أجــاب بقولــه ‪ :‬ال بينــة لــدي ســوى مــا جــاء يف شــهادة احلــدث وال‬\n‫أريــد إحضــاره وأطلــب ميــن املدعــى عليهمــا علــى نفــي دعــواي فقــط هــذه‬\n‫إجابتــي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليهمــا اســتعدا بذلــك فجــرى‬\n‫حتذيرهمــا مــن مغبــة اليمــن الكاذبــة فتفهمــا ذلــك فأذنــت لــه فحلــف‬\n‫كل واحــد منهمــا ‪ :‬بقولــه ( أقســم بــاهلل العظيــم املهلــك املــدرك خالــق‬\n‫الســموات واألرض أننــي لــم أقــم بوضــع حجــارة وبهائــم ميتــة علــى طريــق‬\n‫‪......‬بتبــوك وال أعلــم مــن قــام بذلــك ‪ ،‬كمــا أقســم بــاهلل العظيــم أنــي لــم‬\n‫أتســبب باحلــادث الــذي حصــل للمدعــي اخلــاص ‪......‬بســبب وضــع احلجــارة‬\n‫والبهائــم امليتــة أقســم بــاهلل العظيــم علــى ذلــك ) هكــذا حلــف‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وألن املدعــى‬    ‫املذكــوران فبنـ ً‬\n‫عليهمــا أنكــرا دعــوى املدعــي جملــة وتفصيــا ولقولــه صلــى اهلل عليــه‬\n‫وســلم ( البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ) ونظــر ًا ألن‬\n\n\n                                                                                        ‫‪284‬‬\n\f      ‫املدعــي لــم يقــم بينــة علــى دعــواه وطلــب ميــن املدعــى عليهمــا علــى نفــي‬\n      ‫ذلــك وألن املدعــى عليهمــا أديــا اليمــن املطلوبــة منهمــا علــى نفــي دعــوى‬\n      ‫املدعــي لــذا فقــد قــررت صــرف النظــر عــن دعــوى املدعــي اخلــاص‬\n      ‫وأخليــت ســبيل املدعــى عليهمــا مــن هــذه الدعــوى يف احلــق اخلــاص هــذا‬\n      ‫مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى الطرفــن قــررا القناعــة‬\n      ‫والرضــا ‪ ،‬هــذا مــا جــرى نظمــه يف احلــق اخلــاص ‪ ،‬أمــا احلــق العــام فحيــث‬\n      ‫ال مانــع مــن طلــب املدعــي العــام رفــع اجللســة ألجــل إحضــار شــاهده ‪،‬‬\n      ‫فقــد جــرى رفــع اجللســة حلــن إحضــار املدعــي العــام لبينتــه ‪ ،‬وحــددت‬\n      ‫موعــد ًا لســماعها وذلــك يف يــوم الســبت القــادم ‪1434/4/27‬ه ـ الســاعة‬\n      ‫العاشــرة صباحـ ًا وعليــه جــرى التوقيــع احلمــد هلل وحــده وبعــد ففــي هــذا‬\n      ‫اليــوم الســبت املوافــق ‪1434/4/27‬ه ـ الســاعة احلاديــة عشــر صباح ـ ًا‬\n      ‫فتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا وبســؤال‬\n      ‫املدعــي العــام عــن بينتــه التــي وعــد بإحضارهــا أجــاب بقولــه لــم أســتطع‬\n      ‫إحضــار الشــهود وأطلــب مهلــة ألجــل إحضارهــم مــرة أخــرى هكــذا‬\n      ‫قــرر املدعــي العــام وحيــث األمــر كذلــك فقــد قــررت رفــع اجللســة‬\n      ‫وحــددت موعــد ًا جديــد ًا لســماع البينــة وذلــك يف يــوم األربعــاء املوافــق‬\n      ‫‪1434/5/1‬ه ـ الســاعة العاشــرة صباح ـ ًا وأفهمــت املدعــي العــام أنــه‬\n      ‫ســيعد عاجــز ًا عــن إحضــار بينتــه يف حــال لــم يحضرهــا يف املوعــد القادم‬\n      ‫فتفهــم ذلــك وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى ســيدنا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم حــرر يف الســاعة احلاديــة عشــر وعشــر دقائــق‬\n      ‫مــن ضحــى يــوم الســبت املوافــق ‪1434/4/27‬ه ـ ثــم يف جلســة أخــرى‬\n      ‫فتحــت اجللســة ‪ ،‬وفيهــا حضــر املدعــي العــام واملدعــى عليهما ‪ ،‬وبســؤال‬\n      ‫املدعــي العــام عــن بينتــه التــي وعــد بإحضارهــا أجــاب بقولــه ‪ :‬أقــرر‬\n\n\n‫‪285‬‬\n\f‫االكتفــاء مبــا ورد يف املعاملــة مــن أدلــة وقرائن هــذه إجابتي ‪،‬وباالطالع‬\n‫علــى مــا ذكــره املدعــي العــام مــن بينــات لــم أجــد فيهــا مــا يديــن املدعــى‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪،‬‬‫عليهمــا مبــا نســب إليهمــا ‪ ،‬فبنـ ً‬\n‫وإلنــكار املدعــى عليهمــا مــا نســب إليهمــا ‪ ،‬ونظــر ًا لعجــز املدعــى العــام‬\n‫عــن إحضــار بينتــه وال بينــه ســواها ونظــر ًا لكــون الشــبهة ال تتوجــه علــى‬\n‫املدعــى عليهمــا مبــا نســبه لهمــا املدعــي العــام ‪ ،‬وألن الشــهادة ال بــد أن‬\n‫تــؤدى مشــافهة يف مجلــس احلكــم ملــا نــص عليــه الفقهــاء ‪ ،‬ومــن ذلــك‬\n‫قولهــم ( وال يجــوز للقاضــي احلكــم برؤيــة خــط الشــاهد احتياط ـ ًا‬\n‫للحكــم ) انظــر كشــاف القنــاع (‪ ، )337/4‬وقــد نــص نظــام املرافعات‬\n‫الشــرعية مــاده (‪ )120‬علــى أنــه ال يجــوز االســتعانة يف أداء الشــهادة‬\n‫مبذكــرات مكتوبــة بــل يجــب أن تــؤدى شــفوي ًا ‪ ،‬كمــا نــص نظــام‬\n‫اإلجــراءات اجلزائيــة علــى أن الشــهادة ال بــد أن تــؤدى يف مجلــس القضــاء‬\n‫كمــا يف املــادة (‪ ، )169‬ونظــر ًا ألن تخلــف الشــاهد عــن احلضــور يعتبــر‬\n‫ا علــى تراجعــه عــن الشــهادة ومعلــوم أن الشــاهد يف حقــوق اهلل‬             ‫دلي ـ ً‬\n‫تعالــى ال يلــزم باحلضــور وألن الشــاهد واحلالــة هــذه يعتبــر مجهــول احلــال‪،‬‬\n‫وإذا اقتــرن مــع ذلــك كلــه كــون الشــاهد حــدث ‪ ،‬معلــوم كالم أهــل‬\n‫العلــم يف شــهادة األحــداث وقبولهــا مــن عدمهــا ‪،‬لذلــك كلــه فقــد قررت‬\n‫صــرف النظــر عــن دعــوى املدعــي العــام ‪ ،‬وأخليت ســبيل املدعــى عليهما‬\n‫مــن هــذه الدعــوى ‪ ،‬هــذا مــا ظهــر لــي وبــه حكمــت ‪ ،‬وبعرضــه علــى‬\n‫األطــراف قــرر املدعــى عليهمــا قناعتهمــا بــه ‪ ،‬وقــرر املدعــي العــام‬\n‫االعتــراض بالئحــة فأجبتــه إلــى طلبــه ‪ ،‬وجــرى إفهامــه أن لــه مــدة‬\n‫ثالثــن يوم ـ ًا لتقــدمي الالئحــة وأنــه إن مضــت املــدة ولــم يقــدم اعتراضــه‬\n‫فيســقط حقــه يف االعتــراض ويرفــع احلكــم حملكمــة االســتئناف‬\n\n\n                                                                                          ‫‪286‬‬\n\f      ‫لتدقيقــه مــن دون الئحــة ‪ ،‬فتفهــم ذلــك ‪ ،‬ثــم جــرى تســليمه نســخة مــن‬\n      ‫القــرار ليبــدأ ميعــاد االعتــراض مــن تاريــخ احلكــم ‪ ،‬وعليــه جــرى‬\n      ‫التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعني‬\n      ‫حــرر يف الســاعة العاشــرة والنصــف مــن ضحــى يــوم األربعــاء‬\n      ‫‪1434/5/1‬ه ـ احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت‬\n      ‫‪1434/7/15‬ه ـ الســاعة العاشــرة صباحـ ًا فتحــت اجللســة ‪ ،‬وفيهــا وردت‬\n      ‫املعاملــة مــن أصحــاب الفضيلــة يف محكمــة االســتئناف مبنطقــة تبــوك‬\n      ‫الدائــرة اجلزائيــة األولــى برفقهــا القــرار رقــم ‪ 34259198‬وتاريــخ‬\n      ‫‪1434/7/4‬ه ـ واملتضمــن مــا يلــي ( وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة والالئحــة االعتراضيــة لوحــظ أن شــهادة احلــدث ‪......‬لهــا‬\n      ‫أثــر يف القضيــة ولــم يحضــر ألداء مــا لديــه ولــم يوضــح املدعــي العــام‬\n      ‫ســبب تعــذر إحضــاره وال مــا اتخــذه مــن إجــراء يف ســبيل ذلــك مــع أن‬\n      ‫للمحكمــة اســتدعاء أي شــاهد تــرى يف ســماع أقوالــه إظهــار احلقيقــة‬\n      ‫كمــا ورد يف نظــام اإلجــراءات اجلزائيــة ‪ ،‬ملالحظــة مــا ذكــر وإكمــال‬\n      ‫الــازم وإحلــاق مــا يجريــه يف الضبــط وصورتــه والقــرار ومــن ثــم إعــادة‬\n      ‫املعاملــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم)‬\n      ‫فأقــول مســتعين ًا بــاهلل ومجيب ـ ًا أصحــاب الفضيلــة بالنســبة لشــهادة‬\n      ‫الشــاهد ‪......‬فقــد مت طلبــه عــن طريــق املدعــي العــام أكثــر مــن مــرة ‪،‬‬\n      ‫ثــم قــرر املدعــي العــام أخيــر ًا عجــزه عــن إحضــاره بعــد إمهالــه مــن‬\n      ‫احملكمــة مــدة كافيــة إلحضــار بينتــه ‪ ،‬كمــا أن الشــاهد احلــدث‬\n      ‫‪ ........‬يقيــم بعيــد ًا عــن تبــوك مبســافة تربــو علــى املائــة كيلــو ‪ ،‬ورمبــا‬\n      ‫كان هــذا مــن األســباب التــي أدت إلــى عــدم حضــوره ‪ ،‬ومــع ذلــك فــإن‬\n      ‫عــبء إثبــات الدعــوى منصــب علــى املدعــي العــام وفيمــا يقــرره من عجزه‬\n\n\n‫‪287‬‬\n\f‫أو رغبتــه وقدرتــه علــى إثبــات دعــواه ‪ ،‬هــذا مــا لــزم إيضاحــه ‪ ،‬واهلل‬\n‫املوفــق ‪ ،‬وأشــكر أصحــاب الفضيلــة جلميــل توجيههــم ونقدهــم ‪ ،‬هــذا‬\n‫وقــد قــررت إعــادة املعاملــة ألصحــاب الفضيلــة يف محكمــة االســتئناف‬\n‫مبنطقــة تبــوك لتقريــر مــا يرونــه ‪ ،‬حــرر يف الســاعة العاشــرة والنصــف‬\n                                        ‫من ضحى يوم السبت ‪1434/7/15‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة األولى‬\n‫لتدقيــق القضايــا اجلزائيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك برقــم‬\n‫‪......‬وتاريــخ ‪1434/7/16‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫الشــيخ‪...... /‬رقــم ‪......‬وتاريــخ ‪1434/5/1‬ه ـ اخلــاص بدعــوى املدعــي‬\n‫العــام ضــد‪...... /‬ورفيقــه ســعوديي اجلنســية يف قضيــة ايــذاء الغيــر علــى‬\n‫النحــو املوضــح يف القــرار واملتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وباالطــاع علــى مــا أحلقــه فضيلتــه جواب ـ ًا لقــرار الدائــرة‬\n‫رقــم ‪ 34259198‬وتاريــخ ‪1434/7/4‬ه ـ تقــرر املصادقــة علــى احلكــم‬\n‫بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                   ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪288‬‬\n\f289\n\f290\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":280,"source_page_end":290,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d6e17f743f84930a6c199caeb996fcae96a3bcabd27da488ae958caa77680592","normalized_text_hash":"85c4d0b634acebe206afeba90595d4d228cf6fd018eb7ec5b22fe037e0971db0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p280-34203552"},{"id":"9c78da28-cd28-52c2-ac2d-88b672578c7e","document_type":"judgment","category":"judicial","subcategory":"general","title":"-1قول جالل الدين السيوطي »:الشبهة ال تسقط التعزير» (األشباه والنظائر( )205/1طبعة مكتبة نزار الباز) .","document_number":"3341010","case_number":"33539297","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/12","year":"1434","subject":"-1قول جالل الدين السيوطي »:الشبهة ال تسقط التعزير» (األشباه والنظائر( )205/1طبعة مكتبة نزار الباز) .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3341010:‬تاريخه‪1433/09/12 :‬هـ‬\n                   ‫رقم الدعوى‪33539297:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3426836‬تاريخه‪1434/02/20:‬هـ‬\n\n\n‫مقاومــة قــوات الشــرطة ‪ ،‬حيــازة ســاح نــاري ‪ ،‬تهديــد باســتخدام ســاح‬\n‫نــاري ‪ ،‬عــدم ثبــوت اإلدانــة ‪ ،‬وجــود ســوابق قضائيــة ‪ ،‬الشــبهة ال تســقط‬\n                                   ‫التعزيــر ‪ ،‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n‫‪ -1‬قول جالل الدين الســيوطي‪ »:‬الشــبهة ال تســقط التعزير» (األشــباه‬\n                                 ‫والنظائــر(‪ )205/1‬طبعــة مكتبــة نزار الباز) ‪.‬‬\n‫‪ -2‬قــول ابــن جنيم‪»:‬التعزيــر يثبــت مــع الشــبهة ولــذا قالــوا يثبــت مبــا‬\n‫يثبــت بــه املــال ويجــري فيــه احللــف ويقضــى فيــه بالنكــول» (األشــباه‬\n                             ‫والنظائــر ص‪ 130‬طبعــة دار الكتــب العلميــة)‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بالهــروب مــن‬\n‫رجــال األمــن وإشــهار الســاح عليهــم والتســتر علــى مرافقــه الهــارب مــن‬\n‫رجــال األمــن وطلــب إثبــات مــا أســند إليــه وإيقــاع العقوبــة التعزيريــة عليه‬\n‫حيــث اشــتبهت الدوريــة األمنيــة بســيارة واقفــة فلمــا وقفــت بجوارهــا‬\n‫هــرب فلحقتــه فترجــل منهــا القائــد والراكــب وأشــهرا ســاحهما‬\n‫للدوريــة وتســلقا ســورا وهربــا نحــو اجلبــل ‪ ،‬بتفتيــش الســيارة ظهــر‬\n‫بأنهــا مســتأجرة ‪ ،‬باســتجواب املســتأجر أجــاب بأنــه اســتأجر الســيارة‬\n\n                                                                                       ‫‪294‬‬\n\f      ‫للمدعــى عليــه وأنهــا كانــت بحوزتــه وقــت احلادثــة ‪ ،‬أقــر املدعــى عليــه‬\n      ‫بــأن الســيارة كانــت بحوزتــه وأنــه لــم يســلمها ألحــد طيلــة مــدة عقــد‬\n      ‫األجــرة ‪ ،‬طلــب مــن املدعــي العــام البينــة فقــرر بــأن بينتــه األوراق املرفقــة‬\n      ‫باملعاملــة ‪ ،‬وبعــد االطــاع علــى األوراق املرفقــة وإلنــكار املدعــى عليــه‬\n      ‫الدعــوى‪ ،‬ولتوجــه التهمــة القويــة بقيامــه بذلــك بالقرائــن اآلتيــة‪ -1:‬مــا‬\n      ‫جــاء يف محضــر القبــض مــن قيامــه بالهــروب وإشــهاره واملرافــق معــه‬\n      ‫الســاح علــى الفرقــة القابضــة‪ -2 .‬إقــرار املدعــى عليــه حتقيقــا بــأن‬\n      ‫الســيارة املشــار لهــا يف الدعــوى قــام باســتئجارها لــه ابــن عمــه وأنهــا‬\n      ‫كانــت بحوزتــه وقــت احلادثــة ولــم يســلمها ألحــد وكانــت ســليمة متامــا‬\n      ‫ملــا اســتأجرها‪ -3 .‬وجــود ســابقة مشــابهة بالهــروب مــن رجــال األمــن‬\n      ‫ومقاومتهــم ‪ ،‬عليــه وألن الشــبهة مــن موجبــات التعزيــر ‪ ،‬وتأسيســا علــى‬\n      ‫مــا تقــدم فقــد قــررت احملكمــة مــا يلــي‪ :‬أوالً‪ /‬عــدم ثبــوت إدانــة املدعــى‬\n      ‫عليــه مبــا جــاء يف دعــوى املدعــي العــام ‪ ،‬ثاني ـاً‪ /‬تعزيــر املدعــى عليــه‬\n      ‫للشــبهة بالســجن واجللــد ‪ -‬قــرر الطرفــان عــدم القناعــة ‪ -‬صــدق احلكــم‬\n                                                              ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم وتاريــخ ‪ 1433/08/21‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقم وتاريخ ‪ 1433/08/21‬هـ ففي يوم السبت املوافق‪1433/08/24‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬بشــأن دعــوى املدعــي العــام ‪..........‬‬\n      ‫واملكلــف مبهمــة اإلشــراف علــى مكتــب االدعــاء العــام مبحاكــم‬\n\n‫‪295‬‬\n\f‫جنــران مبوجــب خطــاب رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام‬\n‫مبنطقــة جنــران رقــم ‪..........‬وتاريــخ ‪1430/12/29‬ه ـ ضــد ‪..........‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪..........‬قائــا يف دعــواه‬\n‫عليــه إنــه حيــث ورد مبحضــر مكافحــة املخــدرات أنــه يف يــوم اجلمعة‬\n‫ـاء‬\n‫املوافــق ‪1431/8/4‬ه ـ ويف متــام الســاعة اخلامســة وعشــرين دقيقــة مسـ ً‬\n‫وأثنــاء قيــام الدوريــة بعملهــا امليدانــي يف حــي ‪..........‬باجتــاه الغــرب مت‬\n‫االشــتباه يف ســيارة نــوع ‪ ....‬زرقــاء اللــون رقــم اللوحــة ‪ ..........‬يســتقلها‬\n‫شــخصان كانــت تقــف بجــوار بقالــه علــى ميــن الطريــق باجتــاه الغــرب‬\n‫وأثنــاء الوقــوف بســيارات الفرقــة الرســمي والســيارة األخــرى للتأكــد‬\n‫مــن وضعهــا الحــظ قائــد تلــك الســيارة ســيارة الفرقــة وقــام بالهــروب‬\n‫بســرعة جنونيــة ســالك ًا طريــق فرعــي باجتــاه الشــمال داخــل ذلــك احلــي‬\n‫فتمــت متابعتــه مــن قبــل الدوريــة إلــى أن وصــل داخــل ســور منــزل ونــزل‬\n‫الســائق والراكــب وأشــهر كل منهمــا ســاحا مــن نــوع مســدس باجتــاه‬\n‫الدوريــة الرســمية والذا بالفــرار مــن علــى ســور ذلــك املنــزل باجتــاه اجلبــل‬\n‫‪ ،‬علم ـ ًا بــأن الراكــب أثنــاء متابعتهمــا كان مشــهر ًا ســاحه للخــارج‬\n‫مــن نافــذة البــاب األمامــي ‪ ،‬كمــا أنــه أثنــاء متابعتهمــا مت مالحظــة‬\n‫تلــك الســيارة وهــي تنحــرف جلهــة اليســار حتتــك يف ســور أحــد املنــازل‬\n‫بالرفــرف األميــن للســيارة ممــا أدى حلــدوث تلفيــات بهــا ‪ ،‬ونظــر ًا لوجــود‬\n‫جتمهــر مــن ســكان احلــي مت نقــل الســيارة ملقــر اإلدارة وتفتيشــها ولــم‬\n‫يتــم العثــور علــى شــيء مــن املمنوعــات ‪ ،‬وعثــر داخــل الــدرج علــى عقــد‬\n‫إيجــار للســيارة املذكــورة أعــاه واتضــح مــن خاللــه بأنهــا مؤجــرة‬\n                                                                   ‫للمدعــو ‪...........‬‬\n‫وورد باحملضــر املعــد مــن قبــل وحــدة البحــث مبركــز شــرطة ‪..........‬‬\n\n\n                                                                                          ‫‪296‬‬\n\f      ‫أنــه بتاريــخ ‪1433/5/1‬ه ـ بنــاء علــى كتــاب رئيــس وحــدة البحــث رقــم‬\n      ‫بــدون وتاريــخ ‪1433/5/1‬ه ـ بشــأن طلــب البحــث عــن ‪..........‬اتضــح‬\n      ‫أنــه يتواجــد يف شــعبة الســجن العــام بنجــران علــى إثــر قضيــة جنائيــة‪.‬‬\n      ‫وبســماع أقــوال ‪........../‬أفــاد بأنــه قــام باســتئجار الســيارة املذكــورة‬\n      ‫أعــاه ل‪ ..........‬لقــرب زواج أختــه وعــدم وجــود ســيارة لديــه وأنــه ال يعلــم‬\n      ‫عمــا حصــل ‪ .‬وبســماع أقــوال املتهــم ‪.......... /‬أفــاد بأنــه كانــت معــه‬\n                                     ‫ســيارة إيجــار اســتأجرها لــه ابــن عمــه ‪...........‬‬\n      ‫وباســتجوابه أفــاد بــأن الســيارة ‪ .....‬زرقــاء اللــون رقــم اللوحــة‪..........‬‬\n      ‫قــام باســتئجارها لــه ابــن عمــه املدعــو‪ ..........‬لوجــود زواج أختــه يف تلــك‬\n      ‫الفتــرة وكان يحتــاج لســيارة وال يوجــد لديــه بطاقــة عمــل وأنــه يف يــوم‬\n      ‫اجلمعــة املوافــق ‪1431/8/4‬ه ـ وقــت وقــوع احلادثــة كانــت الســيارة‬\n      ‫بحوزتــه ومفتاحهــا معــه ولــم يعطهــا ألحــد وأن الســيارة كانــت ســليمة‬\n                            ‫متام ـ ًا عندمــا اســتأجرها ولــم يكــن بهــا أي تلفيــات ‪.‬‬\n      ‫وانتهــى التحقيــق إلــى توجيــه االتهــام لـ ـ ‪.......... /‬بالهــروب مــن رجــال‬\n      ‫األمــن وإشــهار الســاح عليهــم والتســتر علــى مرافقــه الهــارب مــن رجــال‬\n                                                                                      ‫األمــن ‪.‬‬\n                                                             ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬إقــراره حتقيقـ ًا املنــوه عنــه واملــدون علــى ص(‪ )4‬مــن دفتــر التحقيــق‬\n      ‫املرفــق لفــة رقــم (‪ )29‬ومــا ورد بســماع أقوالــه املنــوه عنــه املــدون ص (‪3‬‬\n      ‫‪ ) 4 ،‬املرفــق لفــة رقــم (‪ )24‬بــأن الســيارة كانــت بحوزتــه وقــت وقــوع‬\n                                                      ‫احلادثــة ولــم يســتعملها أحــد غيــره ‪.‬‬\n      ‫‪ -2‬شــهادة معــدي محضــر مكافحــة املخــدرات بنجــران املنــوه عنــه‬\n                                                                ‫املرفــق لفــة رقــم (‪.)10 ، 9‬‬\n\n\n‫‪297‬‬\n\f‫‪ -3‬وجــود ســابقتني لديه(مقاومــة رجــال األمــن والهــروب مــن نقطــة‬\n‫التفتيــش) قريبــة مــن الوصــف اجلرمــي ‪ ،‬همــا قرينــة علــى ســوء ســلوكه‬\n                                                                       ‫اإلجرامــي‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره و التشــديد‬\n‫عليــه لقــاء محاولــة اعتدائــه علــى رجــال األمــن اســتناد ًا لتعميــم صاحــب‬\n‫الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n‫رقــم ‪ 36717/2/5/1‬و تاريــخ ‪1431/6/11‬ه ـ و التشــديد عليــه كذلك‬\n‫لقــاء تعــدد ســوابقه التــي لــم تردعــه عقوباتهــا اســتناد ًا لتعميــم نائــب‬\n‫وزيــر الداخليــة رقــم ( ) و تاريــخ ‪1429/8/23‬هـ ـ ‪ .‬هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام يف دعــواه غيــر‬\n‫ا هكــذا أجــاب ثــم جــرى منــي ســؤال املدعــي‬        ‫صحيــح جملــة وتفصي ـ ً‬\n‫العــام هــل لديــك بينــة علــى مــا جــاء يف دعــواك فقــال ال يوجــد لــدي‬\n‫بينــة ســوى مــا جــاء يف الئحــة الدعــوى ثــم جــرى منــي تصفــح األوراق‬\n‫واالطــاع علــى أقــوال املدعــى عليــه حتقيق ـ ًا املدونــة علــى ص(‪ )4‬مــن‬\n‫دفتــر التحقيــق املرفــق علــى لفــة رقــم (‪ )29‬و املدونــة علــى ص (‪، 3‬‬\n‫‪ ) 4‬مــن امللــف املرفــق علــى لفــة رقــم (‪ )24‬كمــا جــرى منــي االطــاع‬\n‫علــى شــهادة معــدي محضــر مكافحــة املخــدرات بنجــران املرفــق‬\n‫علــى لفــة رقــم (‪ )10 ، 9‬وللتأمــل ودراســة القضيــة رفعــت اجللســة إلــى‬\n‫يــوم األحــد املوافــق ‪1433/8/25‬ه ـ الســاعة العاشــرة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1433/08/24‬ه ـ الســاعة ‪ 09:30‬احلمــد هلل وحــده وبعــد ففــي يــوم‬\n\n\n                                                                                     ‫‪298‬‬\n\f      ‫األحد املوافق‪ 1433/08/25‬هـ افتتحت اجللســة الســاعة ‪ 08:00‬وفيها‬\n      ‫حضــر املدعــى عليــه وبعــد التأمــل والدراســة وبنــاء علــى مــا ســبق مــن‬\n      ‫الدعــوى واإلجابــة و حيــث إن املدعــى عليــه قــد أنكــر هروبــه مــن فرقــة‬\n      ‫مكافحــة املخــدرات بالســيارة التــي كانــت بحوزته مــن ‪ .....‬زرقاء اللون‬\n      ‫رقــم لوحتهــا ‪..........‬وإشــهاره الســاح عليهــم و تســتره علــى الشــخص‬\n      ‫املرافــق معــه ولتوجــه التهمــة القويــة عليــه فيمــا أنكــره املؤيــدة بالقرائــن‬\n      ‫اآلتيــة ‪ -1 :‬مــا جــاء يف محضــر القبــض املتضمــن قيــام قائــد ســيارة مــن‬\n      ‫نــوع ‪ ......‬زرقــاء اللــون رقــم لوحتهــا ‪ ..........‬بالهــروب مــن فرقــة مكافحــة‬\n      ‫املخــدرات و وإشــهاره هــو واملرافــق معــه ســاح مــع نــوع مســدس باجتــاه‬\n      ‫الدوريــة الرســمية ‪ -2‬إقــرار املدعــى عليــه حتقيقـ ًا املتضمــن بأن الســيارة‬\n      ‫املشــار إليهــا قــام باســتئجارها لــه ابــن عمــه املدعــو ‪ ..........‬وأنــه يف يــوم‬\n      ‫اجلمعــة املوافــق ‪1431/8/4‬ه ـ وقــت وقــوع احلادثــة كانــت الســيارة‬\n      ‫بحوزتــه ومفتاحهــا معــه ولــم يســلمها ألي شــخص وأن الســيارة كانــت‬\n      ‫ســليمة متام ـ ًا عندمــا اســتأجرها ولــم يكــن بهــا أي تلفيــات ‪ -3‬كــون‬\n      ‫املدعــى عليــه مــن أربــاب الســوابق ولديــه ســابقة يف الهــروب مــن رجــال‬\n      ‫األمــن وســابقة يف مقاومتهــم وملــا كان مــن املقــرر فقه ـ ًا أن التعزيــر ال‬\n      ‫يســقط بالشــبهة قــال جــال الديــن الســيوطي رحمــه اهلل ‪ « :‬الشــبهة‬\n      ‫ال تســقط التعزيــر « ( األشــباه والنظائــر ‪ ،‬ص ‪ )162‬ويقــول ابــن جنيــم‬\n      ‫رحمــه اهلل ‪ « :‬التعزيــر يثبــت مــع الشــبهة ولــذا قالــوا يثبــت مبــا يثبــت بــه‬\n      ‫املــال ويجــري فيــه احللــف ويقضــى فيــه بالنكــول « ( األشــباه والنظائــر‬\n      ‫‪ ،‬ص ‪ )157‬و تأسيسـ ًا علــى جميــع مــا ســبق فقــد قــررت مــا يأتــي أو ًال ‪:‬‬\n      ‫لــم يثبــت لــدي إدانــة املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام ثانيـ ًا‬\n      ‫‪ :‬تعزيــره وذلــك بســجنه ملــدة ســنة واحــدة تبــدأ اعتبــار ًا مــن تاريــخ إدخالــه‬\n\n\n‫‪299‬‬\n\f‫الســجن وجلــده خمســن جلــده علنـ ًا تكــرر عليــه ســت مــرات بــن كل‬\n‫مــرة وأخــرى مــدة ال تقــل عــن أســبوعني لقــاء توجــه التهمــة القويــة عليــه‬\n‫بارتكابــه مــا نســب إليــه هــذا مــا ظهــر لــي و بــه حكمــت وبعــرض‬\n‫احلكــم علــى املدعــى عليــه لــم يقنــع بــه وطلــب رفــع احلكــم حملكمــة‬\n‫االســتئناف فأجبتــه لطلبــه وأفهمتــه باســتالم نســخة احلكــم بعــد عشــرة‬\n‫أيــام وتقــدمي الئحــة اعتراضيــة خــال ثالثــن يومــا مــن التاريــخ احملــدد ال‬\n‫ســتالم نســخة احلكــم كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n‫بــدون الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/25‬ه ـ الســاعة ‪ 08:30‬احلمــد هلل‬\n‫وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق القضايــا‬\n‫اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم وتاريــخ ‪/1/17‬‬\n‫‪1434‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضــي باحملكمــة‬\n‫الشــيخ ‪.......... /‬برقــم وتاريــخ ‪1433/9/12‬ه ـ اخلــاص بدعــوى املدعي‬\n‫العــام ض ـ ـ ـ ـ ــد ‪.......... /‬يف قضيــة ( الهــروب مــن رجــال األمــن وإشــهار‬\n‫الســاح عليهــم والتســتر علــى مرافقــه الهــارب مــن رجــال األمــن ) علــى‬\n‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪300‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":294,"source_page_end":300,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"9d4cd5bc41e41efc058d17a33498526150c126a694d574093bb900081e4c76c6","normalized_text_hash":"4a23a676884e3064f588d2c41ad57e801c3c55807d6bab4108ee192e0de1fed9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p294-3341010"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"77bc8385-c1a1-5d63-ae85-5efe6c6ced65","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -استخدام أداة خشبية -إحداث إصابة -إقرار املدعى عليه -تنازل املدعي اخلاص عن حقه -تعزير باجللد - نصح وتوجيه يف مجلس احلكم .","document_number":"34246203","case_number":"34121195","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/06/19","year":"1434","subject":"اعتداء -ضرب -استخدام أداة خشبية -إحداث إصابة -إقرار املدعى عليه -تنازل املدعي اخلاص عن حقه -تعزير باجللد - نصح وتوجيه يف مجلس احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34246203 :‬تاريخه‪1434/06/19:‬هـ‬\n                    ‫رقم الدعوى‪34121195:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 34638846‬تاريخه‪1434/07/18 :‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪ -‬اســتخدام أداة خشــبية ‪ -‬إحــداث إصابــة ‪ -‬إقــرار‬\n‫املدعــى عليــه ‪ -‬تنــازل املدعــي اخلــاص عــن حقــه ‪ -‬تعزيــر باجللــد ‪-‬‬\n                                  ‫نصــح وتوجيــه يف مجلــس احلكــم ‪.‬‬\n\n\n\n\n   ‫‪ -‬قوله صلى اهلل عليه وسلم ( كل املسلم على املسلم حرام دمه‬\n                                ‫وماله و عرضه ) ‪ .‬رواه مسلم ‪.‬‬\n ‫‪ -‬الشريعة اإلسالمية جاءت بحفظ الكليات اخلمس ومنها النفس‪.‬‬\n\n\n\n\n‫ادعــى املدعــي العــام علــى املدعــى عليــه باالعتــداء عمــد ًا علــى املدعــي‬\n‫اخلــاص بضربــه علــى رأســه بــأداة خشــبية و التســبب يف إصابتــه ‪ ،‬حيــث‬\n‫انتهــى التحقيــق إلــى توجيــه االتهــام إلــى املدعــى عليــه باالعتــداء عمــد ًا‬\n‫علــى املدعــي اخلــاص بضربــه علــى رأســه ‪ ،‬بــأداة خشــبية ‪ ،‬والتســبب‬\n‫بإحــداث اإلصابــة ‪ ،‬املوصوفــة يف التقريــر الطبــي ‪ ،‬و طلــب املدعــي‬\n‫العــام تعزيــر املدعــى عليــه لقــاء مــا نســب إليــه ‪ ،‬أقــر املدعــى عليــه مبــا‬\n‫جــاء بدعــوى املدعــي العــام ‪ ،‬حضــر املدعــي اخلــاص و تنــازل عــن حقــه‬\n‫اخلــاص يف هــذه الدعــوى ‪ ،‬احلكــم بتعزيــر املدعــى عليــه باجللــد مبــا‬\n‫نســب إليــه يف دعــوى املدعــي العــام ‪ ،‬احلكــم بتنــازل املدعــي اخلــاص‬\n\n                                                                                         ‫‪252‬‬\n\f      ‫عــن حقــه اخلــاص يف هــذه الدعــوى ‪ ،‬جــرى نصــح و توجيــه املدعــى عليــه‬\n      ‫مبــا يناســب احلــال ‪ ،‬قــرر املدعــي عليــه القناعــة ‪ ،‬و املدعــي العــام قــرر‬\n      ‫اعتراضــه علــى احلكــم بــدون الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة‬\n                                                                          ‫االســتئناف ‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬مســاعد رئيــس احملكمــة اجلزائيــة‬\n      ‫باملدينــة املنــورة يف يــوم األحــد ‪ .....‬الســاعة الثالثــة والربــع بعــد الظهــر‬\n      ‫ـاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n                                                             ‫أفتتحــت اجللســة األولــى بنـ ً‬\n      ‫احملكمــة اجلزائيــة برقــم (‪ ).....‬وتاريــخ ‪ ....‬واملقيــدة برقــم (‪ )....‬وتاريــخ‬\n      ‫‪ ....‬وفيهــا حضــر املدعــي العــام ‪ ...‬وقــدم الئحــة دعــواه ضــد ‪ .....‬البالــغ‬\n      ‫مــن العمــر ‪ 27‬عام ـ ًا باكســتناني اجلنســية برخصــة اإلقامــة رقــم (‪)....‬‬\n      ‫ا يف دعــواه‬   ‫املقبــوض عليــه بتاريــخ ‪ .......‬واملفــرج عنــه بتاريــخ ‪ ....‬قائ ـ ً‬\n      ‫إنتهــى التحقيــق إلــى توجيــه اإلتهــام للمدعــى عليــه ‪ ....‬باإلعتــداء عمــد ًا‬\n      ‫علــى املدعــي بضربــه علــى رأســه بــأداة خشــبية والتســبب يف إحــداث‬\n      ‫اإلصابــة املوصوفــة بالتقريــر الطبــي املرفــق ‪ ،‬وذلــك لألدلــة والقرائــن‬\n      ‫التاليــة‪ /1 -:‬مــا جــاء يف أقــوال املدعــى عليــه واملدونــة علــى صفحــة رقــم‬\n      ‫(‪ )10‬لفــة رقــم (‪ /2 .)1‬التقريــر الطبــي املنــوه عنــه املرفــق باملعاملــة لفــة‬\n      ‫رقــم (‪/3 .)4‬محضــر دوريــات األمــن املنــوه عنــه املرفــق باملعاملــة لفــة رقم‬\n      ‫(‪ .)5‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق مســجلة وحيــث أن‬\n      ‫مــا أقــدم عليــه املدعــى عليــه املذكــور فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة رادعة له‬\n      ‫وزاجــرة لغيــره علمـ ًا بــأن احلــق اخلــاص الزال قائمـ ًا هكــذا إدعــى ولعــدم‬\n\n‫‪253‬‬\n\f‫حضــور املدعــى عليــه رغــم تبلغــه مبوعــد هــذه اجللســة كمــا يف محضــر‬\n‫اإلتصــال املــؤرخ يف ‪ ......‬املرفــق باملعاملــة لــذا أجلــت اجللســة إلــى يــوم‬\n‫اإلثنــن ‪ .......‬الســاعة الثانيــة وخمــس وأربعــن دقيقــة بعــد الظهــر ويف يوم‬\n‫االثنــن ‪ .....‬أفتتحــت اجللســة الثانيــة يف موعدهــا احملــدد الســاعة الثانيــة‬\n‫وخمــس وأربعــن دقيقــة بعــد الظهــر وفيهــا حضــر املتداعيــان وبتــاوة‬\n‫دعــوى املدعــي العــام علــى املدعــى عليــه احلاضــر بعــد التأكــد مــن هويته‬\n‫أجــاب بواســطة مترجــم احملكمــة ‪ .....‬أفغانــي اجلنســية مبوجــب رخصــة‬\n‫ا مــا ذكــره املدعــي العــام مــن إتهامــي باإلعتــداء‬  ‫االقامــة رقــم (‪ ).....‬قائـ ً‬\n‫عمــد ًا علــى املدعــى عليــه بضربــه علــى رأســه بــأداة خشــبية والتســبب‬\n‫يف إحــداث إصابــة بــه موصوفــة بالتقريــر الطبــي فهــذا صحيــح وأنــا‬\n‫ال إن شــاء‬ ‫نــادم علــى فعلــي وتائــب ولــن أعــود ملثــل مــا بــدر منــي مســتقب ً‬\n‫اهلل هــذه إجابتــي وأثنــاء اجللســة حضــر املدعــي اخلــاص ‪ .....‬باكســتاني‬\n‫عمــا لديــه قــال‬\n                 ‫اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪ ).....‬وبســؤاله ّ‬\n‫بواســطة املترجــم املشــار إلــى إســمه وهويتــه أعــاه إن املدعــى عليــه ‪.....‬‬\n‫قــام باإلعتــداء علـ ّـي بالضــرب عمــد ًا علــى رأســي بــأداة خشــبية وأحــدث‬\n‫بــي إصابــة برأســي وقــد صــدر فيهــا تقريــر طبــي وإننــي أقــرر تنازلــي عنــه‬\n‫عمــا حلــق بــي مــن إصابــة وال أطالبــه بشــيء بخصوصهــا ال حاضــر ًا وال‬         ‫ّ‬\n‫ال هكــذا قــرر بحضــور وشــهادة املترجــم املشــار إليــه وكاتبــه‬          ‫مســتقب ً‬\n‫‪ .....‬والعســكري لدينــا ‪ ...‬ســعودي بالســجل املدنــي رقــم (‪ ).....‬هــذا‬\n‫وقــد جــرى اإلطــاع علــى أقــوال املدعــى عليــه املدونــة بالصفحــة رقــم‬\n‫(‪ )10‬لفــة رقــم (‪ )1‬ومحضــر دوريــات األمــن املرفــق باملعاملــة لفــة رقــم‬\n‫(‪ )5‬فوجــدا كمــا ذكــر املدعــي العــام واإلطــاع علــى التقريــر الطبــي‬\n‫املرفــق باملعاملــة لفــة رقــم (‪ )4‬الصــادر مــن مستشــفى ‪ ......‬برقــم (‪)46‬‬\n\n\n                                                                                           ‫‪254‬‬\n\f      ‫وتاريــخ ‪ .....‬ومفــاده إصابــة املدعــي ‪ ......‬بجــرح قطعــي ‪3‬ســم يف فــروة‬\n      ‫ـاء علــى مــا تقــدم مــن ســماع الدعوى‬ ‫الــرأس ومــدة الشــفاء ســبعة أيــام فبنـ ً‬\n      ‫واإلجابــة ومــا قــرره الطرفــان ونظــر ًا إلــى أن املدعــى عليــه صــادق علــى‬\n      ‫مــا جــاء يف دعــوى املدعــي العــام والشــريعة اإلســامية جــأت بحفــظ‬\n      ‫الكليــات اخلمــس ومنهــا النفــس ويف احلديــث (كل املســلم علــى املســلم‬\n      ‫حــرام دمــه ومالــه وعرضــه) رواه مســلم ونظــر ًا إلــى أن املدعــى عليــه‬\n      ‫أعلــن توبتــه وأظهــر ندامتــه وخللـ ّـو صحيفتــه مــن الســوابق اجلنائيــة وطمعـ ًا‬\n      ‫يف اســتصالحه ونظــر ًا إلــى أن املدعــي اخلــاص تنــازل عــن حقــه اخلــاص‬\n      ‫جتــاه املدعــى عليــه وألن اإلصابــة التــي حلقــت باملدعــي اخلــاص ليســت‬\n      ‫بليغــة حســبما جــاء بالتقريــر الطبــي املشــار إليــه وجلميــع مــا تقــدم قــررت‬\n                                                                                  ‫اآلتــي ‪-:‬‬\n                                                                          ‫أو ًال ‪ /‬ثبــت لـ ّ‬\n      ‫ـدي إدانــة املدعــى عليــه ‪ .....‬باإلعتــداء عمــد ًا علــى املدعــي‬\n      ‫بضربــه علــى رأســه بــأداة خشــبية والتســبب يف إحــداث اإلصابــة‬\n      ‫ـدي تنــازل املدعــي اخلــاص ‪ ....‬عــن‬ ‫املوصوفــة بالتقريــر الطبــي وثبــت لـ ّ‬\n      ‫حقــه اخلــاص عــن املدعــى عليــه بخصــوص هــذه الدعــوى وال يطالبــه فيها‬\n      ‫ال ثاني ـاً‪ /‬جلــد املدعــى عليــه ‪ .....‬ثالثــن‬‫بشــيء ال حاضــر ًا وال مســتقب ً‬\n      ‫جلــدة دفعــة واحــدة وأخــذ التعهــد املشــدد عليــه وإنــذاره مــن العــود ملثــل‬\n      ‫ال تعزيــر ًا لــه علــى مــا أديــن بــه املنصــوص عليــه يف‬\n                                                                  ‫مــا بــدره منــه مســتقب ً‬\n      ‫أو ًال مــن اإلعتــداء عمــد ًا علــى املدعــي بضربــه علــى رأســه بــأداة خشــبية‬\n      ‫والتســبب يف إحــداث اإلصابــة بــه املوصوفــة بالتقريــر الطبــي هــذا مــا‬\n      ‫ظهــر لــي وبــه حكمــت ألجــل احلــق العــام وجــرى نصــح وتوجيــه املدعــى‬\n      ‫عليــه مبــا يناســب املقــام وبإعــان احلكــم قــرر املدعــى عليــه القناعــة‬\n      ‫بــه وأبــدى املدعــي العــام اإلعتــراض علــى احلكــم وطلــب رفعــه الــى‬\n\n\n‫‪255‬‬\n\f‫محكمــة اإلســتئناف بــدون الئحــة إعتراضيــة وأقفلــت اجللســة يف متــام‬\n‫الســاعة الثالثــة بعــد الظهــر وعلــى مــا تقــدم حصــل التوقيــع وصلــى اهلل‬\n         ‫وســلم علــى نبينــا محمــد وعلــى الــه وصحبــه أجمعــن حــرر يف ‪.....‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ -:‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائيــة اخلامســة مبحكمــة االســتئناف‬\n‫يف منطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم ‪ ...‬وتاريــخ ‪ ...‬املرفــق بهــا‬\n‫القرار الصادر مـن فضيلة الشيخ ‪ ....‬مساعد رئيس باحملكمة اجلزائية‬\n‫باملدينــة املنــورة برقــم ‪ ......‬وتـ ـ ـ ـ ــاريخ ‪ .....‬الـمتضم ــن دعــوى املدعــي العام‬\n‫ضــد ‪..... /‬باكســتاني اجلنســية املتهــم يف اعتــداء‪ ،‬احملكــوم فيــه مبــا‬\n‫دون بباطــن القــرار ‪ ،‬وبدراســة القــرار وصــورة ضبطــه قررنــا املوافقــة‬\n‫علــى احلكــم ‪ ،‬واهلل املوفــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آل ـ ـ ــه‬\n                                                                        ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                              ‫‪256‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":252,"source_page_end":256,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"b4140f0001caa24a7181dca0317b17727c8bf48f7a34973618b4ae0a43ccdaa8","normalized_text_hash":"ae5ec8568deb476c34ccfe820455d6b345bda40a8efa88c5626770a43ea17a81","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p252-34246203"},{"id":"5aa7c300-fe71-5924-9aef-6f7ff35edc2d","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -التسبب بإصابة املدعية -رد دعوى املدعي العام لعدم وجود بينة -كبر سن املدعى عليها -إخاء سبيل املدعى","document_number":"34187653","case_number":"34121728","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/14","year":"1434","subject":"اعتداء -ضرب -التسبب بإصابة املدعية -رد دعوى املدعي العام لعدم وجود بينة -كبر سن املدعى عليها -إخاء سبيل املدعى","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك‪ 34187653:‬تاريخه‪1434/04/14:‬هـ‬\n                          ‫رقم الدعوى‪34121728:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34246700‬تاريخه‪1434/06/20 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬التســبب بإصابــة املدعيــة ‪ -‬رد دعــوى املدعــي العــام‬\n      ‫لعــدم وجــود بينــة ‪ -‬كبــر ســن املدعــى عليهــا ‪ -‬إخــاء ســبيل املدعــى‬\n                                                                         ‫عليهــا ‪.‬‬\n\n\n\n\n                                ‫‪ -‬قاعدة ( األصل البراءة حتى يثبت خالفها ) ‪.‬‬\n                                     ‫‪ -‬وما أشار إليه القاضي يف تسبيب احلكم ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليهــا بضرب امرأة بحــذاء على عينها‬\n      ‫اليمنــى ممــا أدى إلــى إصابتهــا ‪ُ ،‬أبلغــت الشــرطة مــن أحــد األشــخاص‬\n      ‫عــن وجــود مضاربــة يف أحــد احلدائــق ‪ ،‬وباالنتقــال إلــى املوقــع وجــد‬\n      ‫املبلــغ‪ ،‬وأفــاد أن املدعــى عليهــا قامــت بضــرب زوجتــه بحــذاء علــى‬\n      ‫عينهــا اليمنــى ‪ ،‬والتســبب بإصابتهــا ‪ ،‬و طلــب املدعــي العــام تعزيــر‬\n      ‫املدعــى عليهــا لقــاء مــا نســب إليهــا ‪ ،‬أنكــرت املدعــى عليهــا مــا جــاء‬\n      ‫بدعــوى املدعــي العــام‪ ،‬ثــم جــرى اإلطــاع علــى أوراق املعاملــة التــي‬\n      ‫قدمهــا املدعــي ‪ ،‬وباالطــاع عليهــا لــم يوجــد للمدعــي العــام بينــة علــى‬\n      ‫دعــواه كمــا قــرر انــه ليــس لديــه مــا يقدمــه مــن بينــات ســوى محضــر‬\n      ‫التعــرف مــن املدعــى عليهــا ‪ ،‬احلكــم بــرد دعــوى املدعــي العــام ضــد‬\n\n‫‪257‬‬\n\f‫املدعــى عليهــا و إخــاء ســبيلها لعــدم ثبــوت الدعــوى ‪ ،‬ارتضــت املدعــى‬\n‫عليهــا احلكــم واملدعــي العــام قــرر اعتراضــه علــى احلكــم بــدون الئحــة‬\n                ‫اعتراضيــه ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم ‪ ...‬وتاريــخ‪ ...‬املقيــدة باحملكمــة برقــم ‪....‬وتاريخ‬\n‫‪ ...‬ففــي يــوم الثالثــاء املوافــق ‪ ....‬افتتحــت اجللســة الســاعة الســاعة‬\n‫الواحــدة والنصــف ظهــر ًا وفيهــا قــدم املدعــي العــام ‪ ... /‬دعــواه علــى ‪/‬‬\n‫‪ 61 ، .....‬عام ـ ًا ‪ ،‬ســعودية اجلنســية مبوجــب الســجل املدنــي رقــم (‪)....‬‬\n‫أميــة ‪ ،‬متســببة ‪ ،‬تقيــم مبدينــة الريــاض ‪ ،‬أوقفــت بتاريــخ ‪ ..‬بســجن‬\n‫النســاء ومــدد إيقافهــا مبوجــب أمــر متديــد التوقيــف رقــم (‪ )....‬وتاريــخ ‪...‬‬\n‫اســتناد ًا للمــادة (‪ )112‬مــن نظــام اإلجــراءات اجلزائيــة ‪ ،‬حيــث إنــه بتاريخ‬\n‫‪ ...‬تســلم مركــز شــرطة ‪ ....‬تقريــر إحــدى فــرق الدوريــات األمنيــة رقــم‬\n‫(‪ )...‬واملتضمــن تلقيهــا بالغ ـ ًا مــن ‪ .... /‬عــن وجــود مضاربــة يف حديقــة‬\n‫‪ ..........‬علــى شــارع ‪ ............‬وباالنتقــال للموقــع وجــد املبلــغ وأفــاد بقيــام‬\n‫امــرأة تدعــى أم ‪( ...‬املتهمــة) بضــرب زوجتــه املجنــي عليهــا ‪ ... /‬بحــذاء‬\n‫علــى عينهــا اليمنــى والتســبب يف إصابتهــا ومت إســعافها مــن قبــل املدعــو‬\n‫‪ .... /‬وذلــك بنقلهــا للمستشــفى ‪ .‬وبســماع أقــوال املجنــي عليهــا ‪/ ....‬‬\n‫أفــادت بأنهــا أثنــاء تواجدهــا يف حديقــة ‪ ............‬بحــي ‪............‬وبرفقتهــا‬\n‫ابنيهــا ‪ ...‬و‪...‬أبنــاء ‪ ...‬شــاهدت املدعــى عليهــا تقــوم بضــرب ابنهــا الصغيــر‬\n‫‪ ...‬بحذائهــا علــى ظهــره وصــدره فحضــرت إليهــا وســألتها عــن ســبب‬\n\n                                                                                            ‫‪258‬‬\n\f      ‫قيامهــا بذلــك ثــم حصلــت مشــادة كالميــة بينهــا وبــن املدعــى عليهــا‬\n      ‫وقيامهــا برميهــا بحــذاء أصــاب عينهــا اليمنــى وصــدر بحقهــا تقرير طبي‬\n      ‫برقــم (بــدون) وتاريــخ ‪2012/10/24‬م مــن مستشــفى ‪........................‬‬\n      ‫واملتضمــن بتشــخيص حالتهــا تبــن خلــع يف عدســة العــن اليمنــى ومتــزق‬\n      ‫طبقــة العــن مصحــوب بــدم حتــت الشــبكية وحفــرة بقعيــة مغلقــة يف‬\n      ‫العــن اليمنــى ولــم حتــدد مــدة الشــفاء ‪ .‬وبتاريــخ ‪ ...‬قبــض علــى املتهمــة‬\n      ‫مــن قبــل شــرطة ‪ ............‬وإحالتهــا إلــى ســجن النســاء‪ .‬وباســتجواب‬\n      ‫املدعــى عليهــا ‪..... /‬أنكــرت ضــرب املجنــي عليهــا ‪ ....‬وأنكــرت‬\n      ‫معرفتهــا بهــا وأنــه لــم يســبق أن رأتهــا وأقــرت بحضورهــا وابنهــا حلديقــة‬\n      ‫‪ ............‬بــن الفينــة واألخــرى ‪ .‬وبســماع أقــوال ابــن املدعــى عليهــا ‪....‬‬\n      ‫‪ /‬أفــاد بأنــه يحضــر حلديقــة ‪ ............‬مــع أمــه املدعــى عليهــا وأخواتــه‬\n      ‫الصغــار شــبه يومــي وأنــه شــاهد يف إحــدى األيــام مضاربــة باأليــدي بــن‬\n      ‫امرأتــن متغطيتــن أمــام بســطة أمــه ثــم اتصلــت عليــه أمــه وطلبــت منــه‬\n      ‫احلضــور لهــا وغــادروا احل ــديقة ذاهبــن إل ــى منزلهــم ‪ .‬وبســماع أقــوال‬\n      ‫ابنــة املجنــي عليهــا ‪ / ....‬أفــادت بأنهــا أثنــاء تواجدهــا بحديقــة ‪............‬‬\n      ‫مــع أمهــا املجنــي عليهــا وأخيهــا ‪ ....‬حصلــت مشــادة كالميــة بــن أمهــا‬\n      ‫واملدعــى عليهــا بســبب قيــام املدعــى عليهــا بضــرب أخيهــا ‪ ....‬وأنهــا رأت‬\n      ‫املدعــى عليهــا تقــوم برمــي حــذاء علــى أمهــا وأصابــت عينهــا اليمنــى‬\n      ‫وســقطت مغشــي ًا عليهــا ثــم طلبــت مــن أحــد األشــخاص إســعافها فقــام‬\n      ‫بإركابهــا وأمهــا املجنــي عليهــا والذهــاب بهمــا إلى املستشــفى ‪ .‬وبســماع‬\n      ‫أقــوال الشــاهد ‪ / ....‬أفــاد بأنــه أثنــاء تواجــده بحديقــة ‪ ............‬شــاهد‬\n      ‫مشــادة كالميــة بــن مجموعــة مــن النســاء كبيــرات يف الســن فذهــب‬\n      ‫إلبــاغ الهيئــة بذلــك وأثنــاء رجوعــه شــاهد املجنــي عليهــا تصــرخ ومعهــا‬\n\n\n‫‪259‬‬\n\f‫ابنتهــا وطلبــا منــه أن يقــوم بإيصالهمــا إلــى مستشــفى ‪........................‬‬\n‫للعيــون ‪ .‬وبعــرض املدعــى عليهــا علــى املجنــي عليهــا ‪..... /‬ومعهــا امــرأة‬\n‫مشــابهة لهــا يف الشــكل اســتطاعت التعــرف عليهــا ‪ .‬ومبواجهــة املدعــى‬\n‫ال منهمــا علــى أقوالهــا وكانــت‬     ‫عليهــا باملجنــي عليهــا ‪ .../‬أصــرت ك ً‬\n‫املجنــي عليهــا تســرد وقائــع املضاربــة وأن املدعــى عليهــا هــي مــن قــام‬\n‫بضربهــا وتطلــب حقهــا الشــرعي منهــا بينمــا املدعــى عليهــا تطلــب ميــن‬\n‫املجنــي عليهــا ‪ .‬وأســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليهــا‬\n‫‪ ..... /‬بضــرب املجنــي عليهــا ‪ ....‬بحــذاء علــى عينهــا اليمنــى ممــا أدى‬\n‫إلــى إصابتهــا باإلصابــات املوصوفــة بالتقريــر الطبــي املشــار إليــه ‪ .‬وذلــك‬\n‫لألدلــة والقرائــن التاليــة‪1 :‬ـ تقريــر الدوريــات األمنيــة املنــوه عنــه املرفــق‬\n                                                               ‫علــى اللفــة رقــم (‪. )..‬‬\n‫‪2‬ـ مــا جــاء يف أقــوال املدعــى عليهــا املنــوه عنهــا املدونــة علــى الصفحــة‬\n‫رقــم (‪ )...‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪3 . )...‬ـ مــا جــاء يف ســماع‬\n‫أقــوال ‪ ...‬ابــن املدعــى عليهــا املنــوه عنهــا املدونــة علــى الصفحــة رقــم (‪)...‬‬\n‫مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪4 . )..‬ـ مــا جــاء يف ســماع أقــوال ‪.....‬‬\n‫ابنــه املجنــي عليهــا املنــوه عنهــا املدونــة علــى الصفحــة رقــم (‪ )..‬مــن دفتــر‬\n‫التحقيــق املرفــق لفــة رقــم (‪5 . )..‬ـ ماجــاء يف ســماع أقــوال ‪ .....‬املنــوه عنهــا‬\n‫املدونــة علــى الصفحــة رقــم (‪ )..‬مــن دفتــر التحقيــق املرفــق لفــة رقــم (‪. )..‬‬\n‫‪6‬ـ محضــر العــرض والتعــرف علــى املدعــى عليهــا مــن قبــل املجنــي عليهــا‬\n‫املنــوه عنــه املــدون علــى الصفحــة رقــم (‪ )..‬مــن دفتــر التحقيــق املرفــق‬\n‫لفــة رقــم (‪ . )..‬وبالبحــث عــن ســوابقها تبــن عــدم وجــود ســوابق جنائيــة‬\n‫مســجلة عليهــا حتــى تاريخــه ‪ .‬وحيــث إن مــا أقدمــت عليهــا املذكــورة‬\n‫فعــل معاقــب عليــه شــرع ًا لــذا أطلــب احلكــم عليهــا بعقوبــة تعزيريــة لقــاء‬\n\n\n                                                                                            ‫‪260‬‬\n\f      ‫مــا أســند إليهــا علم ـ ًا بــأن احلــق اخلــاص مــازال قائم ـ ًا ‪ .‬وبعــرض دعــوى‬\n      ‫املدعــي العــام علــى املدعــى عليهــا احلاضــرة يف هــذه اجللســة واملعــرف‬\n      ‫بهــا مــن قبــل ولدهــا احلاضــر معهــا ‪ ، ... /‬حامــل بطاقــة الهويــة الوطنيــة‬\n      ‫رقــم ‪ ....‬أجابــت قائلــة ‪ :‬مــا جــاء بدعــوى املدعــي العــام غيــر صحيــح وأنــا‬\n      ‫ال أعــرف هــذه املــرأة املجنــي عليهــا ولــم أضربهــا وليــس بينــي وبينهــا‬\n      ‫أي عــداوة وجميــع مــا جــاء يف الدعــوى جتاهــي غيــر صحيــح ‪ ،‬هكــذا‬\n      ‫أجابــت‪ .‬بعــد ذلــك قــررت رفــع اجللســة لدراســة أوراق املعاملــة إلــى يــوم‬\n      ‫األحــد املوافــق ‪ ...‬الســاعة العاشــرة صباحـ ًا ‪ ،‬واختتمــت اجللســة يف متــام‬\n      ‫الســاعة الثانيــة ظهــر ًا ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه‬\n      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ ...‬احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم‬\n      ‫األحــد املوافــق ‪ ...‬فتحــت اجللســة يف متــام الســاعة الواحــدة ظهــر ًا وفيهــا‬\n      ‫حضــرت املدعــى عليهــا وقــد جــرى منــا الرجــوع ألوراق املعاملــة لإلطــاع‬\n      ‫علــى البينــات التــي قدمهــا املدعــي العــام وباالطــاع عليهــا ودراســتها لــم‬\n      ‫أجــد فيهــا مــا يــدل علــى صحــة دعــوى املدعــي العــام ولــم أجــد أي قرينــة‬\n      ‫ســوى محضــر تعــرف املجنــي عليهــا علــى املدعــى عليهــا فقــط ‪ .‬بعــد‬\n      ‫ذلــك ســألت املدعــي العــام ‪ :‬هــل لديــه زيــادة بينــة ؟ فقــال ‪ :‬ليــس لــدي‬\n      ‫ســوى مــا قدمــت ‪ .‬فبنــاء علــى مــا تقــدم ومبــا أنــه ال بينــة لــدى املدعــي‬\n      ‫العــام علــى دعــواه ومبــا أن األصــل عــدم صحــة هــذه الدعــوى واألصــل‬\n      ‫البــراءة حتــى يثبــت خالفهــا ومبــا أن مجــرد محضــر التعــرف مــن قبــل‬\n      ‫املجنــي عليهــا ال يكفــي التهامهــا الســيما مــع كبــر ســن املدعــى عليهــا‬\n      ‫إذ أن عمرهــا قــد جتــاوز الســتني كمــا يتضــح ذلــك مــن أوراق املعاملــة‬\n      ‫وكــرت العائلــة العائــد لزوجهــا إضافــة إلــى عــدم وجــود ســوابق لــدى‬\n      ‫املدعــى عليهــا ‪ .‬لذلــك كلــه فقــد حكمــت بــرد دعــوى املدعــي العــام‬\n\n\n‫‪261‬‬\n\f‫جتــاه املدعــى عليهــا وأخليــت ســبيل املدعــى عليهــا وقــررت إطالقهــا‬\n‫بالكفالــة احلضوريــة بنــاء علــى املــادة (‪ )216‬مــن نظــام اإلجــراءات‬\n‫اجلزائيــة ‪ .‬وبعــرض ذلــك علــى املدعــى عليهــا واملدعــي العــام قــررت‬\n‫املدعــى عليهــا القناعــة باحلكــم وقــرر املدعــي العــام االعتــراض بــدون‬\n‫الئحــة اعتراضيــة ‪ .‬واختتمــت اجللســة يف متــام الســاعة الواحــدة والنصــف‬\n‫ظهــر ًا ‪ ،‬وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n                                                                       ‫حــرر يف ‪...‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة الرابعــة‬\n‫مبحكمــة االســتئناف بالريــاض علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪ ...‬وتاريــخ ‪ ...‬املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ ....‬املســجل‬\n‫برقــم ‪ ...‬وتاريــخ ‪ ...‬اخلــاص بدعــوى املدعــي العــام ضــد‪ ...... /‬يف قضيــة‬\n‫مضاربــة علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه مبــا‬\n‫هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫نقــرر باألكثريــة املصادقــة علــى احلكــم مــع تنبيــه فضيلتــه إلــى إثبــات‬\n‫ال حســب النظــام واهلل املوفــق‬    ‫اإلدانــة مــن عدمهــا قبــل احلكــم مســتقب ً‬\n                       ‫صلــى اهلل علــى نبينــا محمــد و آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                       ‫‪262‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":257,"source_page_end":262,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"315b24d15c35c5f04e0a52a4be8c82956ede12eac827d50045610d9e01340de8","normalized_text_hash":"676ff8e0911c23e19d8032f748ca1f9cec2bfbc0626d730ea88b9cee64159e09","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p257-34187653"},{"id":"9cbef568-8c67-5c44-be24-13f2294f18f6","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -تهديد رجل أمن -التعدي بالقول على رجل أمن -اعتداء بالضرب على أحد املوقوفن -التعدي بألفاظ غير الئقة إحداث فوضى بداخل التوقيف -إقرار املدعى عليه مبا جاء بدعوى املدعي العام -التعزير باجللد .","document_number":"34295817","case_number":"34137366","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/08/14","year":"1434","subject":"اعتداء -ضرب -تهديد رجل أمن -التعدي بالقول على رجل أمن -اعتداء بالضرب على أحد املوقوفن -التعدي بألفاظ غير الئقة إحداث فوضى بداخل التوقيف -إقرار املدعى عليه مبا جاء بدعوى املدعي العام -التعزير باجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34295817 :‬تاريخه‪1434/08/14:‬هـ‬\n                         ‫رقم الدعوى‪34137366:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34332145‬تاريخه‪1434/10/18 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬تهديــد رجــل أمــن ‪ -‬التعــدي بالقــول علــى رجــل‬\n      ‫أمــن ‪ -‬اعتــداء بالضــرب علــى أحــد املوقوفــن ‪ -‬التعــدي بألفــاظ غيــر‬\n      ‫الئقــة ـ إحــداث فوضــى بداخــل التوقيــف ‪ -‬إقــرار املدعــى عليــه مبــا جــاء‬\n                                        ‫بدعــوى املدعــي العــام ‪ -‬التعزيــر باجللــد ‪.‬‬\n\n\n\n\n      ‫‪ -‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                 ‫مالــه و عرضــه ) راوه مســلم ‪.‬‬\n      ‫‪ -‬الشــريعة اإلســامية جــاءت بحفــظ الكليــات اخلمــس منهــا النفــس‬\n                                                                       ‫والعــرض ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي العــام علــى املدعــى عليــه بتهديــد رجــل أمــن والتعــدي‬\n      ‫عليــه بألفــاظ غيــر الئقــة و االعتــداء بالضــرب علــى أحــد املوقوفــن‬\n      ‫أثنــاء ايقافــه ‪ ،‬انتهــى التحقيــق إلــى اتهــام املدعــى عليــه بذلــك وبإحــداث‬\n      ‫فوضــى بداخــل التوقيــف ‪ ،‬وطلــب املدعــي العــام تعزيــر املدعــى عليــه‬\n      ‫لقــاء مــا نســب إليــه‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف دعــوى املدعــي‬\n      ‫العــام‪ ،‬صــدر احلكــم بتعزيــر املدعــى عليــه باجللــد لقــاء مــا نســب إليــه‬\n      ‫يف دعــوى املدعــي العــام‪ ،‬قــرر املدعــى عليــه و املدعــي العــام اعتراضهمــا‬\n\n‫‪263‬‬\n\f‫علــى احلكــم بــدون الئحــة ‪ ،‬صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬مســاعد رئيــس احملكمــة اجلزائيــة‬\n‫باملدينة املنورة يف يوم اإلثنني ‪ .....‬أفتتحت اجللســة األولى يف متام الســاعة‬\n‫ـاء علــى املعاملــة احملالة إلينــا من فضيلة رئيس‬      ‫الثانيــة والنصــف ظهــر ًا بنـ ً‬\n‫احملكمــة اجلزائيــة باملدينــة املنــورة برقــم (‪ )....‬وتاريــخ ‪ .....‬واملقيــدة برقــم‬\n‫(‪ )....‬وتاريــخ ‪ .....‬وفيهــا حضــر املدعــي العــام ‪ .....‬وقــدم الئحــة دعــواه‬\n‫ضــد ‪ .....‬البالــغ مــن العمــر (‪ )26‬عامـ ًا ســعودي اجلنســية بالســجل املدنــي‬\n‫ا‬\n‫رقــم (‪ )......‬املقبــوض عليــه بتاريــخ ‪ ....‬واملوقــوف بالســجن العــام‪ .‬قائ ـ ً‬\n‫يف دعــواه إنتهــى التحقيــق إلــى إتهــام املدعــى عليــه بتهديــد رجــل أمــن‬\n‫والتلفــظ عليــه بألفــاظ غيــر الئقــة واإلعتــداء بضــرب املوقــوف ‪... /‬‬\n‫باحلــذاء والتلفــظ علــى املواقيــف بألفــاظ غيــر الئقــة وإحــداث فوضــى‬\n‫بداخــل التوقيــف‪ .‬وذلــك لألدلــة والقرائــن التاليــة ‪ /1 -:‬مــا ورد بأقــوال‬\n‫املدعــى عليــه املدونــة علــى الصفحــة رقــم (‪ )2،1‬مــن ملــف التحقيــق لفــة‬\n‫رقــم (‪ /2 .)6‬محضــر خفيــر التوقيــف املرفــق باملعاملــة لفــة رقــم (‪)2‬‬\n‫وأقوالــه املدونــة علــى الصفحــة رقــم (‪ )15‬مــن ملــف اإلســتدالل لفــة رقــم‬\n‫(‪ /3 .)1‬أقــوال املواقيــف املدونــة علــى الصفحــة رقــم (‪)12،11،10،9‬‬\n‫مــن ملــف اإلســتدالل لفــة رقــم (‪ .)1‬وبالبحــث عــن ســوابقه لــم يعثــر لــه‬\n‫علــى ســوابق مســجلة باســمه‪ ،‬وحيــث أن مــا اقــدم عليــه املدعــى عليــه‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب ‪ /1 -:‬إثبــات مــا أســند إليه‪.‬‬\n‫‪ /2‬احلكــم عليــه بعقوبــة تعزيريــة‪ .‬علمـ ًا أن احلــق اخلــاص مــا زال قائمــا‪،‬‬\n‫هكــذا إدعــى ولــم يحضــر املدعــى عليــه رغــم طلبــه بخطابنــا رقــم ‪.....‬‬\n\n                                                                                            ‫‪264‬‬\n\f      ‫وتاريــخ ‪ .....‬املوجــه إلــى مديــر شــعبة امــن احملاكــم الشــرعية وقــد وردنــا‬\n      ‫خطــاب مديــر شــعبة أمــن احملاكــم الشــرعية برقــم (‪)5/358/22‬‬\n      ‫وتاريــخ ‪ ......‬املتضمــن بــأن املدعــى عليــه غيــر موقــوف يف الســجن العــام‬\n      ‫لــذا جــرى رفــع اجللســة إلــى يــوم األربعــاء ‪ ......‬وأمــرت بالكتابــة إلــى‬\n      ‫اجلهــة املختصــة إلحضــار املدعــى عليــه يف موعــد اجللســة املشــار إليــه‬\n      ‫أعــاه وأفهمــت بــه املدعــي العــام ويف يــوم األربعــاء ‪ .....‬أفتتحــت اجللســة‬\n      ‫الثانيــة يف موعدهــا احملــدد الســاعة الثانيــة وخمــس وأربعــن دقيقــة‬\n      ‫بعــد الظهــر وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه وقــد‬\n      ‫ســبق الكتابــة إلــى مركــز شــرطة ‪ .....‬بخطابنــا رقــم (‪ )....‬وتاريــخ ‪.....‬‬\n      ‫املتضمــن إحضــار املدعــى عليــه يف موعــد هــذه اجللســة ولــم يتــم إحضــاره‬\n      ‫ولــم تردنــا اإلفــادة علــى خطابنــا املشــار إليــه حتــى تاريخــه لــذا أجلــت‬\n      ‫اجللســة إلــى يــوم اإلثنــن ‪ .....‬الســاعة الثالثــة بعــد الظهــر وأفهمــت بــه‬\n      ‫املدعــي العــام وأمــرت بالكتابــة إلــى اجلهــة املختصــة إلحضــار املدعــى‬\n      ‫عليــه يف املوعــد احملــدد أعــاه واإلفــادة عــن خطابنــا الســابق ويف يــوم‬\n      ‫االثنــن ‪ ......‬افتتحــت اجللســة الثالثــة يف موعدهــا احملــدد الســاعة الثالثــة‬\n      ‫بعــد الظهــر وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه وقــد‬\n      ‫ســبق الكتابــة إلــى مركــز شــرطة ‪ .....‬بخطابنــا رقــم (‪ ).....‬وتاريــخ ‪......‬‬\n      ‫وباخلطــاب التعقيبــي رقــم (‪ )....‬وتاريــخ ‪....‬إلحضــار املدعــى عليــه ولــم يتــم‬\n      ‫إحضــاره ولــم تردنــا اإلفــادة علــى اخلطابــات املشــار إليهــا حتــى تاريخــه‬\n      ‫لــذا أجلــت اجللســة إلــى يــوم اإلثنــن ‪ ...‬الســاعة الثالثــة والربــع بعــد الظهــر‬\n      ‫وأفهمــت بــه املدعــي العــام وأمرت بالكتابة إلــى اجلهة املختصة إلحضار‬\n      ‫املدعــى عليــه يف املوعــد احملــدد أعــاه واإلفــادة عــن املخاطبــات الســابقة‬\n      ‫ويف يوم اإلثنني ‪ ......‬افتتحت اجللســة الرابعة يف موعدها احملدد الســاعة‬\n\n\n‫‪265‬‬\n\f‫الثالثــة والربــع بعــد الظهــر وفيهــا حضر املدعي العــام ولم يحضر املدعى‬\n‫عليــه وقــد ســبق الكتابــة إلــى مركــز شــرطة ‪ .....‬بخطابنــا رقــم (‪).....‬‬\n‫وتاريــخ ‪ .....‬وباخلطابــن التعقيبيــن رقــم (‪ ).....‬وتاريــخ ‪ .....‬ورقــم (‪)......‬‬\n‫وتاريــخ ‪ .....‬إلحضــار املدعــى عليــه ولــم يتــم إحضــاره ولــم تردنــا اإلفــادة‬\n‫علــى املخطابــات املشــار إليهــا حتــى تاريخــه لــذا أجلــت اجللســة إلــى يــوم‬\n‫اإلثنــن ‪ ....‬الســاعة الثالثــة بعــد الظهــر وأفهمــت بــه املدعــي العــام وأمــرت‬\n‫بالكتابــة إلــى اجلهــة املختصــة إلحضــار املدعــى عليــه يف املوعــد احملــدد‬\n                                     ‫أعــاه واإلفــادة عــن املخاطبــات الســابقة ‪.‬‬\n‫ويف يوم االثنني ‪ ......‬افتتحت اجللسة اخلامسة يف موعدها احملدد الساعة‬\n‫الثالثــة بعــد الظهــر وفيهــا حضــر املدعــي العــام ولــم يحضــر املدعــى عليــه‬\n‫وقــد ســبق الكتابــة إلــى مركــز شــرطة ‪ .....‬بخطابنــا رقــم (‪ )....‬وتاريــخ‬\n‫‪ .....‬وباملخاطبــات التعقيــب رقــم (‪ ).......‬وتاريــخ ‪ .....‬ورقــم (‪ ).....‬وتاريــخ‬\n‫‪ ......‬و رقــم (‪ )......‬وتاريــخ ‪ .....‬إلحضــار املدعــى عليــه ولــم يتــم إحضــاره‬\n‫ولــم تردنــا اإلفــادة علــى املخطابــات املشــار إليهــا حتــى تاريخــه لــذا أجلــت‬\n‫اجللســة إلــى يــوم الســبت ‪......‬الســاعة الثانيــة عشــر ظهــر ًا وأفهمــت بــه‬\n‫املدعــي العــام وأمــرت بالكتابــة إلــى اجلهــة املختصــة إلحضــار املدعــى‬\n‫عليــه يف املوعــد احملــدد أعــاه واإلفــادة عــن املخاطبــات الســابقة ويف‬\n‫يــوم الســبت ‪ .....‬أفتتحــت اجللســة السادســة يف موعدهــا احملــدد الســاعة‬\n‫الثانيــة عشــر ظهــر ًا وفيهــا حضــر املدعــي العــام واملدعــى عليــه ‪ ....‬وبعــد‬\n‫التأكــد مــن هويتــه املشــار إليهــا أعــاه جــرى تــاوة دعــوى املدعــي العــام‬\n‫ا مــا ذكــره املدعــي العــام مــن إتهامــي بتهديــد رجــل‬   ‫عليــه فأجــاب قائـ ً‬\n‫أمــن والتلفــظ عليــه بألفــاظ غيــر الئقــة واإلعتــداء بضــرب املوقــوف ‪/‬‬\n‫‪ .....‬باحلــذاء والتلفــظ علــى املواقيــف بألفــاظ غيــر الئقــة وإحــداث فوضى‬\n\n\n                                                                                         ‫‪266‬‬\n\f      ‫بداخــل التوقيــف فهــذا كلــه صحيــح وإننــي نــادم علــى فعلــي وتائــب منــه‬\n      ‫ال إن شــاء اهلل هــذه إجابتــي هــذا‬    ‫ولــن أعــود ملثــل مــا بــدر منــي مســتقب ً‬\n      ‫وقــد جــرى اإلطــاع علــى مــا جــاء يف أقــوال املدعــى عليــه املدونــة علــى‬\n      ‫الصفحــة رقــم (‪ )2-1‬مــن ملــف التحقيــق املرفــق باملعاملــة وعلــى محضــر‬\n      ‫خفيــر التوقيــف املرفــق باملعاملــة لفــة رقــم (‪ )2‬وأقــوال املدعــى عليــه‬\n      ‫املدونــة علــى الصفحــة رقــم (‪ )15‬مــن ملــف اإلســتدالل وأقــوال املواقيــف‬\n      ‫ـاء علــى مــا تقــدم‬‫املدونــة علــى الصحيفــة رقــم (‪ )13-12-11-10-9‬فبنـ ً‬\n      ‫مــن ســماع الدعــوى واإلجابــة ومــا قــرره الطرفــان ونظــر ًا إلــى أن املدعــى‬\n      ‫عليــه صــادق علــى مــا جــاء يف دعــوى املدعــي العــام ونظــر ًا إلــى أن املدعى‬\n      ‫عليــه تعــدى بقولــه وفعلــه والشــريعة اإلســامية جــاءت بحفــظ الكليــات‬\n      ‫اخلمــس ومنهــا النفــس والعــرض ويف احلديــث (كل املســلم علــى املســلم‬\n      ‫حــرام دمــه ومالــه وعرضــه) رواه مســلم ونظــر ًا إلــى خلـ ّـو صحيفــة املدعــى‬\n      ‫عليــه مــن الســوابق اجلنائيــة وإعالنــه التوبــة والنــدم‪ ،‬وقصــد ًا الســتصالح‬\n               ‫املدعــى عليــه وجلميــع مــا تقــدم قــررت اآلتــي ‪ -:‬أو ًال ‪ /‬ثبــت لـ ّ‬\n      ‫ـدي إدانــة‬\n      ‫املدعــى عليــه ‪ ......‬بتهديــد رجــل أمــن والتلفــظ عليــه بألفــاظ غيــر الئقــة‬\n      ‫واإلعتــداء بضــرب املوقــوف ‪ .... /‬باحلــذاء والتلفــظ علــى املواقيــف‬\n      ‫بألفــاظ غيــر الئقــة وإحــداث فوضــى بداخــل التوقيــف‪ .‬ثاني ـاً‪ /‬جلــد‬\n      ‫املدعــى عليــه ســبعني جلــدة دفعــة واحــدة وأخــذ التعهــد املشــدد عليــه‬\n      ‫ال تعزيــر ًا لــه علــى مــا‬\n                                  ‫وإنــذاره مــن العــود إلــى مثــل مــا بــدر منــه مســتقب ً‬\n      ‫أديــن بــه املنصــوص عليــه يف أو ًال مــن تهديــد رجــل أمــن والتلفــظ عليــه‬\n      ‫بألفــاظ غيــر الئقــة واإلعتــداء بضــرب املوقــوف ‪ .... /‬باحلــذاء والتلفــظ‬\n      ‫علــى املواقيــف بألفــاظ غيــر الئقــة وإحــداث فوضــى بداخــل التوقيــف‬\n      ‫هــذا مــا ظهــر لــي وبــه حكمــت ألجــل احلــق العــام وجــرى نصــح وتوجيــه‬\n\n\n‫‪267‬‬\n\f‫املدعــى عليــه مبــا يناســب املقــام وبإعــان احلكــم قــرر املدعــى عليــه‬\n‫عــدم القناعــة بــه وطلــب رفعــه إلــى محكمــة اإلســتئناف بــدون الئحــة‬\n‫إعتراضيــة وأبــدى املدعــي العــام اإلعتــراض علــى احلكــم وطلــب رفعــه‬\n‫إلــى محكمــة اإلســتئناف بــدون الئحــة إعتراضيــة وأمــرت برفــع احلكــم‬\n‫مــع كامــل متعلقاتــه إلــى محكمــة اإلســتئناف لتدقيقــه حســب املتبــع‬\n‫وأقفلــت اجللســة يف متــام الســاعة الثانيــة عشــر والنصــف بعــد الظهــر‬\n‫وعلــى مــا تقــدم حصــل التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد‬\n                                         ‫وعلــى الــه وصحبــه أجمعــن حــرر يف ‪....‬‬\n‫احلمــد هلل وحــده والصــاة والســام علــى رســول اهلل ‪ ...‬وبعــد‪ -:‬فقــد‬\n‫جــرى منــا نحــن قضــاة الدائــرة اجلزائية الســابعة يف محكمة اإلســتئناف‬\n‫مبنطقــة مكــة املكرمــة اإلطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة باملديــة املنــورة برقــم ‪ ....‬وتاريــخ ‪ ....‬املرفــق بهــا‬\n‫القــرار الصــادر مــن فضيلــة الشــيخ‪ .... /‬القاضــي باحملكمــة اجلزائيــة‬\n‫باملدينــة املنــورة برقــم ‪ .....‬وتاريــخ ‪ .....‬احملكــوم فيــه مبــا دون بباطــن‬\n‫القــرار املتضمــن دعــوى املدعــي العــام ضــد‪ ..... /‬املتهــم يف تهديــد رجــل‬\n‫األمــن وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم‪.‬‬\n‫واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                           ‫‪268‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":263,"source_page_end":268,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"c4d1f6b4dc2b8c4deefe49943008f30fd3006636b0725b0e03be8b59ca304309","normalized_text_hash":"9a0030d1b766ad041f701ac2e31f1c2c20cedf3348fd148ca26c389f65cfc34a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p263-34295817"},{"id":"5937168e-52b6-571f-aeff-4dc70b6896db","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -إحداث إصابات -الشروع يف القتل -دعوى عامة ( حق عام ) -دعوى خاصة ( حق خاص) -تنازل املجني عليه «الزوجة» أحد موجبات تخفيف العقوبة التعزيرية -الشروع يف اجلرمية بالقيام ببعض أسبابها أو مقدماتها موجب للتعزير - التعزير للشبهة (تهمة ) لقيام قرائن على صحة التهمة -تقرير طبي -تعزير بالسجن وأخذ التعهد.","document_number":"34283926","case_number":"34283109","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/30","year":"1434","subject":"اعتداء -ضرب -إحداث إصابات -الشروع يف القتل -دعوى عامة ( حق عام ) -دعوى خاصة ( حق خاص) -تنازل املجني عليه «الزوجة» أحد موجبات تخفيف العقوبة التعزيرية -الشروع يف اجلرمية بالقيام ببعض أسبابها أو مقدماتها موجب للتعزير - التعزير للشبهة (تهمة ) لقيام قرائن على صحة التهمة -تقرير طبي -تعزير بالسجن وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 34283926 :‬تاريخه‪1434/7/30 :‬هـ‬\n                          ‫رقم الدعوى‪34283109:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34351947‬تاريخه‪1434/11/5 :‬هـ‬\n\n\n\n      ‫اعتــداء ‪ -‬ضــرب ‪ -‬إحــداث إصابــات ‪ -‬الشــروع يف القتــل ‪ -‬دعــوى عامــة‬\n      ‫( حــق عــام ) ‪ -‬دعــوى خاصــة ( حــق خــاص) ‪ -‬تنــازل املجنــي عليــه‬\n      ‫«الزوجــة» أحــد موجبــات تخفيــف العقوبــة التعزيريــة ‪ -‬الشــروع يف‬\n      ‫اجلرميــة بالقيــام ببعــض أســبابها أو مقدماتهــا موجــب للتعزيــر ‪-‬‬\n      ‫التعزيــر للشــبهة (تهمــة ) لقيــام قرائــن علــى صحــة التهمــة ‪ -‬تقريــر‬\n                                      ‫طبــي ‪ -‬تعزيــر بالســجن وأخــذ التعهــد‪.‬‬\n\n\n\n\n                                          ‫ما أشار له القاضي يف تسبيب احلكم ‪.‬‬\n\n\n\n\n      ‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بالشــروع يف قتــل‬\n      ‫زوجتــه واالعتــداء بضربهــا ممــا أدى إلصابتهــا باإلصابــات املوصوفــة‬\n      ‫بالتقريــر الطبــي وطلــب إيقــاع العقوبــة التعزيريــة عليــه حيــث تقدمــت‬\n      ‫املدعيــة اخلاصــة ببــاغ بــأن املدعــى عليــه (زوجهــا) ضربهــا وأشــهر عليهــا‬\n      ‫الســكني مهــددا لهــا بقتلهــا ‪ ،‬وبعــد هــذه احلادثــة بأيــام دخــل عليهــا يف‬\n      ‫غرفتهــا ببيــت أهلهــا وهددهــا بالقتــل ورأت بحوزتــه ســكينا‪ ،‬وصــدر‬\n      ‫تقريــر طبــي يوضــح اإلصابــات التــي نالــت املدعيــة ‪ ،‬أنكــر املدعى عليه‬\n      ‫التهمــة وقــرر بــأن يحصــل بينــه وبــن زوجتــه مشــاكل عائليــة ‪ ،‬حضــر‬\n\n‫‪269‬‬\n\f‫وكيــل املدعيــة اخلاصــة وقــرر بــأن موكلتــه متنازلــة عــن املدعــى عليــه‬\n‫وال تطلــب منــه أرشــا وال تأديبــا وال بينــة لديهــا علــى مــا اتهــم بــه املدعــي‪،‬‬\n‫وأنهــا تطلــب منــه أن يقــوم بحقوقهــا ويعاشــرها باملعــروف ويكــف أذاه‬\n‫عنهــا وعــن أســرتها ‪ ،‬وبالعــرض علــى املدعــى عليــه قــرر التزامــه بالقيــام‬\n‫باحلقــوق الزوجيــة والعشــرة احلســنة وأن هــذه طريقتــه منــذ تزوجهــا ‪،‬‬\n‫تبــن مــن صحيفــة ســوابق املدعــي عــدم تســجيل ســابقة عليــه ‪ ،‬قــدم‬\n‫املدعــى عليــه تقريــرا طبيــا صــادرا مــن أحــد املراكــز الطبيــة مضمونــه‬\n‫بــأن املدعــى عليــه يعانــي مــن اضطــراب ذهانــي ضاللــي ومصــاب بوهــم‬\n‫االعتقــادات والشــكوك ‪ ،‬عليــه ونظــرا لتنــازل املدعيــة اخلاصــة ‪،‬‬\n‫ولتطلــع الشــرع لبنــاء احليــاة الزوجيــة علــى الوفــاق والوئــام ‪ ،‬ولعــدم‬\n‫وجــود دليــل يســتند عليــه يف إدانــة املدعــى عليــه ‪ ،‬لكــن تتوجــه التهمــة‬\n‫علــى املدعــى عليــه لــذا فقــد قــررت احملكمــة احلكــم باالكتفــاء مبــا‬\n‫أمضــاه املدعــى عليــه يف التوقيــف ألجــل هــذه القضيــة أي مــدة شــهرين‬\n‫إعتبــارا مــن تاريــخ توقيفــه وأخــذ التعهــد عليــه بإلتــزام األدب والنظــام‬\n‫واحلــذر مــن الوقــوع يف املخالفــات وكــف أذاه عــن زوجتــه وأســرتها‬\n‫والقيــام باحلقــوق الزوجيــة والعشــرة احلســنة ‪ ،‬ورأت معاجلــة املدعــى عليــه‬\n‫يف مستشــفى متخصــص حتــى تتحســن حالتــه ‪ ،‬عــرض احلكــم علــى‬\n‫املدعيــة اخلــاص واملدعــى عليــه وقــررا القناعــة ‪ ،‬وأمــا املدعــي العــام‬\n‫فقــرر عــدم القناعــة وطلــب اســتئنافه بــدون الئحــة ‪ ،‬صــدق احلكــم مــن‬\n                                                              ‫محكمــة االســتئناف ‪.‬‬\n\n\n\n\n                                                                                           ‫‪270‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة‬\n      ‫اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪1434/06/19‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم وتاريــخ ‪1434/06/19‬ه ـ ففــي يــوم األحــد املوافــق‬\n      ‫‪1434/07/30‬ه ـ افتتحــت اجللســة الســاعة ‪ 01:00‬وفيهــا قــدم املدعــي‬\n      ‫العــام ‪...........‬املــدرع دعــواه ضــد ‪ 39 ،........... /‬عام ـ ًا ‪ ،‬ســعودي‬\n      ‫اجلنســية‪ ،‬مبوجــب الســجل املدنــي رقــم (‪ )...........‬يقيــم مبدينــة الريــاض‬\n      ‫‪ ،‬أوقــف بتاريــخ ‪ 1434/6/1‬ه ـ وأحيــل للســجن العــام مبوجــب أمــر‬\n      ‫اإلحالــة ومتديــد التوقيــف رقــم ‪...........‬وتاريــخ ‪1434/6/13‬ه ـ اســتناد ًا‬\n      ‫للمــادة (‪ )113‬مــن نظــام اإلجــراءات اجلزائيــة ‪.‬فبتاريــخ ‪1434/5/28‬ه ـ‬\n      ‫تقدمــت ملركــز شــرطة ‪...........‬املجنــي عليهــا‪........... /‬مبلغــة عــن‬\n      ‫تعرضهــا للضــرب مــن قبــل زوجهــا املدعــى عليــه أعــاه وصــدر بحقهــا‬\n      ‫تقريــر طبــي مــن املديريــة العامــة للشــئون الصحيــة مبنطقــة الريــاض‬\n      ‫برقــم (‪ )...........‬وتاريــخ ‪1434/5/28‬ه ـ املتضمــن وجــود كدمــات‬\n      ‫بالســاعد األميــن وبالعضــد األيســر وكدمــة بالشــفة العليــا وكدمــات‬\n      ‫بالســاقني واملذكــورة حامــل يف الشــهر الرابــع ولــم حتــدد مــدة الشــفاء‬\n      ‫‪.‬وبضبــط بــاغ املجنــي عليهــا وســماع أقوالهــا‪ /‬أفــادت أن املدعــى عليــه‬\n      ‫قــام وقــت احلادثــة األولــى يــوم االثنــن املوافــق ‪1434/5/27‬ه ـ حوالــي‬\n      ‫الســاعة العاشــرة صباحـ ًا باالســتئذان لهــا وألطفالهــا مــن الروضــة ‪........‬‬\n      ‫ب‪ ...........‬وقــام بإنــزال األطفــال عنــد منــزل والدتــه الــذي نقيــم فيــه ثــم‬\n      ‫توجــه بهــا إلــى اســتراحة والدتــه ‪ ...........‬وعنــد وصولهــم االســتراحة‬\n\n‫‪271‬‬\n\f‫قــام املدعــى عليــه بســحبها علــى األرض وإدخالهــا بالقــوة واالعتــداء‬\n‫عليهــا بالضــرب بحذائــه وضغطهــا علــى احلائــط واألرض وأشــهر عليهــا‬\n‫ا (ســوف أقتلــك وأذبحــك) وتكلــم عليهــا‬     ‫ســكني متوســطة احلجــم قائـ ً‬\n‫بــكالم بذيــئ وأخــذ يتكلــم عــن صــورة شــاهدها يف االنترنــت يقــول‬\n‫بأنهــا لهــا وتفيــد أيضـ ًا أنهــا قامــت بتهدئتــه وبعدهــا أخذهــا ملنزلهــم عنــد‬\n‫والدتــه ب‪...........‬وأنهــا قامــت باالتصــال علــى أخوهــا‪........... /‬فحضــر‬\n‫إلــى ‪...........‬وأخذهــا ملنــزل أهلهــا بحــي ‪...........‬بالريــاض ‪.‬ويف يــوم‬\n‫الثالثــاء املوافــق ‪1434/5/28‬ه ـ فجــر ًا حوالــي الســاعة اخلامســة صباح ًا‬\n‫تفاجــأت بدخولــه عليهــا يف غرفتهــا يف بيــت أهلهــا بحــي ‪...........‬بالرياض‬\n‫وكان البــس بيجامــة ومغطــى وجهــه والبــس قفــازات وقــام بوضــع قطعــة‬\n‫قمــاش مبلولــة مبــاء يف فمهــا مــردد ًا (ســوف أقتلــك وأذبحــك) وكالم‬\n‫بــذئ ويقــول (ســوف أصــل إليــك يف أي مــكان تذهبــن إليــه) وتفيــد بعــد‬\n‫تهدئتهــا لــه رأتــه يضــع ســكني يف شــنطة أحضرهــا معــه لــم تشــاهدها‬\n‫حــن دخولــه وبســؤالها عــن كيفيــة دخولــه منــزل أهلهــا أفــادت باحتمال‬\n‫أنــه أخــذ مفتاحهــا اخلــاص بهــا ألنها حني خروجها مــن بيتهم ب‪ ...........‬لم‬\n‫تأخــذ معهــا ســوى مالبســها التــي عليهــا وبســؤالها عــن عــدم اســتنجادها‬\n‫بأهلهــا أفــادت بأنهــا لــم تســتطيع ألنــه كان واضع ـ ًا علــى فمهــا قطعــة‬\n‫قمــاش مبلولــة باملــاء ‪.‬وباســتجواب املدعــى عليــه‪ /‬أنكــر مــا تدعــي بــه‬\n‫املجنــي عليهــا املدعيــة بتات ـ ًا وذكــر أنــه يوجــد بينــه وبينهــا مشــاكل‬\n‫قبــل حوالــي ســتة أشــهر حــول صــورة مشــابهة لهــا وجدهــا باإلنترنــت‬\n‫‪.‬وبإجــراء محضــر مواجهــة بينهمــا وبعــرض ادعــاء املجنــي عليهــا علــى‬\n‫املدعــى عليــه وإنــكار املدعــى عليــه علــى املدعيــة تبــن لنــا قــوة حجــة‬\n                                                ‫املدعيــة يف ادعاءهــا ملــا يلــي ‪:‬‬\n\n\n                                                                                         ‫‪272‬‬\n\f                                                  ‫‪ -1‬استشهادها بوالدة املدعى عليه ‪.‬‬\n      ‫‪ -2‬وجــود ســبب دافــع لقيــام املدعــى عليــه باالعتــداء علــى املجنــي عليهــا‬\n      ‫وهــو الشــك فيهــا ويــدل علــى ذلــك طلبــه أثنــاء املواجهــة حتليــل (‪)DNA‬‬\n                                                               ‫ألبناءه‪...............................‬‬\n                             ‫‪ -3‬التقرير الطبي يثبت وجود حالة االعتداء بالضرب ‪.‬‬\n      ‫‪ -4‬يؤكــد وقــوع االعتــداء يف وقتــه املذكــور واعتــراف املدعــى‬\n      ‫عليــه أثنــاء املواجهــة بحضــوره إلــى الروضــة التــي تعمــل فيهــا املدعيــة‬\n                                                         ‫واالســتئذان لهــا وألطفالهــا ‪.‬‬\n      ‫وأســفر التحقيــق بتوجيــه االتهــام للمدعــى عليــه‪...................... /‬‬\n      ‫بالشــروع يف قتــل زوجتــه‪........... /‬واالعتــداء بضربهــا ممــا أدى إلصابتهــا‬\n      ‫باإلصابــات املوصوفــة بالتقريــر الطبــي املشــار إليــه‪ .‬وذلــك لألدلــة‬\n                                                                           ‫والقرائــن األتيــة ‪:‬‬\n                                      ‫‪ -1‬ما جاء بالتقرير الطبي املشار إليه املرفق ‪.‬‬\n                              ‫‪ -2‬ما جاء مبحضر املواجهة املدون من ملف التحقيق ‪.‬‬\n          ‫وببحث سوابقه اتضح عدم وجود سوابق مسجله عليه حتى تاريخه ‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــور فعــل معاقــب عليــه شــرع ًا لــذا‬\n      ‫أطلــب احلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا أســند إليــه ‪ ،‬علم ـ ًا بــأن‬\n      ‫احلــق اخلــاص مــازال قائم ـ ًا ‪ .‬هــذه دعــواي ‪ ،‬وبســؤال املدعــى عليــه‬\n      ‫أجــاب بقولــه إن مــا ذكــره املدعــي العــام غيــر صحيــح ودعــوى زوجتــي‬\n      ‫وبالغهــا غيــر صحيــح ولكــن يحصــل بينــي وبــن زوجتــي مشــاكل‬\n      ‫عائليــة هكــذا أجــاب فطلبــت مــن املدعــي العــام البينــة فقــال بينتــي‬\n      ‫مــا يف أوراق املعاملــة وبــاغ املدعيــة بذلــك هــذا وقــد حضــر ‪...........‬‬\n      ‫ســعودي بالهويــة رقــم (‪ )...........‬الوكيــل الشــرعي عــن ‪......................‬‬\n\n\n‫‪273‬‬\n\f‫ســعودية بالهويــة رقــم (‪ )...........‬مبوجــب صــك الوكالــة الصــادرة مــن‬\n‫كاتــب العــدل بــوزارة العــدل برقــم ‪...........‬يف ‪1434/07/25‬ه ـ املخــول‬\n‫لــه فيهــا باملرافعــة واملدافعــة واملخاصمــة واملخالصــة واملطالبــة ضــد‬\n‫زوجهــا ‪......................‬والصلــح والتنــازل واإلقــرار ‪ ...‬الــخ وقــال إن هــذا‬\n‫احلاضــر املدعــى عليــه زوج ملوكلتــي وبينهمــا أوالد وليــس لدينــا بينــة‬\n‫علــى الضــرب والشــروع يف القتــل وموكلتــي متنازلــه عــن حقهــا اخلــاص‬\n‫وال تطالــب بــأرش وال تأديــب ولكــن تطلــب منــه أن يقــوم بحقوقهــا‬\n‫ويعاشــرها باملعــروف ويكــف أذاه عنهــا وعــن أســرتها وأنــي بحضــوري‬\n‫ال هكــذا قــرر بطوعــه‬    ‫أقــرر تنــازل موكلتــي عنــه ال حاضــر ًا وال مســتقب ً‬\n‫واختيــاره وبعــرض ذلــك علــى املدعــى عليــه ‪...........‬قــال إننــي التــزم علــى‬\n‫نفســي بالقيــام باحلقــوق الزوجيــة والعشــرة احلســنة وهــذه طريقتــي منــذ‬\n‫أن تزوجتهــا هــذا وقــد أبــرز أحــد املراجعــن للمدعــى عليــه تقريــر ًا‬\n‫طبي ـ ًا صــادر ًا مــن مركــز مطمئنــة مفــاده أن املدعــى عليــه يعانــي مــن‬\n‫اضطــراب ذهانــي ضاللــي ومصــاب بوهــم االعتقــادات والشــكوك‬\n‫فبنــاء علــى مــا تقــدم وإلــى مــا تضمنتــه أوراق املعاملــة ونظــر ًا النتهــاء‬\n‫احلــق اخلــاص بالتنــازل وحيــث أن الشــرع ينظــر إلــى بنــاء احليــاة الزوجيــة‬\n‫وإلــى الوفــاق والوئــام بــن الزوجــن وحيــث لــم يثبــت علــى املدعــى عليــه‬\n‫مــا أســفر إليــه التحقيــق لعــدم وجــود دليــل يســتند إليــه ولكــن تتوجــه‬\n‫التهمــة عليــه يف ذلــك لــذا قــررت االكتفــاء مبــا أمضــاه املدعــى عليــه‬\n‫يف التوقيــف وهــو مــدة شــهرين اعتبــار ًا مــن تاريــخ توقيفــه ويؤخــذ عليــه‬\n‫التعهــد بالتــزام األدب والنظــام واحلــذر مــن الوقــوع يف املخالفــات وكــف‬\n‫أذاه عــن زوجتــه وأســرتها والقيــام باحلقــوق الزوجيــة والعشــرة احلســنة وبه‬\n‫حكمــت وأرى معاجلــة املدعــى عليــه يف مستشــفى حتــى تتحســن حالتــه‬\n\n\n                                                                                         ‫‪274‬‬\n\f      ‫وبعــرض احلكــم علــى احملكــوم عليــه واملدعــي اخلــاص وكالــة قــرروا‬\n      ‫القناعــة أمــا املدعــي العــام فطلــب اســتئنافه بــدون الئحــة اعتراضيــة‪.‬‬\n      ‫وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n      ‫وســلم ‪ .‬حــرر يف ‪1434/07/30‬ه ـ ‪ .‬احلمــد هلل وحــده وبعــد فقــد اطلعنــا‬\n      ‫نحــن قضــاة الدائــرة اجلزائيــة األولــى مبحكمــة االســتئناف بالريــاض‬\n      ‫علــى املعاملــة الــواردة مــن مســاعد رئيــس احملكمــة اجلزائيــة بالريــاض‬\n      ‫برقــم وتاريــخ ‪1434/10/7‬ه ـ واملرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n      ‫القاضــي باحملكمــة ‪...........‬برقــم وتاريــخ ‪1434/7/30‬ه ـ واخلــاص‬\n      ‫بدعــوى املدعــي العــام ضــد ‪ ،........... /‬وموضوعهــا ضــرب وانتهــاء‬\n      ‫الدراســة والتدقيــق املصادقــة علــى احلكــم لعــدم موجــب املالحظــة مــع‬\n      ‫تنبيــه فضيلتــه إلــى الشــرح علــى وكالــة صــورة املدعــي املرفقــة الصــادرة‬\n      ‫مــن املدعــي عليــه أصالــة بأنهــا مطابقــة ألصلهــا‪ .‬واهلل املوفــق وصلــى اهلل‬\n                           ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــة وســلم ‪.‬‬\n\n\n\n\n‫‪275‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":269,"source_page_end":275,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"bacbf2fb586b5b5e27e8c8a299d1445316235d8becc950b7f90c1739d23287be","normalized_text_hash":"1b43bfe02d4887291354abd0c52ebf0b8b344ed940e53a811e0552da8d40b472","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p269-34283926"},{"id":"06840413-ada4-50c3-92e3-4a329693f08f","document_type":"judgment","category":"judicial","subcategory":"general","title":"دعوى إيذاء ووضع حجارة وبهائم ميتة على الطريق العام -عدم البينة -إمهال املدعى العام إحضار بينة -عجز املدعى العام على إحضار بينته -حلف املدعى عليهما على نفي الدعوى -صرف النظر عن احلقن العام واخلاص.","document_number":"34203552","case_number":"34786739","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":"الدائرة اجلزائية األولى برفقها القرار رقم 34259198وتاريخ","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/01","year":"1434","subject":"دعوى إيذاء ووضع حجارة وبهائم ميتة على الطريق العام -عدم البينة -إمهال املدعى العام إحضار بينة -عجز املدعى العام على إحضار بينته -حلف املدعى عليهما على نفي الدعوى -صرف النظر عن احلقن العام واخلاص.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 34203552:‬تاريخه‪1434/04/01:‬هـ‬\n                   ‫رقم الدعوى‪34786739 :‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n       ‫تاريخه‪1434/8/15 :‬هـ‬   ‫‪34297067‬‬\n\n\n\n‫دعــوى إيــذاء ووضــع حجــارة وبهائــم ميتــة علــى الطريــق العــام ‪ -‬عــدم‬\n‫البينــة ‪ -‬إمهــال املدعــى العــام إحضــار بينــة ‪ -‬عجــز املدعــى العــام علــى‬\n‫إحضــار بينتــه ‪ -‬حلــف املدعــى عليهمــا علــى نفــي الدعــوى ‪ -‬صــرف‬\n                                      ‫النظــر عــن احلقــن العــام واخلــاص‪.‬‬\n\n\n\n\n‫‪ -‬قولــه صلــى اهلل عليــه وســلم‪ ( :‬البينــة علــى املدعــي واليمــن علــى‬\n                                                           ‫املدعــى عليــه )‬\n‫‪ -‬مــا جــاء يف كشــاف القنــاع‪ ( :)337/4( :‬وال يجــوز للقاضــي احلكــم‬\n                              ‫برؤيــة خــط الشــاهد احتياط ـ ًا للحكــم )‪.‬‬\n                            ‫‪ -‬املادة (‪ )120‬من نظام املرافعات الشرعية‪.‬‬\n                             ‫‪ -‬املادة (‪ )169‬من نظام اإلجراءات اجلزائية‪.‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليهمــا بوضــع احلجــارة والبهائــم علــى الطريــق‬\n‫عمــد ًا ممــا تســبب يف حــدوث تلفيــات لســيارتني وكذلــك حــدوث‬\n‫اإلصابــة المــرأة باإلصابــة املوصوفــة بالتقريــر الطبــي املرفــق ‪ ،‬بعــرض‬\n‫ذلــك علــى املدعــى عليهمــا أنكراهــا جملــة وتفصيــا وبعــرض ذلــك‬\n‫علــى املدعــي العــام طلــب مهلــة إلحضــار البينــة‪ ،‬حضــر املدعــي باحلــق‬\n\n                                                                                    ‫‪280‬‬\n\f      ‫اخلــاص وادعــى علــى املدعــى عليهمــا أنهمــا قامــا بوضــع أحجــار وبهائــم‬\n      ‫ميتــة يف وســط الطريــق ‪ ،‬وأثنــاء مــروره وطــئ هــذه األشــياء فخــرج‬\n      ‫عــن الطريــق وتلفــت الســيارة‪ ،‬وبعــرض دعــوى املدعــي باحلــق اخلــاص‬\n      ‫علــى املدعــى عليهمــا أنكراهــا‪ ،‬وبطلــب البينــة مــن املدعــي باحلــق‬\n      ‫اخلــاص طلــب ميــن املدعــى عليهمــا علــى نفــي دعــواه فقــط‪ ،‬وبعــرض‬\n      ‫ذلــك علــى املدعــى عليهمــا حلــف كل واحــد منهمــا اليمــن علــى نفــي‬\n      ‫دعــوى املدعــي باحلــق اخلــاص‪ ،‬نظــر ًا ألن املدعــى عليهمــا أنكــرا دعــوى‬\n      ‫املدعــي جملــة وتفصيــا‪ ،‬ونظــر ًا ألن املدعــي لــم يقــم بينــة علــى دعــواه‬\n      ‫وطلــب ميــن املدعــى عليهمــا علــى نفــي ذلــك‪ ،‬وألن املدعــى عليهمــا أديــا‬\n      ‫اليمــن املطلوبــة منهمــا علــى نفــي دعوى املدعي‪ ،‬لــذا مت احلكم بصرف‬\n      ‫النظــر عــن دعــوى املدعــي اخلــاص والعــام وإخــاء ســبيل املدعــى عليهمــا‬\n      ‫مــن هــذه الدعــوى‪ ،‬بعــرض احلكــم علــى املدعــي واملدعــى عليهمــا قرروا‬\n      ‫القناعــة وقــرر املدعــي العــام االعتــراض وجــرى تصديــق احلكــم مــن‬\n                                                               ‫محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫‪281‬‬\n\f‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ففــي‬\n‫هــذا اليــوم الســبت ‪1434/4/20‬هـ ـ الســاعة احلاديــة عشــرة والنصــف‬\n‫صباح ـ ًا لــدي أنــا ‪......‬القاضــي يف احملكمــة اجلزائيــة بتبــوك فتحــت‬\n‫ـاء علــى املعاملــة الــواردة لــي مــن هيئــة التحقيــق واالدعــاء العــام‬\n                                                                         ‫اجللســة بنـ ً‬\n‫برقــم ‪ 6032‬وتاريــخ ‪1433/9/10‬ه ـ واحملالــة لــي بشــرح فضيلــة الرئيس‬\n‫رقــم ‪ 34786739‬وتاريــخ ‪1434/4/1‬هـ ـ وفيهــا حضــر املدعــي العــام ‪......‬‬\n‫ســعودي مبوجــب الســجل املدنــي رقــم ‪ ،......‬واملعمــد مــن مرجعــه مبوجب‬\n‫ا يف تقريــر دعــواه بصفتــي‬   ‫اخلطــاب رقــم ‪ 13058‬يف ‪1433/9/5‬ه ـ قائـ ً‬\n‫مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء لفــرع الهيئــة مبنطقــة تبــوك أدعــي علــى‪/‬‬\n‫‪...... -1‬ســعودي اجلنســية مبوجب ســجل مدني يرقم ‪...... -2......‬ســعودي‬\n‫اجلنســية مبوجــب ســجل مدنــي رقــم ‪ ،......‬باالطــاع علــى احملضــر املعــد‬\n‫مــن قبــل نقطــة أمــن الظلفــة بتاريــخ ‪1433/5/22‬ه ـ أنــه يف متــام الســاعة‬\n‫العاشــرة مســاء وقــع حادثــن بســبب قيــام أشــخاص غيــر معروفــن‬\n‫بوضــع أحجــار وبهائــم ميتــة علــى الطريــق عمــد ًا مت القبــض علــى احلدثني‬\n‫‪ ......‬و ‪ ......‬مــن قبــل نقطــة أمــن مركــز ‪......‬وبســماع أقــوال املقيــم ‪......‬‬\n‫أفــاد بأنــه وقــع لــه حــادث بســبب وضــع أحجــار وبهائــم ميتــة علــى الطريق‬\n‫ممــا تســبب يف إحــداث تلفيــات يف ســيارته مــن نــوع ‪ ......‬وبســماع أقــوال‬\n‫املواطــن ‪......‬أفــاد بأنــه كان معــه يف الســيارة ‪......‬كمــا أفــاد بأنــه‬\n‫تعــرض للحــادث بســبب وجــود أحجــار وبهائــم ميتــة علــى الطريــق ممــا‬\n‫تســبب يف إحــداث تلفيــات يف ســيارته مــن نــوع ‪ .....‬وقــد قــدرت قيمــة‬\n‫التلفيــات للســيارة مــن نــوع ‪ .....‬بأربعــة وثالثــن ألــف وتســعمائة واثنــن‬\n\n                                                                                          ‫‪282‬‬\n\f      ‫وثمانــن ريــا ًال وقــد قــدرت قيمــة التلفيــات للســيارة مــن نــوع ‪ .....‬بتســع‬\n      ‫وخمســن ألــف ريــال وخمســمائة وســتة عشــر ريــاال وبســماع شــهادة‬\n      ‫احلــدث ‪......‬أفــاد بــأن املدعــى عليهمــا طلبــا منــه الذهــاب معهــم لوضــع‬\n      ‫احلجــارة والبهائــم امليتــة علــى الطريــق فرفــض ذلــك وقامــوا بتهديــده إن‬\n      ‫أخبــر أحــد بذلــك وقــد صــدر التقريــر الطبــي بحــق ‪......‬رقــم (‪)......‬‬\n      ‫وتاريــخ ‪1433/6/22‬ه ـ مــن مستشــفى ‪......‬العــام املتضمــن وجــود رض‬\n      ‫بســيط علــى األنــف أدى إلــى رعــاف بســيط ومــدة الشــفاء يومــان مالــم‬\n      ‫حتــدث مضاعفــات ‪ ،‬وقــد أســفر التحقيــق عــن توجيــه االتهــام للمدعــى‬\n      ‫عليهمــا ‪......‬بوضــع احلجــارة والبهائــم علــى الطريــق عمــد ًا ممــا تســبب يف‬\n      ‫حــدوث تلفيــات لســيارتني وكذلــك حــدوث اإلصابــة المــرأة باإلصابــة‬\n      ‫املوصوفــة بالتقريــر الطبــي املرفــق وذلــك لألدلــة والقرائــن التاليــة ‪-1‬‬\n      ‫شــهادة احلــدث املدونــة علــى اللفــة رقــم (‪ -2 )34‬مــا جــاء بالتقارير الطبية‬\n      ‫املرفــق لفــة رقــم (‪ -3 )15-13‬مــا جــاء يف تقاريــر قيمــة التلفيــات املرفــق‬\n      ‫لفــة رقــم (‪ )43‬ورقــم (‪ )39-38‬وحيــث أن مــا أقــدم عليــه املذكــوران‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرعا لــذا أطلــب ‪ -1‬إثبــات مــا أســند إليهمــا‬\n      ‫‪ -2‬احلكــم عليهمــا بعقوبــة بديلــة اســتنادا لقــرار مجلــس الــوزراء رقــم‬\n      ‫(‪ )169‬وتاريــخ ‪1429/6/19‬ه ـ علم ـ ًا بــأن احلــق اخلــاص ال زال قائم ـ ًا )‬\n      ‫هــذه دعــواي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليهمــا أجــاب كل واحــد‬\n      ‫ا ‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي بوضــع احلجــارة‬      ‫منهمــا قائ ـ ً‬\n      ‫والبهائــم علــى الطريــق عمــد ًا ممــا تســبب يف حــدوث تلفيــات لســيارتني‬\n      ‫وكذلــك حــدوث اإلصابــة المــرأة باإلصابــة املوصوفــة بالتقريــر الطبــي‬\n      ‫املرفــق ‪ ،‬فهــذا غيــر صحيــح ‪ ،‬هكــذا أجــاب كل واحــد مــن املدعــى‬\n      ‫ا ‪ :‬مــا ذكرتــه‬  ‫عليهمــا ‪ ،‬وبعــرض ذلــك علــى املدعــي العــام أجــاب قائ ـ ً‬\n\n\n‫‪283‬‬\n\f‫هــو الصحيــح ولــدي بينــة علــى ذلــك أطلــب إمهالــي ألجــل إحضارهــا ‪،‬‬\n‫هكــذا أجــاب املدعــي العــام ‪ ،‬ثــم حضــر يف هــذه اجللســة املدعــي اخلاص‬\n‫‪ ،......‬ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪......‬فادعــى ضــد‬\n‫ا يف حتريــر دعــواه‬     ‫احلاضريــن معــه يف مجلــس احلكــم الشــرعي قائ ـ ً‬\n‫عليهمــا ‪ :‬لقــد قــام هــذان احلاضــران املدعــى عليهمــا بوضــع أحجــار‬\n‫وبهائــم ميتــة يف وســط طريــق ‪......‬يف تبــوك ‪ ،‬وأثنــاء مــروري قمــت بــوطء‬\n‫هــذه األشــياء فخرجــت عــن الطريــق وتلفــت ســيارتي مــن نــوع ‪ ، ......‬وقــد‬\n‫قــدرت تلفيــات الســيارة املذكــورة مببلــغ قــدره تســعة وخمســون ألف ـ ًا‬\n‫وخمســمائة وســتة عشــر ريــا ًال ‪ ،‬أطلــب إلزامهمــا بدفعهــا لــي حــا ًال هــذه‬\n‫دعــواي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليهمــا أجــاب كل واحــد منهمــا‬\n‫ا ‪ :‬مــا ذكــره املدعــي اخلــاص غيــر صحيــح ‪ ،‬هذه إجابتــي ‪ ،‬وبطلب‬           ‫قائـ ً‬\n‫البينــة أجــاب بقولــه ‪ :‬ال بينــة لــدي ســوى مــا جــاء يف شــهادة احلــدث وال‬\n‫أريــد إحضــاره وأطلــب ميــن املدعــى عليهمــا علــى نفــي دعــواي فقــط هــذه‬\n‫إجابتــي ‪ ،‬وبعــرض ذلــك علــى املدعــى عليهمــا اســتعدا بذلــك فجــرى‬\n‫حتذيرهمــا مــن مغبــة اليمــن الكاذبــة فتفهمــا ذلــك فأذنــت لــه فحلــف‬\n‫كل واحــد منهمــا ‪ :‬بقولــه ( أقســم بــاهلل العظيــم املهلــك املــدرك خالــق‬\n‫الســموات واألرض أننــي لــم أقــم بوضــع حجــارة وبهائــم ميتــة علــى طريــق‬\n‫‪......‬بتبــوك وال أعلــم مــن قــام بذلــك ‪ ،‬كمــا أقســم بــاهلل العظيــم أنــي لــم‬\n‫أتســبب باحلــادث الــذي حصــل للمدعــي اخلــاص ‪......‬بســبب وضــع احلجــارة‬\n‫والبهائــم امليتــة أقســم بــاهلل العظيــم علــى ذلــك ) هكــذا حلــف‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة وألن املدعــى‬    ‫املذكــوران فبنـ ً‬\n‫عليهمــا أنكــرا دعــوى املدعــي جملــة وتفصيــا ولقولــه صلــى اهلل عليــه‬\n‫وســلم ( البينــة علــى املدعــي واليمــن علــى املدعــى عليــه ) ونظــر ًا ألن‬\n\n\n                                                                                        ‫‪284‬‬\n\f      ‫املدعــي لــم يقــم بينــة علــى دعــواه وطلــب ميــن املدعــى عليهمــا علــى نفــي‬\n      ‫ذلــك وألن املدعــى عليهمــا أديــا اليمــن املطلوبــة منهمــا علــى نفــي دعــوى‬\n      ‫املدعــي لــذا فقــد قــررت صــرف النظــر عــن دعــوى املدعــي اخلــاص‬\n      ‫وأخليــت ســبيل املدعــى عليهمــا مــن هــذه الدعــوى يف احلــق اخلــاص هــذا‬\n      ‫مــا ظهــر لــي وبــه حكمــت وبعرضــه علــى الطرفــن قــررا القناعــة‬\n      ‫والرضــا ‪ ،‬هــذا مــا جــرى نظمــه يف احلــق اخلــاص ‪ ،‬أمــا احلــق العــام فحيــث‬\n      ‫ال مانــع مــن طلــب املدعــي العــام رفــع اجللســة ألجــل إحضــار شــاهده ‪،‬‬\n      ‫فقــد جــرى رفــع اجللســة حلــن إحضــار املدعــي العــام لبينتــه ‪ ،‬وحــددت‬\n      ‫موعــد ًا لســماعها وذلــك يف يــوم الســبت القــادم ‪1434/4/27‬ه ـ الســاعة‬\n      ‫العاشــرة صباحـ ًا وعليــه جــرى التوقيــع احلمــد هلل وحــده وبعــد ففــي هــذا‬\n      ‫اليــوم الســبت املوافــق ‪1434/4/27‬ه ـ الســاعة احلاديــة عشــر صباح ـ ًا‬\n      ‫فتحــت اجللســة وفيهــا حضــر املدعــي العــام واملدعــى عليهمــا وبســؤال‬\n      ‫املدعــي العــام عــن بينتــه التــي وعــد بإحضارهــا أجــاب بقولــه لــم أســتطع‬\n      ‫إحضــار الشــهود وأطلــب مهلــة ألجــل إحضارهــم مــرة أخــرى هكــذا‬\n      ‫قــرر املدعــي العــام وحيــث األمــر كذلــك فقــد قــررت رفــع اجللســة‬\n      ‫وحــددت موعــد ًا جديــد ًا لســماع البينــة وذلــك يف يــوم األربعــاء املوافــق‬\n      ‫‪1434/5/1‬ه ـ الســاعة العاشــرة صباح ـ ًا وأفهمــت املدعــي العــام أنــه‬\n      ‫ســيعد عاجــز ًا عــن إحضــار بينتــه يف حــال لــم يحضرهــا يف املوعــد القادم‬\n      ‫فتفهــم ذلــك وعليــه جــرى التوقيــع وصلــى اهلل وســلم علــى ســيدنا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم حــرر يف الســاعة احلاديــة عشــر وعشــر دقائــق‬\n      ‫مــن ضحــى يــوم الســبت املوافــق ‪1434/4/27‬ه ـ ثــم يف جلســة أخــرى‬\n      ‫فتحــت اجللســة ‪ ،‬وفيهــا حضــر املدعــي العــام واملدعــى عليهما ‪ ،‬وبســؤال‬\n      ‫املدعــي العــام عــن بينتــه التــي وعــد بإحضارهــا أجــاب بقولــه ‪ :‬أقــرر‬\n\n\n‫‪285‬‬\n\f‫االكتفــاء مبــا ورد يف املعاملــة مــن أدلــة وقرائن هــذه إجابتي ‪،‬وباالطالع‬\n‫علــى مــا ذكــره املدعــي العــام مــن بينــات لــم أجــد فيهــا مــا يديــن املدعــى‬\n‫ـاء علــى مــا تقــدم مــن الدعــوى واإلجابــة‪،‬‬‫عليهمــا مبــا نســب إليهمــا ‪ ،‬فبنـ ً‬\n‫وإلنــكار املدعــى عليهمــا مــا نســب إليهمــا ‪ ،‬ونظــر ًا لعجــز املدعــى العــام‬\n‫عــن إحضــار بينتــه وال بينــه ســواها ونظــر ًا لكــون الشــبهة ال تتوجــه علــى‬\n‫املدعــى عليهمــا مبــا نســبه لهمــا املدعــي العــام ‪ ،‬وألن الشــهادة ال بــد أن‬\n‫تــؤدى مشــافهة يف مجلــس احلكــم ملــا نــص عليــه الفقهــاء ‪ ،‬ومــن ذلــك‬\n‫قولهــم ( وال يجــوز للقاضــي احلكــم برؤيــة خــط الشــاهد احتياط ـ ًا‬\n‫للحكــم ) انظــر كشــاف القنــاع (‪ ، )337/4‬وقــد نــص نظــام املرافعات‬\n‫الشــرعية مــاده (‪ )120‬علــى أنــه ال يجــوز االســتعانة يف أداء الشــهادة‬\n‫مبذكــرات مكتوبــة بــل يجــب أن تــؤدى شــفوي ًا ‪ ،‬كمــا نــص نظــام‬\n‫اإلجــراءات اجلزائيــة علــى أن الشــهادة ال بــد أن تــؤدى يف مجلــس القضــاء‬\n‫كمــا يف املــادة (‪ ، )169‬ونظــر ًا ألن تخلــف الشــاهد عــن احلضــور يعتبــر‬\n‫ا علــى تراجعــه عــن الشــهادة ومعلــوم أن الشــاهد يف حقــوق اهلل‬             ‫دلي ـ ً‬\n‫تعالــى ال يلــزم باحلضــور وألن الشــاهد واحلالــة هــذه يعتبــر مجهــول احلــال‪،‬‬\n‫وإذا اقتــرن مــع ذلــك كلــه كــون الشــاهد حــدث ‪ ،‬معلــوم كالم أهــل‬\n‫العلــم يف شــهادة األحــداث وقبولهــا مــن عدمهــا ‪،‬لذلــك كلــه فقــد قررت‬\n‫صــرف النظــر عــن دعــوى املدعــي العــام ‪ ،‬وأخليت ســبيل املدعــى عليهما‬\n‫مــن هــذه الدعــوى ‪ ،‬هــذا مــا ظهــر لــي وبــه حكمــت ‪ ،‬وبعرضــه علــى‬\n‫األطــراف قــرر املدعــى عليهمــا قناعتهمــا بــه ‪ ،‬وقــرر املدعــي العــام‬\n‫االعتــراض بالئحــة فأجبتــه إلــى طلبــه ‪ ،‬وجــرى إفهامــه أن لــه مــدة‬\n‫ثالثــن يوم ـ ًا لتقــدمي الالئحــة وأنــه إن مضــت املــدة ولــم يقــدم اعتراضــه‬\n‫فيســقط حقــه يف االعتــراض ويرفــع احلكــم حملكمــة االســتئناف‬\n\n\n                                                                                          ‫‪286‬‬\n\f      ‫لتدقيقــه مــن دون الئحــة ‪ ،‬فتفهــم ذلــك ‪ ،‬ثــم جــرى تســليمه نســخة مــن‬\n      ‫القــرار ليبــدأ ميعــاد االعتــراض مــن تاريــخ احلكــم ‪ ،‬وعليــه جــرى‬\n      ‫التوقيــع وصلــى اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعني‬\n      ‫حــرر يف الســاعة العاشــرة والنصــف مــن ضحــى يــوم األربعــاء‬\n      ‫‪1434/5/1‬ه ـ احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت‬\n      ‫‪1434/7/15‬ه ـ الســاعة العاشــرة صباحـ ًا فتحــت اجللســة ‪ ،‬وفيهــا وردت‬\n      ‫املعاملــة مــن أصحــاب الفضيلــة يف محكمــة االســتئناف مبنطقــة تبــوك‬\n      ‫الدائــرة اجلزائيــة األولــى برفقهــا القــرار رقــم ‪ 34259198‬وتاريــخ‬\n      ‫‪1434/7/4‬ه ـ واملتضمــن مــا يلــي ( وبدراســة القــرار وصــورة ضبطــه‬\n      ‫وأوراق املعاملــة والالئحــة االعتراضيــة لوحــظ أن شــهادة احلــدث ‪......‬لهــا‬\n      ‫أثــر يف القضيــة ولــم يحضــر ألداء مــا لديــه ولــم يوضــح املدعــي العــام‬\n      ‫ســبب تعــذر إحضــاره وال مــا اتخــذه مــن إجــراء يف ســبيل ذلــك مــع أن‬\n      ‫للمحكمــة اســتدعاء أي شــاهد تــرى يف ســماع أقوالــه إظهــار احلقيقــة‬\n      ‫كمــا ورد يف نظــام اإلجــراءات اجلزائيــة ‪ ،‬ملالحظــة مــا ذكــر وإكمــال‬\n      ‫الــازم وإحلــاق مــا يجريــه يف الضبــط وصورتــه والقــرار ومــن ثــم إعــادة‬\n      ‫املعاملــة واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم)‬\n      ‫فأقــول مســتعين ًا بــاهلل ومجيب ـ ًا أصحــاب الفضيلــة بالنســبة لشــهادة‬\n      ‫الشــاهد ‪......‬فقــد مت طلبــه عــن طريــق املدعــي العــام أكثــر مــن مــرة ‪،‬‬\n      ‫ثــم قــرر املدعــي العــام أخيــر ًا عجــزه عــن إحضــاره بعــد إمهالــه مــن‬\n      ‫احملكمــة مــدة كافيــة إلحضــار بينتــه ‪ ،‬كمــا أن الشــاهد احلــدث‬\n      ‫‪ ........‬يقيــم بعيــد ًا عــن تبــوك مبســافة تربــو علــى املائــة كيلــو ‪ ،‬ورمبــا‬\n      ‫كان هــذا مــن األســباب التــي أدت إلــى عــدم حضــوره ‪ ،‬ومــع ذلــك فــإن‬\n      ‫عــبء إثبــات الدعــوى منصــب علــى املدعــي العــام وفيمــا يقــرره من عجزه‬\n\n\n‫‪287‬‬\n\f‫أو رغبتــه وقدرتــه علــى إثبــات دعــواه ‪ ،‬هــذا مــا لــزم إيضاحــه ‪ ،‬واهلل‬\n‫املوفــق ‪ ،‬وأشــكر أصحــاب الفضيلــة جلميــل توجيههــم ونقدهــم ‪ ،‬هــذا‬\n‫وقــد قــررت إعــادة املعاملــة ألصحــاب الفضيلــة يف محكمــة االســتئناف‬\n‫مبنطقــة تبــوك لتقريــر مــا يرونــه ‪ ،‬حــرر يف الســاعة العاشــرة والنصــف‬\n                                        ‫من ضحى يوم السبت ‪1434/7/15‬هـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلزائيــة األولى‬\n‫لتدقيــق القضايــا اجلزائيــة يف محكمــة االســتئناف مبنطقــة تبــوك علــى‬\n‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بتبــوك برقــم‬\n‫‪......‬وتاريــخ ‪1434/7/16‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيلــة‬\n‫الشــيخ‪...... /‬رقــم ‪......‬وتاريــخ ‪1434/5/1‬ه ـ اخلــاص بدعــوى املدعــي‬\n‫العــام ضــد‪...... /‬ورفيقــه ســعوديي اجلنســية يف قضيــة ايــذاء الغيــر علــى‬\n‫النحــو املوضــح يف القــرار واملتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه‪ .‬وباالطــاع علــى مــا أحلقــه فضيلتــه جواب ـ ًا لقــرار الدائــرة‬\n‫رقــم ‪ 34259198‬وتاريــخ ‪1434/7/4‬ه ـ تقــرر املصادقــة علــى احلكــم‬\n‫بعــد اإلجــراء األخيــر‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                   ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                                        ‫‪288‬‬\n\f289\n\f290\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":280,"source_page_end":290,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"d6e17f743f84930a6c199caeb996fcae96a3bcabd27da488ae958caa77680592","normalized_text_hash":"85c4d0b634acebe206afeba90595d4d228cf6fd018eb7ec5b22fe037e0971db0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p280-34203552"},{"id":"9c78da28-cd28-52c2-ac2d-88b672578c7e","document_type":"judgment","category":"judicial","subcategory":"general","title":"-1قول جالل الدين السيوطي »:الشبهة ال تسقط التعزير» (األشباه والنظائر( )205/1طبعة مكتبة نزار الباز) .","document_number":"3341010","case_number":"33539297","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/09/12","year":"1434","subject":"-1قول جالل الدين السيوطي »:الشبهة ال تسقط التعزير» (األشباه والنظائر( )205/1طبعة مكتبة نزار الباز) .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3341010:‬تاريخه‪1433/09/12 :‬هـ‬\n                   ‫رقم الدعوى‪33539297:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 3426836‬تاريخه‪1434/02/20:‬هـ‬\n\n\n‫مقاومــة قــوات الشــرطة ‪ ،‬حيــازة ســاح نــاري ‪ ،‬تهديــد باســتخدام ســاح‬\n‫نــاري ‪ ،‬عــدم ثبــوت اإلدانــة ‪ ،‬وجــود ســوابق قضائيــة ‪ ،‬الشــبهة ال تســقط‬\n                                   ‫التعزيــر ‪ ،‬التعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n‫‪ -1‬قول جالل الدين الســيوطي‪ »:‬الشــبهة ال تســقط التعزير» (األشــباه‬\n                                 ‫والنظائــر(‪ )205/1‬طبعــة مكتبــة نزار الباز) ‪.‬‬\n‫‪ -2‬قــول ابــن جنيم‪»:‬التعزيــر يثبــت مــع الشــبهة ولــذا قالــوا يثبــت مبــا‬\n‫يثبــت بــه املــال ويجــري فيــه احللــف ويقضــى فيــه بالنكــول» (األشــباه‬\n                             ‫والنظائــر ص‪ 130‬طبعــة دار الكتــب العلميــة)‪.‬‬\n\n\n\n\n‫جــرى توجيــه االتهــام مــن املدعــي العــام للمدعــى عليــه بالهــروب مــن‬\n‫رجــال األمــن وإشــهار الســاح عليهــم والتســتر علــى مرافقــه الهــارب مــن‬\n‫رجــال األمــن وطلــب إثبــات مــا أســند إليــه وإيقــاع العقوبــة التعزيريــة عليه‬\n‫حيــث اشــتبهت الدوريــة األمنيــة بســيارة واقفــة فلمــا وقفــت بجوارهــا‬\n‫هــرب فلحقتــه فترجــل منهــا القائــد والراكــب وأشــهرا ســاحهما‬\n‫للدوريــة وتســلقا ســورا وهربــا نحــو اجلبــل ‪ ،‬بتفتيــش الســيارة ظهــر‬\n‫بأنهــا مســتأجرة ‪ ،‬باســتجواب املســتأجر أجــاب بأنــه اســتأجر الســيارة‬\n\n                                                                                       ‫‪294‬‬\n\f      ‫للمدعــى عليــه وأنهــا كانــت بحوزتــه وقــت احلادثــة ‪ ،‬أقــر املدعــى عليــه‬\n      ‫بــأن الســيارة كانــت بحوزتــه وأنــه لــم يســلمها ألحــد طيلــة مــدة عقــد‬\n      ‫األجــرة ‪ ،‬طلــب مــن املدعــي العــام البينــة فقــرر بــأن بينتــه األوراق املرفقــة‬\n      ‫باملعاملــة ‪ ،‬وبعــد االطــاع علــى األوراق املرفقــة وإلنــكار املدعــى عليــه‬\n      ‫الدعــوى‪ ،‬ولتوجــه التهمــة القويــة بقيامــه بذلــك بالقرائــن اآلتيــة‪ -1:‬مــا‬\n      ‫جــاء يف محضــر القبــض مــن قيامــه بالهــروب وإشــهاره واملرافــق معــه‬\n      ‫الســاح علــى الفرقــة القابضــة‪ -2 .‬إقــرار املدعــى عليــه حتقيقــا بــأن‬\n      ‫الســيارة املشــار لهــا يف الدعــوى قــام باســتئجارها لــه ابــن عمــه وأنهــا‬\n      ‫كانــت بحوزتــه وقــت احلادثــة ولــم يســلمها ألحــد وكانــت ســليمة متامــا‬\n      ‫ملــا اســتأجرها‪ -3 .‬وجــود ســابقة مشــابهة بالهــروب مــن رجــال األمــن‬\n      ‫ومقاومتهــم ‪ ،‬عليــه وألن الشــبهة مــن موجبــات التعزيــر ‪ ،‬وتأسيســا علــى‬\n      ‫مــا تقــدم فقــد قــررت احملكمــة مــا يلــي‪ :‬أوالً‪ /‬عــدم ثبــوت إدانــة املدعــى‬\n      ‫عليــه مبــا جــاء يف دعــوى املدعــي العــام ‪ ،‬ثاني ـاً‪ /‬تعزيــر املدعــى عليــه‬\n      ‫للشــبهة بالســجن واجللــد ‪ -‬قــرر الطرفــان عــدم القناعــة ‪ -‬صــدق احلكــم‬\n                                                              ‫مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بنجــران وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بنجــران برقــم وتاريــخ ‪ 1433/08/21‬ه ـ املقيــدة باحملكمــة‬\n      ‫برقم وتاريخ ‪ 1433/08/21‬هـ ففي يوم السبت املوافق‪1433/08/24‬‬\n      ‫ه ـ افتتحــت اجللســة الســاعة ‪ 09 : 00‬بشــأن دعــوى املدعــي العــام ‪..........‬‬\n      ‫واملكلــف مبهمــة اإلشــراف علــى مكتــب االدعــاء العــام مبحاكــم‬\n\n‫‪295‬‬\n\f‫جنــران مبوجــب خطــاب رئيــس فــرع هيئــة التحقيــق واالدعــاء العــام‬\n‫مبنطقــة جنــران رقــم ‪..........‬وتاريــخ ‪1430/12/29‬ه ـ ضــد ‪..........‬‬\n‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪..........‬قائــا يف دعــواه‬\n‫عليــه إنــه حيــث ورد مبحضــر مكافحــة املخــدرات أنــه يف يــوم اجلمعة‬\n‫ـاء‬\n‫املوافــق ‪1431/8/4‬ه ـ ويف متــام الســاعة اخلامســة وعشــرين دقيقــة مسـ ً‬\n‫وأثنــاء قيــام الدوريــة بعملهــا امليدانــي يف حــي ‪..........‬باجتــاه الغــرب مت‬\n‫االشــتباه يف ســيارة نــوع ‪ ....‬زرقــاء اللــون رقــم اللوحــة ‪ ..........‬يســتقلها‬\n‫شــخصان كانــت تقــف بجــوار بقالــه علــى ميــن الطريــق باجتــاه الغــرب‬\n‫وأثنــاء الوقــوف بســيارات الفرقــة الرســمي والســيارة األخــرى للتأكــد‬\n‫مــن وضعهــا الحــظ قائــد تلــك الســيارة ســيارة الفرقــة وقــام بالهــروب‬\n‫بســرعة جنونيــة ســالك ًا طريــق فرعــي باجتــاه الشــمال داخــل ذلــك احلــي‬\n‫فتمــت متابعتــه مــن قبــل الدوريــة إلــى أن وصــل داخــل ســور منــزل ونــزل‬\n‫الســائق والراكــب وأشــهر كل منهمــا ســاحا مــن نــوع مســدس باجتــاه‬\n‫الدوريــة الرســمية والذا بالفــرار مــن علــى ســور ذلــك املنــزل باجتــاه اجلبــل‬\n‫‪ ،‬علم ـ ًا بــأن الراكــب أثنــاء متابعتهمــا كان مشــهر ًا ســاحه للخــارج‬\n‫مــن نافــذة البــاب األمامــي ‪ ،‬كمــا أنــه أثنــاء متابعتهمــا مت مالحظــة‬\n‫تلــك الســيارة وهــي تنحــرف جلهــة اليســار حتتــك يف ســور أحــد املنــازل‬\n‫بالرفــرف األميــن للســيارة ممــا أدى حلــدوث تلفيــات بهــا ‪ ،‬ونظــر ًا لوجــود‬\n‫جتمهــر مــن ســكان احلــي مت نقــل الســيارة ملقــر اإلدارة وتفتيشــها ولــم‬\n‫يتــم العثــور علــى شــيء مــن املمنوعــات ‪ ،‬وعثــر داخــل الــدرج علــى عقــد‬\n‫إيجــار للســيارة املذكــورة أعــاه واتضــح مــن خاللــه بأنهــا مؤجــرة‬\n                                                                   ‫للمدعــو ‪...........‬‬\n‫وورد باحملضــر املعــد مــن قبــل وحــدة البحــث مبركــز شــرطة ‪..........‬‬\n\n\n                                                                                          ‫‪296‬‬\n\f      ‫أنــه بتاريــخ ‪1433/5/1‬ه ـ بنــاء علــى كتــاب رئيــس وحــدة البحــث رقــم‬\n      ‫بــدون وتاريــخ ‪1433/5/1‬ه ـ بشــأن طلــب البحــث عــن ‪..........‬اتضــح‬\n      ‫أنــه يتواجــد يف شــعبة الســجن العــام بنجــران علــى إثــر قضيــة جنائيــة‪.‬‬\n      ‫وبســماع أقــوال ‪........../‬أفــاد بأنــه قــام باســتئجار الســيارة املذكــورة‬\n      ‫أعــاه ل‪ ..........‬لقــرب زواج أختــه وعــدم وجــود ســيارة لديــه وأنــه ال يعلــم‬\n      ‫عمــا حصــل ‪ .‬وبســماع أقــوال املتهــم ‪.......... /‬أفــاد بأنــه كانــت معــه‬\n                                     ‫ســيارة إيجــار اســتأجرها لــه ابــن عمــه ‪...........‬‬\n      ‫وباســتجوابه أفــاد بــأن الســيارة ‪ .....‬زرقــاء اللــون رقــم اللوحــة‪..........‬‬\n      ‫قــام باســتئجارها لــه ابــن عمــه املدعــو‪ ..........‬لوجــود زواج أختــه يف تلــك‬\n      ‫الفتــرة وكان يحتــاج لســيارة وال يوجــد لديــه بطاقــة عمــل وأنــه يف يــوم‬\n      ‫اجلمعــة املوافــق ‪1431/8/4‬ه ـ وقــت وقــوع احلادثــة كانــت الســيارة‬\n      ‫بحوزتــه ومفتاحهــا معــه ولــم يعطهــا ألحــد وأن الســيارة كانــت ســليمة‬\n                            ‫متام ـ ًا عندمــا اســتأجرها ولــم يكــن بهــا أي تلفيــات ‪.‬‬\n      ‫وانتهــى التحقيــق إلــى توجيــه االتهــام لـ ـ ‪.......... /‬بالهــروب مــن رجــال‬\n      ‫األمــن وإشــهار الســاح عليهــم والتســتر علــى مرافقــه الهــارب مــن رجــال‬\n                                                                                      ‫األمــن ‪.‬‬\n                                                             ‫وذلك لألدلة والقرائن التالية ‪:‬‬\n      ‫‪ -1‬إقــراره حتقيقـ ًا املنــوه عنــه واملــدون علــى ص(‪ )4‬مــن دفتــر التحقيــق‬\n      ‫املرفــق لفــة رقــم (‪ )29‬ومــا ورد بســماع أقوالــه املنــوه عنــه املــدون ص (‪3‬‬\n      ‫‪ ) 4 ،‬املرفــق لفــة رقــم (‪ )24‬بــأن الســيارة كانــت بحوزتــه وقــت وقــوع‬\n                                                      ‫احلادثــة ولــم يســتعملها أحــد غيــره ‪.‬‬\n      ‫‪ -2‬شــهادة معــدي محضــر مكافحــة املخــدرات بنجــران املنــوه عنــه‬\n                                                                ‫املرفــق لفــة رقــم (‪.)10 ، 9‬‬\n\n\n‫‪297‬‬\n\f‫‪ -3‬وجــود ســابقتني لديه(مقاومــة رجــال األمــن والهــروب مــن نقطــة‬\n‫التفتيــش) قريبــة مــن الوصــف اجلرمــي ‪ ،‬همــا قرينــة علــى ســوء ســلوكه‬\n                                                                       ‫اإلجرامــي‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املتهــم وهــو بكامــل أهليتــه املعتبــرة شــرع ًا‬\n‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات إدانتــه مبــا أســند‬\n‫إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره وتــردع غيــره و التشــديد‬\n‫عليــه لقــاء محاولــة اعتدائــه علــى رجــال األمــن اســتناد ًا لتعميــم صاحــب‬\n‫الســمو امللكــي النائــب الثانــي لرئيــس مجلــس الــوزراء وزيــر الداخليــة‬\n‫رقــم ‪ 36717/2/5/1‬و تاريــخ ‪1431/6/11‬ه ـ و التشــديد عليــه كذلك‬\n‫لقــاء تعــدد ســوابقه التــي لــم تردعــه عقوباتهــا اســتناد ًا لتعميــم نائــب‬\n‫وزيــر الداخليــة رقــم ( ) و تاريــخ ‪1429/8/23‬هـ ـ ‪ .‬هــذه دعــواي وبعــرض‬\n‫الدعــوى علــى املدعــى عليــه قــال مــا ذكــره املدعــي العــام يف دعــواه غيــر‬\n‫ا هكــذا أجــاب ثــم جــرى منــي ســؤال املدعــي‬        ‫صحيــح جملــة وتفصي ـ ً‬\n‫العــام هــل لديــك بينــة علــى مــا جــاء يف دعــواك فقــال ال يوجــد لــدي‬\n‫بينــة ســوى مــا جــاء يف الئحــة الدعــوى ثــم جــرى منــي تصفــح األوراق‬\n‫واالطــاع علــى أقــوال املدعــى عليــه حتقيق ـ ًا املدونــة علــى ص(‪ )4‬مــن‬\n‫دفتــر التحقيــق املرفــق علــى لفــة رقــم (‪ )29‬و املدونــة علــى ص (‪، 3‬‬\n‫‪ ) 4‬مــن امللــف املرفــق علــى لفــة رقــم (‪ )24‬كمــا جــرى منــي االطــاع‬\n‫علــى شــهادة معــدي محضــر مكافحــة املخــدرات بنجــران املرفــق‬\n‫علــى لفــة رقــم (‪ )10 ، 9‬وللتأمــل ودراســة القضيــة رفعــت اجللســة إلــى‬\n‫يــوم األحــد املوافــق ‪1433/8/25‬ه ـ الســاعة العاشــرة وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1433/08/24‬ه ـ الســاعة ‪ 09:30‬احلمــد هلل وحــده وبعــد ففــي يــوم‬\n\n\n                                                                                     ‫‪298‬‬\n\f      ‫األحد املوافق‪ 1433/08/25‬هـ افتتحت اجللســة الســاعة ‪ 08:00‬وفيها‬\n      ‫حضــر املدعــى عليــه وبعــد التأمــل والدراســة وبنــاء علــى مــا ســبق مــن‬\n      ‫الدعــوى واإلجابــة و حيــث إن املدعــى عليــه قــد أنكــر هروبــه مــن فرقــة‬\n      ‫مكافحــة املخــدرات بالســيارة التــي كانــت بحوزته مــن ‪ .....‬زرقاء اللون‬\n      ‫رقــم لوحتهــا ‪..........‬وإشــهاره الســاح عليهــم و تســتره علــى الشــخص‬\n      ‫املرافــق معــه ولتوجــه التهمــة القويــة عليــه فيمــا أنكــره املؤيــدة بالقرائــن‬\n      ‫اآلتيــة ‪ -1 :‬مــا جــاء يف محضــر القبــض املتضمــن قيــام قائــد ســيارة مــن‬\n      ‫نــوع ‪ ......‬زرقــاء اللــون رقــم لوحتهــا ‪ ..........‬بالهــروب مــن فرقــة مكافحــة‬\n      ‫املخــدرات و وإشــهاره هــو واملرافــق معــه ســاح مــع نــوع مســدس باجتــاه‬\n      ‫الدوريــة الرســمية ‪ -2‬إقــرار املدعــى عليــه حتقيقـ ًا املتضمــن بأن الســيارة‬\n      ‫املشــار إليهــا قــام باســتئجارها لــه ابــن عمــه املدعــو ‪ ..........‬وأنــه يف يــوم‬\n      ‫اجلمعــة املوافــق ‪1431/8/4‬ه ـ وقــت وقــوع احلادثــة كانــت الســيارة‬\n      ‫بحوزتــه ومفتاحهــا معــه ولــم يســلمها ألي شــخص وأن الســيارة كانــت‬\n      ‫ســليمة متام ـ ًا عندمــا اســتأجرها ولــم يكــن بهــا أي تلفيــات ‪ -3‬كــون‬\n      ‫املدعــى عليــه مــن أربــاب الســوابق ولديــه ســابقة يف الهــروب مــن رجــال‬\n      ‫األمــن وســابقة يف مقاومتهــم وملــا كان مــن املقــرر فقه ـ ًا أن التعزيــر ال‬\n      ‫يســقط بالشــبهة قــال جــال الديــن الســيوطي رحمــه اهلل ‪ « :‬الشــبهة‬\n      ‫ال تســقط التعزيــر « ( األشــباه والنظائــر ‪ ،‬ص ‪ )162‬ويقــول ابــن جنيــم‬\n      ‫رحمــه اهلل ‪ « :‬التعزيــر يثبــت مــع الشــبهة ولــذا قالــوا يثبــت مبــا يثبــت بــه‬\n      ‫املــال ويجــري فيــه احللــف ويقضــى فيــه بالنكــول « ( األشــباه والنظائــر‬\n      ‫‪ ،‬ص ‪ )157‬و تأسيسـ ًا علــى جميــع مــا ســبق فقــد قــررت مــا يأتــي أو ًال ‪:‬‬\n      ‫لــم يثبــت لــدي إدانــة املدعــى عليــه مبــا جــاء يف دعــوى املدعــي العــام ثانيـ ًا‬\n      ‫‪ :‬تعزيــره وذلــك بســجنه ملــدة ســنة واحــدة تبــدأ اعتبــار ًا مــن تاريــخ إدخالــه‬\n\n\n‫‪299‬‬\n\f‫الســجن وجلــده خمســن جلــده علنـ ًا تكــرر عليــه ســت مــرات بــن كل‬\n‫مــرة وأخــرى مــدة ال تقــل عــن أســبوعني لقــاء توجــه التهمــة القويــة عليــه‬\n‫بارتكابــه مــا نســب إليــه هــذا مــا ظهــر لــي و بــه حكمــت وبعــرض‬\n‫احلكــم علــى املدعــى عليــه لــم يقنــع بــه وطلــب رفــع احلكــم حملكمــة‬\n‫االســتئناف فأجبتــه لطلبــه وأفهمتــه باســتالم نســخة احلكــم بعــد عشــرة‬\n‫أيــام وتقــدمي الئحــة اعتراضيــة خــال ثالثــن يومــا مــن التاريــخ احملــدد ال‬\n‫ســتالم نســخة احلكــم كمــا قــرر املدعــي العــام اعتراضــه علــى احلكــم‬\n‫بــدون الئحــة وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1433/08/25‬ه ـ الســاعة ‪ 08:30‬احلمــد هلل‬\n‫وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق القضايــا‬\n‫اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة بنجــران برقــم وتاريــخ ‪/1/17‬‬\n‫‪1434‬ه ـ املرفــق بهــا القــرار الصــادر مــن فضيل ــة القاضــي باحملكمــة‬\n‫الشــيخ ‪.......... /‬برقــم وتاريــخ ‪1433/9/12‬ه ـ اخلــاص بدعــوى املدعي‬\n‫العــام ض ـ ـ ـ ـ ــد ‪.......... /‬يف قضيــة ( الهــروب مــن رجــال األمــن وإشــهار‬\n‫الســاح عليهــم والتســتر علــى مرافقــه الهــارب مــن رجــال األمــن ) علــى‬\n‫الصفــة املوضحــة يف القــرار املتضمــن حكــم فضيلتــه مبــا هــو مــدون‬\n‫ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة تقــررت‬\n‫املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                                                ‫وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                      ‫‪300‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-64